window.BOOK={"title":"Barron's Essential Words for the TOEFL","lessons":[{"lesson":1,"words":[{"word":"abroad","def_lines":[],"pos":"adv","definition":"to or in another country","forms":[],"synonyms":["overseas","internationally"],"examples":["Louis Armstrong often traveled abroad.","Living abroad can be an educational experience."],"lesson":1,"id":"1-1"},{"word":"abrupt","def_lines":[],"pos":"adj","definition":"quick; without warning","forms":[{"pos":"adv","word":"abruptly"},{"pos":"n","word":"abruptness"}],"synonyms":["sudden"],"examples":["There was an abrupt change in the weather.","After the incident everyone left abruptly."],"lesson":1,"id":"1-2"},{"word":"acceptable","def_lines":[],"pos":"adj","definition":"allowable or satisfactory","forms":[{"pos":"v","word":"accept"},{"pos":"adv","word":"acceptably"},{"pos":"n","word":"acceptability"},{"pos":"adj","word":"accepting"}],"synonyms":["permissible"],"examples":["The idea was acceptable to everyone.","The registrar accepted more applicants than he should have."],"lesson":1,"id":"1-3"},{"word":"acclaim","def_lines":[],"pos":"n","definition":"enthusiastic approval; applause","forms":[{"pos":"adj","word":"acclaimed"},{"pos":"n","word":"acclamation"}],"synonyms":["praise"],"examples":["Isaac Stern has won acclaim abroad.","Acclaimed authors often win Pulitzer Prizes."],"lesson":1,"id":"1-4"},{"word":"actually","def_lines":[],"pos":"adv","definition":"being in existence, real or factual","forms":[{"pos":"adj","word":"actual"}],"synonyms":["truly"],"examples":["They were actually very good soccer players.","The actual time allotted to complete the test is two hours."],"lesson":1,"id":"1-5"},{"word":"adverse","def_lines":[],"pos":"adj","definition":"displeasing, objectionable, or bad","forms":[{"pos":"adv","word":"adversely"},{"pos":"n","word":"adversity"},{"pos":"n","word":"adversary"}],"synonyms":["unfavorable"],"examples":["Adverse weather conditions made it difficult to play the game.","His indecision adversely affected his job performance."],"lesson":1,"id":"1-6"},{"word":"advice","def_lines":[],"pos":"n","definition":"a recommendation given by someone not associated with the problem or situation","forms":[{"pos":"v","word":"advise"},{"pos":"adj","word":"advisable"},{"pos":"n","word":"advisability"}],"synonyms":["suggestion"],"examples":["Good advice is hard to find.","It is not advisable to stay up late the day before a test."],"lesson":1,"id":"1-7"},{"word":"attractive","def_lines":[],"pos":"adj","definition":"calling attention to; pleasing; creating interest; pretty","forms":[{"pos":"v","word":"attract"},{"pos":"n","word":"attraction"},{"pos":"n","word":"attractiveness"},{"pos":"adv","word":"attractively"}],"synonyms":["appealing"],"examples":["The idea of working four, ten-hour work days was attractive to the employees.","The major attraction of the show was a speech by the president."],"lesson":1,"id":"1-8"},{"word":"autonomous","def_lines":[],"pos":"adj","definition":"by itself; with no association","forms":[{"pos":"adv","word":"autonomously"}],"synonyms":["independent"],"examples":["Mexico became an autonomous state in 1817.","Although working closely with the government, all businesses function autonomously."],"lesson":1,"id":"1-9"},{"word":"chronic","def_lines":[],"pos":"adj","definition":"always present; continual","forms":[{"pos":"adv","word":"chronically"}],"synonyms":["constant"],"examples":["The author’s chronic headache prevented her from finishing the chapter.","He is chronically late to class."],"lesson":1,"id":"1-10"},{"word":"disapproval","def_lines":[],"pos":"n","definition":"the act of disagreeing; not giving approval","forms":[{"pos":"v","word":"disapprove"},{"pos":"adv","word":"disapprovingly"}],"synonyms":["objection"],"examples":["Their disapproval of the plan caused the experiment to be abandoned.","The students disapproved of the plan of study."],"lesson":1,"id":"1-11"},{"word":"disruptive","def_lines":[],"pos":"adj","definition":"causing confusion and interruption","forms":[{"pos":"v","word":"disrupt"},{"pos":"n","word":"disruption"},{"pos":"adv","word":"disruptively"}],"synonyms":["disturbing"],"examples":["Frequent questions during lectures can be disruptive.","The storm caused a disruption in bus service."],"lesson":1,"id":"1-12"},{"word":"haphazardly","def_lines":[],"pos":"adv","definition":"having no order or pattern; by chance","forms":[{"pos":"adj","word":"haphazard"},{"pos":"n","word":"haphazardness"}],"synonyms":["arbitrarily","carelessly"],"examples":["It was obvious that the house was built haphazardly.","Susan completed the assignment in a haphazard way."],"lesson":1,"id":"1-13"},{"word":"persistent","def_lines":[],"pos":"adj","definition":"continuous; refusing to give up; firm in action or decision","forms":[{"pos":"v","word":"persist"},{"pos":"n","word":"persistence"},{"pos":"adv","word":"persistently"}],"synonyms":["constant"],"examples":["The attorney’s persistent questioning weakened the witness.","Her persistence earned her a spot on the team."],"lesson":1,"id":"1-14"},{"word":"postpone","def_lines":[],"pos":"v","definition":"to change to a later time; to delay","forms":[{"pos":"adj","word":"postponable"},{"pos":"n","word":"postponement"}],"synonyms":["reschedule"],"examples":["The referees decided to postpone the soccer match.","The postponement of the meeting upset the impatient club members."],"lesson":1,"id":"1-15"},{"word":"valid","def_lines":[],"pos":"adj","definition":"producing a desired result based on truths or facts","forms":[{"pos":"n","word":"validity"},{"pos":"adv","word":"validly"}],"synonyms":["convincing"],"examples":["The students had a valid reason for missing class.","The professor questioned the validity of the test results."],"lesson":1,"id":"1-16"},{"word":"withdraw","def_lines":[],"pos":"v","definition":"to remove, take out, or take back","forms":[{"pos":"n","word":"withdrawal"}],"synonyms":["extract"],"examples":["The player withdrew from the competition.","Gloria had to make a withdrawal from her savings to pay tuition."],"lesson":1,"id":"1-17"}],"matching":[{"n":1,"word":"withdraw","options":["extract","describe","copy","convince"],"answer":0},{"n":2,"word":"autonomous","options":["independent","sudden","international","abrupt"],"answer":0},{"n":3,"word":"chronic","options":["famous","visible","constant","ordinary"],"answer":2},{"n":4,"word":"attractive","options":["appealing","adverse","arbitrary","perfect"],"answer":0},{"n":5,"word":"disapproval","options":["attraction","attention","objection","persistence"],"answer":2},{"n":6,"word":"haphazardly","options":["suddenly","secretly","carelessly","constantly"],"answer":2},{"n":7,"word":"constant","options":["disruption","acceptable","abrupt","persistent"],"answer":3},{"n":8,"word":"valid","options":["attractive","convincing","normal","abrupt"],"answer":1},{"n":9,"word":"unfavorably","options":["attractively","haphazardly","acceptably","adversely"],"answer":3},{"n":10,"word":"postpone","options":["respond","reschedule","assert","reveal"],"answer":1}],"tests":[{"n":1,"passage":"A customs union is an organization of autonomous countries that agree that international trade between member states is free of restrictions. They place a tariff or other restriction on products entering the customs union from nonmember states. One of the best-known customs unions is the European Union, or EU.","prompt":"The word autonomous in the passage is closest in meaning to","options":["massive","acclaimed","prosperous","independent"],"answer":3,"target":"autonomous"},{"n":2,"passage":"The search to hide natural body odors led to the discovery and use of musk. Musk is a scent used in perfumes. It is obtained from the sex glands of the male musk deer, a small deer native to the mountainous regions of the Himalayas. The odor of musk, penetrating and persistent, is believed to act as an aphrodisiac. In animals, musk serves the functions of defining territory, providing recognition, and attracting mates.","prompt":"The word persistent in the passage is closest in meaning to","options":["attractive","disruptive","constant","pleasant"],"answer":2,"target":"persistent"},{"n":3,"passage":"Until the late ninteenth century all rubber was extracted haphazardly from trees found in the jungles of South America. It was expensive and the supply was uncertain. However, during the 1860s the idea of transporting rubber trees to the British colonies in Asia was conceived. This led to the larger-scale cultivation of rubber trees on organized plantations.","prompt":"The word haphazardly in the passage is closest in meaning to","options":["carelessly","secretly","constantly","dangerously"],"answer":0,"target":"haphazardly"},{"n":4,"passage":"Some animals’ coloration uses bold, disruptive markings to scare predators. Other animals have color patterns that blend with their surroundings. Such coloration serves for protection, to attract mates, or to distract enemies. Called cryptic coloration, it uses the animals’ living place, habits, and means of defense. Cryptic coloration may blend an animal so well with its environment that it is virtually invisible.","prompt":"The word disruptive in the passage is closest in meaning to","options":["disturbing","distinctive","brilliant","unfavorable"],"answer":0,"target":"disruptive"},{"n":5,"passage":"Cognitive approaches to therapy assume that emotional disorders are the result of irrational beliefs or perceptions. The mind may interpret an event as scary or calming, happy or sad. The emotionally disordered person may perceive adverse events as personal failures. Cognitive psychotherapies seek to make the patient aware of the irrationality of this perception and to substitute more rational evaluations of such events.","prompt":"The word adverse in the passage is closest in meaning to","options":["monotonous","threatening","inoffensive","unfavorable"],"answer":3,"target":"adverse"},{"n":6,"passage":"Increasingly, authorities are uneasy about teenagers who drive while talking on the telephone. For many, phone use and driving are perfectly compatible; others are more easily distracted, especially while listening to music. The growing number of accidents associated with phone use also supports this claim. Many communities now disapprove of these phones so much that they have forbidden anyone of any age to use them while driving.","prompt":"In stating that many communities now disapprove of these phones, the author means that they","options":["fully endorse their popularity.","condemn or oppose their use.","favor their use only by adults.","agree to their unrestricted use."],"answer":1,"target":""},{"n":7,"passage":"Fans are used to circulate air in rooms and buildings, and for cooling and drying people, materials, or products. Even though air circulated by a fan is comforting, no fan actually cools the air. Only devices such as air conditioners can affect changes in air temperature.","prompt":"The word actually in the passage is closest in meaning to","options":["legitimately","factually","truly","essentially"],"answer":2,"target":"actually"},{"n":8,"passage":"Tornadoes strike in many areas of the world, but nowhere are they as frequent or as devastating as in the United States. A vast “tornado belt” embraces large portions of the Great Plains of the United States and the southeastern portion of the country. Tornadoes pose the greatest threats to these areas, which are especially vulnerable to abrupt changes in weather conditions.","prompt":"The word abrupt in the passage is closest in meaning to","options":["sudden","vivid","sharp","direct"],"answer":0,"target":"abrupt"},{"n":9,"passage":"For women in the 1920s, freedom in dress reflected their new freedom to take up careers. Only a small percentage of women pursued such opportunities, but the revolutionary change affected the types of clothes worn by most women. For example, trousers became acceptable attire for almost all activities. This milestone in the fashion world favored more stylish and comfortable clothing instead of more formal modes of dress.","prompt":"The word acceptable in the passage is closest in meaning to","options":["usable","endurable","believable","permissible"],"answer":3,"target":"acceptable"},{"n":10,"passage":"The National Film Board of Canada was established in 1939 to produce films that reflect Canadian life and thought, and to distribute them both domestically and abroad. By winning awards from film festivals around the world, it has earned international acclaim for the artistic and technical excellence of its work.","prompt":"The word acclaim in the passage is closest in meaning to","options":["fascination","praise","acceptance","attraction"],"answer":1,"target":"acclaim"}]},{"lesson":2,"words":[{"word":"advantage","def_lines":[],"pos":"n","definition":"something that may help one to be successful or to gain something","forms":[{"pos":"adv","word":"advantageously"},{"pos":"adj","word":"advantageous"}],"synonyms":["benefit"],"examples":["Is there any advantage in arriving early?","He was advantageously born into a rich family."],"lesson":2,"id":"2-1"},{"word":"advent","def_lines":[],"pos":"n","definition":"the coming or appearance of something","forms":[],"synonyms":["arrival"],"examples":["With the advent of computers, many tasks have been made easier.","The newspapers announced the advent of the concert season."],"lesson":2,"id":"2-2"},{"word":"agile","def_lines":[],"pos":"adj","definition":"able to move in a quick and easy way","forms":[{"pos":"adv","word":"agilely"},{"pos":"n","word":"agileness"},{"pos":"n","word":"agility"}],"synonyms":["nimble"],"examples":["Deer are very agile animals.","She moved agilely across the stage."],"lesson":2,"id":"2-3"},{"word":"albeit","def_lines":[],"pos":"conj","definition":"in spite of the facts, regardless of the fact","forms":[],"synonyms":["although"],"examples":["His trip was successful, albeit tiring.","Albeit difficult at times, speaking another language is rewarding."],"lesson":2,"id":"2-4"},{"word":"appealing","def_lines":[],"pos":"adj","definition":"attractive or interesting","forms":[{"pos":"v","word":"appeal"},{"pos":"n","word":"appeal"},{"pos":"adv","word":"appealingly"}],"synonyms":["alluring"],"examples":["Working abroad is appealing to many people.","Through his speeches, the candidate appealed to the voters."],"lesson":2,"id":"2-5"},{"word":"celebrated","def_lines":[],"pos":"adj","definition":"acclaimed; well-known and popular","forms":[],"synonyms":["renowned"],"examples":["The celebrated pianist will be giving a concert this weekend.","San Francisco is celebrated for its multicultural makeup."],"lesson":2,"id":"2-6"},{"word":"circumvent","def_lines":[],"pos":"v","definition":"to go around; avoid","forms":[{"pos":"n","word":"circumvention"}],"synonyms":["evade"],"examples":["The hacker attempted to circumvent the computer’s security system.","Circumvention of the freshman math requirement is possible."],"lesson":2,"id":"2-7"},{"word":"collide","def_lines":[],"pos":"v","definition":"to hit one object against another with violent force; to be in opposition","forms":[{"pos":"n","word":"collision"}],"synonyms":["crash"],"examples":["The collision caused major damage to both cars.","Moon craters were caused when large asteroids collided with the moon."],"lesson":2,"id":"2-8"},{"word":"contemporary","def_lines":[],"pos":"adj","definition":"modern, up-to-date, or (n.) a person living at the same time as another person","forms":[{"pos":"n","word":"contemporary"}],"synonyms":["current"],"examples":["Contemporary architecture makes very good use of space.","Cervantes was a contemporary of Shakespeare."],"lesson":2,"id":"2-9"},{"word":"distribute","def_lines":[],"pos":"v","definition":"to divide among people or to give out","forms":[{"pos":"n","word":"distribution"}],"synonyms":["dispense"],"examples":["Many publishers distribute their newspapers directly to homes in their area.","The distribution of seeds is very quick with this new machine."],"lesson":2,"id":"2-10"},{"word":"encourage","def_lines":[],"pos":"v","definition":"to promote, help, or support","forms":[{"pos":"n","word":"encouragement"},{"pos":"n","word":"encourager"},{"pos":"adv","word":"encouragingly"},{"pos":"adv","word":"encouraging"}],"synonyms":["stimulate"],"examples":["The government cut taxes in order to encourage spending.","The professor gave each student the encouragement that was needed to learn the material."],"lesson":2,"id":"2-11"},{"word":"energetic","def_lines":[],"pos":"adj","definition":"full of life, action, or power","forms":[{"pos":"n","word":"energy"},{"pos":"adv","word":"energetically"}],"synonyms":["vigorous"],"examples":["Sam hasn’t been as energetic as he usually is.","There’s a lot of energy in these batteries."],"lesson":2,"id":"2-12"},{"word":"frail","def_lines":[],"pos":"adj","definition":"weak in health or in body","forms":[{"pos":"n","word":"frailty"}],"synonyms":["fragile"],"examples":["The frail wings of the newborn bird could not lift it off the ground.","One of the frailties of human beings is laziness."],"lesson":2,"id":"2-13"},{"word":"heyday","def_lines":[],"pos":"n","definition":"a high point of success or abundance","forms":[],"synonyms":["pinnacle"],"examples":["Many settlers became rich during the heyday of the California gold rush of the 1800s.","We are living in the heyday of digital communications."],"lesson":2,"id":"2-14"},{"word":"myth","def_lines":[],"pos":"n","definition":"an invented story or idea","forms":[{"pos":"adj","word":"mythological"},{"pos":"n","word":"mythology"}],"synonyms":["legend"],"examples":["Throughout history myths were created in an attempt to explain many common natural occurrences.","Mythology is the study of legends and fables."],"lesson":2,"id":"2-15"},{"word":"refine","def_lines":[],"pos":"v","definition":"to make pure; to improve","forms":[{"pos":"n","word":"refinement"},{"pos":"adj","word":"refined"}],"synonyms":["perfect (verb)"],"examples":["Factories must refine oil before it can be used as fuel.","A squirt of lime juice is the perfect refinement to cola."],"lesson":2,"id":"2-16"},{"word":"worthwhile","def_lines":[],"pos":"adj","definition":"value in doing something","forms":[],"synonyms":["rewarding"],"examples":["It was worthwhile waiting ten hours in line for the tickets.","It’s worthwhile to prepare for the TOEFL."],"lesson":2,"id":"2-17"}],"matching":[{"n":1,"word":"circumvent","options":["celebrate","attract","evade","appeal"],"answer":2},{"n":2,"word":"advantage","options":["benefit","persistence","nimbleness","allure"],"answer":0},{"n":3,"word":"fragile","options":["modern","famous","refined","frail"],"answer":3},{"n":4,"word":"contemporary","options":["timing","current","well-known","perfect"],"answer":1},{"n":5,"word":"appealing","options":["refined","encouraging","alluring","popular"],"answer":2},{"n":6,"word":"renowned","options":["unknown","celebrated","adverse","disapprove"],"answer":1},{"n":7,"word":"worthwhile","options":["rewarding","acceptable","agile","permitted"],"answer":0},{"n":8,"word":"vigorous","options":["attractive","beautiful","energetic","advantageous"],"answer":2},{"n":9,"word":"refine","options":["persist","value","perfect","divide"],"answer":2},{"n":10,"word":"heyday","options":["agreement","acclaim","postponement","pinnacle"],"answer":3}],"tests":[{"n":1,"passage":"Over the years, investigators have evaluated the local folklore of areas where sightings of the celebrated Abominable Snowman have been reported. The same scientists have collected physical evidence, such as footprints, body parts, and photographs, but this evidence remains unconvincing. In 1960 the renowned mountaineer Sir Edmund Hillary of New Zealand conducted an investigation of the reports of the creature, but found no evidence of its existence.","prompt":"The word celebrated in the passage is closest in meaning to","options":["elusive","ambiguous","renowned","indistinct"],"answer":2,"target":"celebrated"},{"n":2,"passage":"Exercises that demand total body involvement improve and maintain fitness. The most effective way to feel more mentally alert and energetic is to engage in aerobic activity at least three times a week for 30 minutes. Such activities may include jogging, running, swimming, dancing, and fast walking.","prompt":"The word energetic in the passage is closest in meaning to","options":["vigorous","frail","agile","appealing"],"answer":0,"target":"energetic"},{"n":3,"passage":"Most people do not appreciate the importance of packaging. Packages maintain the purity and freshness of their contents and protect them from elements outside. If the contents are harmful, corrosive, or poisonous, the package must also protect the outside environment. A package must identify its contents, which facilitates distribution of the product.","prompt":"The word distribution in the passage is closest in meaning to","options":["usage","disruption","dispensing","advertising"],"answer":2,"target":"distribution"},{"n":4,"passage":"A contemporary issue among psychologists is the activation or cause of emotion, its structure or components, and its functions and consequences. Each of these aspects can be considered from a biosocial view. Generally, biosocial theory focuses on the neurophysiological aspects of emotions and their roles as organizers of cognition and motivators of action.","prompt":"The word contemporary in the passage is closest in meaning to","options":["current","acclaimed","contemptuous","favored"],"answer":0,"target":"contemporary"},{"n":5,"passage":"The early artists of the Hudson River school were Thomas Doughty, Asher Durand, and Thomas Cole. They found the wilderness in the Hudson River valley appealing. Although these painters studied in Europe, they first achieved a measure of success at home, and chose the common theme of the remoteness and splendor of the American interior.","prompt":"The word appealing in the passage is closest in meaning to","options":["annoying","ongoing","spectacular","alluring"],"answer":3,"target":"appealing"},{"n":6,"passage":"Recent polls suggest that fewer people see an advantage in moving to the city than they used to. There was a time when cities attracted country dwellers like powerful magnets: cities had more jobs, better schools, more services. Today, people often see pollution, crime, stress, and unemployment where they once saw opportunity. Instead of advantages, they see disadvantages in uprooting their families for the uncertainty of urban life.","prompt":"In stating that fewer people see an advantage in moving to the city, the author means that fewer people","options":["consider cities a poor option.","prefer to relocate to big cities.","take a positive view of cities.","view city life as advantageous."],"answer":3,"target":""},{"n":7,"passage":"The growing popularity of television in the 1950s marked an important turning point in the entertainment world. This development created vast new entertainment choices for people who lived within the signal areas of TV stations. Later, with the advent of satellite and cable TV, almost everyone, regardless of location, was able to experience this entertainment medium.","prompt":"The word advent in the passage is closest in meaning to","options":["dependence","allowance","explosion","arrival"],"answer":3,"target":"advent"},{"n":8,"passage":"Passerines form the dominant avian group on Earth today. They are regarded as the most highly evolved of all birds and occur in abundance. Humans have long enjoyed passerines for their songs and their almost infinite variety of colors, patterns, and behavioral traits. Many passerines are considered to be quite agile. Among the most energetic of them is the swallow, whose small body is designed for effortless maneuvering.","prompt":"The word agile in the passage is closest in meaning to","options":["nimble","detectible","broad","fast"],"answer":0,"target":"agile"},{"n":9,"passage":"In part because seafood tends to spoil rapidly, in certain areas of the United States, shrimping is allowed only during specific predetermined seasons. For example, in Mississippi tidal waters, shrimping is allowed only between October and May. In the past, this short season made it difficult to find shrimp out of season. However, the development of freezing techniques in the 1940s encouraged the shrimping industry to expand, making it a global industry. The United States now imports shrimp from over sixty countries and shrimp can be bought at any time of the year.","prompt":"The word encouraged in the passage is closest in meaning to","options":["advanced","accepted","stimulated","wanted"],"answer":2,"target":"encouraged"},{"n":10,"passage":"Scientific disciplines, such as genetic engineering, are exploding with possibilities. As a result of new technologies and procedures to treat health conditions, new treatments for many diseases have been developed. Although the development of advanced methods will continue to change the face of healthcare, moral beliefs often collide with scientific advancements, slowing down the progress of some healthcare treatments.","prompt":"The phrase collide with in the passage is closest in meaning to","options":["are in opposition to","are absent from","are associated with","are concerned about"],"answer":0,"target":"collide with"}]},{"lesson":3,"words":[{"word":"alter","def_lines":[],"pos":"v","definition":"to change or make different","forms":[{"pos":"v","word":"altered"},{"pos":"n","word":"alteration"},{"pos":"adj","word":"alterable"},{"pos":"adv","word":"alterably"}],"synonyms":["modify"],"examples":["Will the storm alter its course and miss the coast?","Gloria hasn’t altered her plans to return to school."],"lesson":3,"id":"3-1"},{"word":"analyze","def_lines":[],"pos":"v","definition":"to study something carefully; to separate into parts for study","forms":[{"pos":"v","word":"analyzed"},{"pos":"n","word":"analysis"}],"synonyms":["examine"],"examples":["Scientists must analyze problems thoroughly.","Analysis of the substance confirms the presence of nitrogen."],"lesson":3,"id":"3-2"},{"word":"ancient","def_lines":[],"pos":"adj","definition":"something from a long time ago; very old","forms":[],"synonyms":["old"],"examples":["Archaeologists analyze ancient civilizations.","Dave found an ancient Roman coin."],"lesson":3,"id":"3-3"},{"word":"annoying","def_lines":[],"pos":"adj","definition":"a slight bother; disturbing to a person","forms":[{"pos":"n","word":"annoyance"},{"pos":"v","word":"annoy"},{"pos":"adv","word":"annoyingly"}],"synonyms":["bothersome"],"examples":["Mosquitos can be an annoying part of a vacation at the beach.","She annoyed her parents by coming home late."],"lesson":3,"id":"3-4"},{"word":"anticipate","def_lines":[],"pos":"v","definition":"to think about or prepare for something ahead of time","forms":[{"pos":"adj","word":"anticipatory"},{"pos":"n","word":"anticipation"}],"synonyms":["predict"],"examples":["No one can anticipate the results of the games.","They planned their vacation with anticipation."],"lesson":3,"id":"3-5"},{"word":"ascertain","def_lines":[],"pos":"v","definition":"to discover; find out","forms":[{"pos":"adj","word":"ascertainable"},{"pos":"adv","word":"ascertainably"},{"pos":"n","word":"ascertainment"}],"synonyms":["determine"],"examples":["I tried to ascertain if he was telling the truth.","The jury made a decision based on its ascertainment of the facts."],"lesson":3,"id":"3-6"},{"word":"conform","def_lines":[],"pos":"v","definition":"to follow established rules or patterns of behavior","forms":[{"pos":"n","word":"conformity"},{"pos":"n","word":"conformist"}],"synonyms":["adapt"],"examples":["You must conform to the rules or leave the club.","She has always been a conformist."],"lesson":3,"id":"3-7"},{"word":"enrich","def_lines":[],"pos":"v","definition":"to make rich; to make something of greater value","forms":[{"pos":"n","word":"enrichment"},{"pos":"adj","word":"enriching"}],"synonyms":["enhance"],"examples":["The fine arts enrich our lives.","The discovery of oil was an enrichment for the country."],"lesson":3,"id":"3-8"},{"word":"intensify","def_lines":[],"pos":"v","definition":"to make stronger in feeling or quality","forms":[{"pos":"n","word":"intensity"},{"pos":"adj","word":"intense"},{"pos":"adj","word":"intensive"},{"pos":"adv","word":"intensely"},{"pos":"adv","word":"intensively"}],"synonyms":["heighten"],"examples":["The importance of the test will sometimes intensify the nervousness of the students.","The chess match was played with great intensity."],"lesson":3,"id":"3-9"},{"word":"intolerable","def_lines":[],"pos":"adj","definition":"difficult or painful to experience; not able to accept different ways of thought or behavior","forms":[{"pos":"n","word":"intolerance"},{"pos":"adv","word":"intolerably"},{"pos":"adv","word":"intolerantly"},{"pos":"adj","word":"intolerant"}],"synonyms":["unbearable"],"examples":["Any opposition to the rules is intolerable.","His boss was intolerant of his tardiness."],"lesson":3,"id":"3-10"},{"word":"ongoing","def_lines":[],"pos":"adj","definition":"continuing","forms":[],"synonyms":["current"],"examples":["The tutoring project is an ongoing program of the school.","Maintaining roads is an ongoing job."],"lesson":3,"id":"3-11"},{"word":"potential","def_lines":[],"pos":"n","definition":"an ability, happening, or opportunity that has not occurred or been developed","forms":[{"pos":"adj","word":"potential"},{"pos":"adv","word":"potentially"}],"synonyms":["possibility"],"examples":["The medical students have shown great potential to become doctors.","Small space heaters are a potential fire hazard."],"lesson":3,"id":"3-12"},{"word":"propose","def_lines":[],"pos":"v","definition":"to suggest or plan to do something","forms":[{"pos":"n","word":"proposal"},{"pos":"n","word":"proposition"},{"pos":"adj","word":"proposed"}],"synonyms":["suggest"],"examples":["The governor is going to propose new taxes.","Her proposal was well accepted."],"lesson":3,"id":"3-13"},{"word":"restore","def_lines":[],"pos":"v","definition":"to give back or bring back something; to return to the original condition","forms":[{"pos":"n","word":"restoration"},{"pos":"adj","word":"restored"}],"synonyms":["revitalize"],"examples":["He restored my confidence in him.","It is a beautiful restoration of the old table."],"lesson":3,"id":"3-14"},{"word":"staple","def_lines":[],"pos":"n","definition":"a fundamental element or principal part of something","forms":[],"synonyms":["essential (n.)"],"examples":["Milk, bread, and eggs are staples of most American grocery stores.","The main staple of Asian diets is rice."],"lesson":3,"id":"3-15"},{"word":"turbulent","def_lines":[],"pos":"adj","definition":"to be in a disordered, disturbed or unstable condition","forms":[{"pos":"n","word":"turbulence"},{"pos":"adv","word":"turbulently"}],"synonyms":["chaotic"],"examples":["The plane flew though an area of turbulence.","The turbulent crowd insisted on a meeting with the prime minister."],"lesson":3,"id":"3-16"},{"word":"vital","def_lines":[],"pos":"adj","definition":"of great importance; full of life","forms":[{"pos":"n","word":"vitality"},{"pos":"adv","word":"vitally"}],"synonyms":["indispensable"],"examples":["Money is vital to the success of the program.","His intense vitality was easily observable."],"lesson":3,"id":"3-17"}],"matching":[{"n":1,"word":"indispensable","options":["abrupt","abroad","vital","frail"],"answer":2},{"n":2,"word":"restore","options":["appeal","revitalize","attract","disrupt"],"answer":1},{"n":3,"word":"conform","options":["annoy","divide","encourage","adapt"],"answer":3},{"n":4,"word":"turbulent","options":["chaotic","intolerant","annoying","adverse"],"answer":0},{"n":5,"word":"ascertain","options":["delay","render","determine","assert"],"answer":2},{"n":6,"word":"potential","options":["attraction","possibility","anticipation","persistence"],"answer":1},{"n":7,"word":"staple","options":["essential","advice","fable","agreement"],"answer":0},{"n":8,"word":"enrich","options":["alter","dispense","disrupt","enhance"],"answer":3},{"n":9,"word":"unbearable","options":["inspiring","unfavorable","intolerable","ancient"],"answer":2},{"n":10,"word":"proposal","options":["question","attention","benefit","suggestion"],"answer":3}],"tests":[{"n":1,"passage":"The point at which pain becomes intolerable is known as the pain perception threshold. Studies have found this point to be similar among different social and cultural groups. However, the pain tolerance threshold varies significantly among these groups. A stoical, unemotional response to pain may be seen as a sign of braveness in certain cultural or social environments. However, this behavior can also mask the seriousness of an injury to an examining physician.","prompt":"The word intolerable in the passage is closest in meaning to","options":["elusive","altered","intensified","unbearable"],"answer":3,"target":"intolerable"},{"n":2,"passage":"Nutritional additives are utilized to restore nutrients lost during production, to enrich certain foods in order to correct dietary deficiencies, or to add nutrients to food substitutes. Nowadays, vitamins are commonly added to many foods in order to increase their nutritional value. For example, vitamins A and D are added to dairy and cereal products, and several of the B vitamins are added to cereals.","prompt":"The word enrich in the passage is closest in meaning to","options":["alter","enhance","produce","restore"],"answer":1,"target":"enrich"},{"n":3,"passage":"In modern manufacturing production facilities that produce equipment sensitive to environmental contamination, a dust-free working area with strict temperature and humidity controls is of vital importance. Seamless plastic walls and ceilings, external lighting, a continuous flow of dust-free air, and daily cleaning are features of this “clean room.” Workers wear special clothing, including head coverings. When entering this room, they pass through a “shower” to remove contaminants.","prompt":"The word vital in the passage is closest in meaning to","options":["indispensable","lively","extreme","dubious"],"answer":0,"target":"vital"},{"n":4,"passage":"Human populations are classified in terms of genetically transmitted traits. For groups that have lived for generations in certain locations, research illustrates the long-term genetic effects of environmental factors such as climate and diet. Ongoing investigations track the history of evolution and its genetic changes and help to explain the origin of genetically determined diseases and their long-term influence.","prompt":"The word ongoing in the passage is closest in meaning to","options":["current","thorough","proposed","temporary"],"answer":0,"target":"ongoing"},{"n":5,"passage":"In the 1890s, a rising generation of young antiorganization leaders came on the political scene. These leaders transformed the art and practice of politics in the United States, by exercising strong leadership and by bringing about institutional changes that helped revitalize political democracy. Most important was their achievement of economic and social objectives, such as legislation to prevent child labor, and accident insurance systems to provide compensation to injured workers.","prompt":"The word revitalize in the passage is closest in meaning to","options":["intensify","establish","reform","restore"],"answer":3,"target":"revitalize"},{"n":6,"passage":"There are more than 100 types or species of chameleon. A member of the lizard family, the chameleon lives in countries as diverse as Madagascar, Spain, and Sri Lanka. It is thought to change color to conform to its surroundings, but that is rarely true. While changes do occur with changes in light or temperature, especially when the chameleon is frightened, its new color rarely matches its immediate surroundings.","prompt":"In stating that the chameleon’s color conforms to its surroundings, the author means that it","options":["differs from the color of its setting.","contrasts with its surroundings.","clashes with the colors around it.","looks the same as its environment."],"answer":3,"target":""},{"n":7,"passage":"Infrared light emission photographs are particularly helpful to astronomers. The composition and temperature of heavenly bodies can often be determined by analysis of photos taken with a camera that is sensitive to infrared light emissions. Using infrared detectors, astronomers can observe cooler celestial objects than they can with optical devices, since infrared radiation is less affected by interstellar dust than is light.","prompt":"The word analysis in the passage is closest in meaning to","options":["intensification","examination","dispersion","production"],"answer":1,"target":"analysis"},{"n":8,"passage":"Working environments in which loud noise is frequent can be harmful to the employee. Aside from simply being annoying, the most measurable physical effect of noise pollution is damage to hearing. This may be either temporary or permanent and may cause disruption of normal activities. In work areas where noise is a problem, care should be taken to protect the ears with earplugs.","prompt":"The word annoying in the passage is closest in meaning to","options":["difficult","ongoing","bothersome","refined"],"answer":2,"target":"annoying"},{"n":9,"passage":"The construction of shelter, found among the first stable human societies about 5,000 years ago, is considered to be among the most important of all ancient human activities. The systematic placement of groups of housing marked a momentous cultural transition toward the formation of towns. It generated new needs and resources and was accompanied by a significant increase in technological innovation.","prompt":"The word ancient in the passage is closest in meaning to","options":["old","actual","distinct","dated"],"answer":0,"target":"ancient"},{"n":10,"passage":"Seeking to take advantage of new economic trends of the late 1800s, Manitoba’s leaders made important changes in economic policies. These changes, which anticipated new directions in economic development of the region, took advantage of the unique business attributes of the province. During the early 1900s, these policies gave the province an advantage over other prairie provinces.","prompt":"The word anticipated in the passage is closest in meaning to","options":["encouraged","analyzed","modified","predicted"],"answer":3,"target":"anticipated"}]},{"lesson":4,"words":[{"word":"ambiguous","def_lines":[],"pos":"adj","definition":"of unclear meaning; something that can be understood in more than one way","forms":[{"pos":"adv","word":"ambiguously"},{"pos":"n","word":"ambiguity"}],"synonyms":["vague"],"examples":["The men received an ambiguous message from their boss.","Her letter was full of ambiguities."],"lesson":4,"id":"4-1"},{"word":"arbitrary","def_lines":[],"pos":"adj","definition":"an action or decision made with little thought, order, or reason","forms":[{"pos":"adv","word":"arbitrarily"},{"pos":"n","word":"arbitrariness"}],"synonyms":["haphazard"],"examples":["Her choice of clothing seemed arbitrary.","The teacher arbitrarily decided to give the class a test."],"lesson":4,"id":"4-2"},{"word":"assert","def_lines":[],"pos":"v","definition":"to express or defend oneself strongly; to state positively","forms":[{"pos":"adv","word":"assertively"},{"pos":"n","word":"assertiveness"},{"pos":"n","word":"assertion"},{"pos":"adj","word":"assertive"}],"synonyms":["declare"],"examples":["The government asserted its control over the banking system.","The company president is an assertive individual."],"lesson":4,"id":"4-3"},{"word":"astounding","def_lines":[],"pos":"adj","definition":"very surprising","forms":[{"pos":"v","word":"astound"},{"pos":"adv","word":"astoundingly"}],"synonyms":["astonishing"],"examples":["The scientists made an astounding discovery.","The fans were astounded by their team’s success."],"lesson":4,"id":"4-4"},{"word":"astute","def_lines":[],"pos":"adj","definition":"very intelligent, smart, clever","forms":[{"pos":"adj","word":"astutely"},{"pos":"n","word":"astuteness"}],"synonyms":["perceptive"],"examples":["He was an astute worker, finishing in half the time it took the others to finish.","They astutely determined that there would be no chance to finish on time."],"lesson":4,"id":"4-5"},{"word":"concur","def_lines":[],"pos":"v","definition":"to have the same opinion or draw the same conclusion","forms":[{"pos":"n","word":"concurrence"}],"synonyms":["agree"],"examples":["The director concurred with the conclusions of the committee’s report.","Do you concur with the details of the business plan?"],"lesson":4,"id":"4-6"},{"word":"deceptively","def_lines":[],"pos":"adv","definition":"making something appear true or good when it is false or bad","forms":[{"pos":"adj","word":"deceptive"},{"pos":"v","word":"deceive"},{"pos":"n","word":"deception"}],"synonyms":["misleadingly"],"examples":["The magician deceptively made the rabbit disappear.","Richard deceived Joe about the cost of the coat."],"lesson":4,"id":"4-7"},{"word":"designate","def_lines":[],"pos":"v","definition":"to specify, name, or select to do a task; to indicate","forms":[{"pos":"n","word":"designation"},{"pos":"n","word":"designator"}],"synonyms":["assign"],"examples":["The president designated the vice president to represent him at the meeting.","The designated driver drove every one home after the party."],"lesson":4,"id":"4-8"},{"word":"determined","def_lines":[],"pos":"adj","definition":"strong in one’s opinion, firm in conviction, to find out","forms":[{"pos":"n","word":"determination"},{"pos":"v","word":"determine"}],"synonyms":["resolute"],"examples":["They were determined to go to graduate school.","The judge determined that the man was lying."],"lesson":4,"id":"4-9"},{"word":"elicit","def_lines":[],"pos":"v","definition":"to get the facts or draw out the truth","forms":[{"pos":"n","word":"elicitation"}],"synonyms":["extract"],"examples":["A lawyer will elicit all the facts necessary to prove her case.","Elicitation of the truth can be difficult at times."],"lesson":4,"id":"4-10"},{"word":"embody","def_lines":[],"pos":"v","definition":"to be a good example of a concept or idea","forms":[{"pos":"n","word":"embodiment"}],"synonyms":["exemplify"],"examples":["The constitution is an embodiment of American ideals.","Charlotte embodies all of the qualities of a good leader."],"lesson":4,"id":"4-11"},{"word":"instigate","def_lines":[],"pos":"v","definition":"to cause a conflict or argument","forms":[{"pos":"n","word":"instigator"},{"pos":"adj","word":"instigative"},{"pos":"adv","word":"instigatively"}],"synonyms":["initiate"],"examples":["No one knew who had instigated the demonstration.","Dissatisfaction with government policies instigated the revolution."],"lesson":4,"id":"4-12"},{"word":"mundane","def_lines":[],"pos":"adj","definition":"common or routine","forms":[{"pos":"adv","word":"mundanely"},{"pos":"n","word":"mundaneness"},{"pos":"n","word":"mundanity"}],"synonyms":["ordinary"],"examples":["The student’s mundane summer job frustrated her.","His mother asked him to do all the mundane household chores."],"lesson":4,"id":"4-13"},{"word":"petition","def_lines":[],"pos":"v","definition":"to make a request","forms":[{"pos":"n","word":"petition"}],"synonyms":["appeal"],"examples":["Canada petitioned the United Nations to consider its case.","The student’s petition was denied."],"lesson":4,"id":"4-14"},{"word":"relinquish","def_lines":[],"pos":"v","definition":"to give up control","forms":[{"pos":"n","word":"relinquishment"}],"synonyms":["abdicate"],"examples":["The troubled executive relinquished her control of the company.","The relinquishment of his claim to the building will allow the building to be sold."],"lesson":4,"id":"4-15"},{"word":"resilient","def_lines":[],"pos":"adj","definition":"strong enough to recover from difficulty or disease","forms":[{"pos":"adv","word":"resiliently"},{"pos":"n","word":"resilience"}],"synonyms":["tenacious"],"examples":["She has a resilient personality and will soon feel better.","The doctor was surprised by his patient’s resilience."],"lesson":4,"id":"4-16"},{"word":"tempt","def_lines":[],"pos":"v","definition":"to make it attractive to do something, usually something not good","forms":[{"pos":"adv","word":"temptingly"},{"pos":"n","word":"temptation"},{"pos":"adj","word":"tempting"}],"synonyms":["entice"],"examples":["The idea of getting rich quickly tempted him to invest his life savings.","Desserts are more tempting when one is on a diet."],"lesson":4,"id":"4-17"}],"matching":[{"n":1,"word":"appeal","options":["enrich","assert","petition","restore"],"answer":2},{"n":2,"word":"mundane","options":["celebrated","ordinary","astounding","alterable"],"answer":1},{"n":3,"word":"instigate","options":["initiate","empower","intensify","restore"],"answer":0},{"n":4,"word":"elicit","options":["declare","withdraw","conform","extract"],"answer":3},{"n":5,"word":"abdicate","options":["relinquish","alter","encourage","heighten"],"answer":0},{"n":6,"word":"misleadingly","options":["abruptly","deceptively","progressively","truly"],"answer":1},{"n":7,"word":"resolute","options":["determined","perfect","renown","perceptive"],"answer":0},{"n":8,"word":"resilient","options":["bothersome","vital","unbearable","tenacious"],"answer":3},{"n":9,"word":"embody","options":["exemplify","entice","notice","enrich"],"answer":0},{"n":10,"word":"vague","options":["intolerable","adverse","beautiful","ambiguous"],"answer":3}],"tests":[{"n":1,"passage":"The creation and analysis of optical illusions involve mathematical and geometric principles, such as the proportionality between the areas of similar figures. Optical illusions and their effects are often created through careful physical attributes, such as a nonstandard use of perspective, distorted angles, deceptive shading, unusual juxtaposition, and color effects.","prompt":"The word deceptive in the passage is closest in meaning to","options":["elusive","misleading","altered","ambiguous"],"answer":1,"target":"deceptive"},{"n":2,"passage":"The Seneca Falls Convention, held in 1848, started the woman’s suffrage movement in the United States. A “Declaration of Sentiments,” which called upon women to organize and to petition for their rights, was passed. However, one controversial resolution, calling for the right of women to vote, narrowly passed. The ridicule of that provision of the Declaration caused many backers of women’s rights to withdraw their support later on.","prompt":"The word petition in the passage is closest in meaning to","options":["vote","demand","appeal","persist"],"answer":2,"target":"petition"},{"n":3,"passage":"Space law is concerned with the proper uses of outer space. The most important treaty of space laws was the 1967 Outer Space Treaty. The participants who crafted the treaty concluded that the moon and all other celestial bodies were to be free for exploration and use by all nations. They also concurred that the use of weapons of mass destruction was to be forbidden in space.","prompt":"The word concurred in the passage is closest in meaning to","options":["assumed","agreed","anticipated","observed"],"answer":1,"target":"concurred"},{"n":4,"passage":"It is a common misconception that the U.S. Congress has the constitutional power to legislate nearly anything for the general welfare. The Constitution gives Congress many powers, but it does not give Congress the power to legislate freely for the general welfare. In many instances, the Congress cannot force the states to abide, although it has the power to tempt states by the offer of money. Congress may try to cause the states to do something by means of offers of subsidies or grants, but it cannot compel them to accept the incentives.","prompt":"The word tempt in the passage is closest in meaning to","options":["coerce","entice","solicit","persuade"],"answer":1,"target":"tempt"},{"n":5,"passage":"Due to the astounding progress of integrated-circuit technology, an enormous number of transistors can be placed onto a single integrated- circuit chip. The first commercially successful microprocessor chip had only 4,800 transistors, but the newest high-end chips now have over 700,000,000 transistors.","prompt":"The word astounding in the passage is closest in meaning to","options":["astonishing","rapid","solid","resilient"],"answer":0,"target":"astounding"},{"n":6,"passage":"Deer populations have grown dramatically in the northeast United States in the last 20 years. Many residents are happy to have deer in their communities, but many others see them as a menace. Deer often wander into traffic, cause automobile accidents, trample lawns, eat flowers, and host insects that carry disease. Therefore, many residents are determined to restrict their movements, fence them out, or even eliminate them altogether.","prompt":"In stating that many people are determined to eliminate the deer, the author means that they","options":["want to decide what to do.","support their increase.","insist on reducing them.","favor enlarging the herd."],"answer":2,"target":""},{"n":7,"passage":"The game of chess was not well organized until 1946, when the world chess governing body, FIDE, asserted its control over international play. At that time, national chess groups immediately welcomed the chance to join the new federation. However, FIDE’s authority has not been universally recognized and even today there is no general agreement as to the status of the world championship.","prompt":"The word asserted in the passage is closest in meaning to","options":["enhanced","empowered","permitted","declared"],"answer":3,"target":"asserted"},{"n":8,"passage":"Social anthropologists attempt to illustrate the social emergence and evolution of the human race and to determine differences between human social organization and that of other primates. Despite the fact that all classifications of human societies and cultures are arbitrary, they also attempt to note differences between various human societies. In spite of these difficulties, anthropologists have made great advances in the identification and grouping of human civilizations.","prompt":"The word arbitrary in the passage is closest in meaning to","options":["vague","haphazard","disputed","elusive"],"answer":1,"target":"arbitrary"},{"n":9,"passage":"The Monroe Doctrine allowed the United States to intervene in the affairs of Latin American countries in case of foreign invasion. Once the United States was designated to act on behalf of its neighbors to the south, episodes of foreign interference decreased until the 1960s, when Cuba wanted the support and economic aid of the former Union of Soviet Socialist Republics.","prompt":"The word designated in the passage is closest in meaning to","options":["authorized","accustomed","determined","tempted"],"answer":0,"target":"designated"},{"n":10,"passage":"J. Edgar Hoover was an astute professional who served as Director of the FBI for 48 years. A resilient and determined government official, Hoover’s tenure spanned one of the most important eras of modern U.S. history. His policies helped to shape and create what has now become a highly respected modern investigative organization.","prompt":"The word astute in the passage is closest in meaning to","options":["acclaimed","celebrated","perceptive","eminent"],"answer":2,"target":"astute"}]},{"lesson":5,"words":[{"word":"baffle","def_lines":[],"pos":"v","definition":"to confuse to a point at which no progress can be made","forms":[{"pos":"adj","word":"baffling"},{"pos":"n","word":"bafflement"}],"synonyms":["puzzle"],"examples":["The causes of many harmful diseases have baffled doctors for centuries.","That was a baffling question."],"lesson":5,"id":"5-1"},{"word":"bear","def_lines":[],"pos":"v","definition":"to produce, to carry; to show; to endure","forms":[{"pos":"adv","word":"bearably"},{"pos":"adj","word":"bearable"}],"synonyms":["yield"],"examples":["This orchard bears many fine harvests of apples.","Although stock prices declined, losses have been bearable for most investors."],"lesson":5,"id":"5-2"},{"word":"blur","def_lines":[],"pos":"v","definition":"to make something difficult to see","forms":[{"pos":"adj","word":"blurred"},{"pos":"n","word":"blur"}],"synonyms":["cloud"],"examples":["The rain blurred everyone’s view of the valley.","The whole accident is just a blur in my mind."],"lesson":5,"id":"5-3"},{"word":"brilliant","def_lines":[],"pos":"adj","definition":"intensely bright or colorful; intelligent","forms":[{"pos":"adv","word":"brilliantly"},{"pos":"n","word":"brilliance"}],"synonyms":["radiant"],"examples":["Einstein was a brilliant thinker.","She brilliantly produced a solution to the problem."],"lesson":5,"id":"5-4"},{"word":"caution","def_lines":[],"pos":"v","definition":"to alert someone of danger, warn someone to take care or pay attention to something","forms":[{"pos":"adj","word":"cautious"},{"pos":"adj","word":"cautionary"},{"pos":"adv","word":"cautiously"},{"pos":"n","word":"caution"}],"synonyms":["warn"],"examples":["The officer cautioned the motorist to slow down.","They entered into the negotiations cautiously."],"lesson":5,"id":"5-5"},{"word":"delicate","def_lines":[],"pos":"adj","definition":"needing careful treatment; sensitive, easily broken","forms":[{"pos":"adv","word":"delicately"}],"synonyms":["fragile"],"examples":["Because of its controversial nature, it was a challenge to discuss such a delicate issue in public.","You must handle the antique delicately."],"lesson":5,"id":"5-6"},{"word":"enhance","def_lines":[],"pos":"v","definition":"to increase in a positive way, such as in value, power, or beauty","forms":[{"pos":"n","word":"enhancement"},{"pos":"adj","word":"enhanced"}],"synonyms":["strengthen"],"examples":["Passing the exam should enhance your chances of being admitted to college.","The computer enhanced our productivity."],"lesson":5,"id":"5-7"},{"word":"facilitate","def_lines":[],"pos":"v","definition":"to make easier; to ease the progress of","forms":[{"pos":"adv","word":"facilitative"}],"synonyms":["assist"],"examples":["His careful planning facilitated the completion of the project.","Good teaching strategies facilitate student learning."],"lesson":5,"id":"5-8"},{"word":"incessant","def_lines":[],"pos":"adj","definition":"nonstop, continual, or never-ending","forms":[{"pos":"adv","word":"incessantly"}],"synonyms":["constant"],"examples":["The woman’s incessant talking disturbed everyone watching the movie.","The dogs’ incessant barking kept the whole neighborhood up all night."],"lesson":5,"id":"5-9"},{"word":"in conjunction with","def_lines":[],"pos":"prep","definition":"ph. in addition to, alongside","forms":[],"synonyms":["along with"],"examples":["Exercise, in conjunction with a nourishing diet, contributes to a healthy lifestyle.","The architects planned the building in conjunction with the engineers."],"lesson":5,"id":"5-10"},{"word":"intrigue","def_lines":[],"pos":"v","definition":"to interest greatly","forms":[{"pos":"adj","word":"intriguing"},{"pos":"adv","word":"intriguingly"},{"pos":"n","word":"intrigue"}],"synonyms":["fascinate"],"examples":["He was intrigued by the acclaim that he received.","The intriguing question baffled historians."],"lesson":5,"id":"5-11"},{"word":"obstruct","def_lines":[],"pos":"v","definition":"to prevent movement, progress, or success","forms":[{"pos":"n","word":"obstruction"},{"pos":"adj","word":"obstructive"},{"pos":"adv","word":"obstructively"}],"synonyms":["block"],"examples":["Just after the storm, downed trees obstructed many roads in the community.","A huge building obstructed the ocean view from the apartment."],"lesson":5,"id":"5-12"},{"word":"persuade","def_lines":[],"pos":"v","definition":"to change a belief or behavior by argument or reason","forms":[{"pos":"adv","word":"persuasively"},{"pos":"adj","word":"persuasive"},{"pos":"n","word":"persuasion"}],"synonyms":["convince"],"examples":["They couldn’t persuade their critics to see their point of view.","John presented a persuasive argument for his salary increase."],"lesson":5,"id":"5-13"},{"word":"recompense","def_lines":[],"pos":"n","definition":"a repayment or reward for a deed","forms":[{"pos":"adv","word":"recompensable"},{"pos":"v","word":"recompense"}],"synonyms":["compensation"],"examples":["The knight received gold as recompense for saving the kingdom.","His boss assured him that he’d be recompensed for his extra efforts."],"lesson":5,"id":"5-14"},{"word":"shed","def_lines":[],"pos":"v","definition":"to throw off naturally; to give out","forms":[],"synonyms":["discard"],"examples":["In order to grow, crabs must shed their shells.","The experiments shed no new information on the cause of the disease."],"lesson":5,"id":"5-15"},{"word":"unique","def_lines":[],"pos":"adj","definition":"to be the only one of a kind; special","forms":[{"pos":"adv","word":"uniquely"},{"pos":"n","word":"uniqueness"}],"synonyms":["rare"],"examples":["He was presented with a unique opportunity to attend the conference.","His style of writing is uniquely his own."],"lesson":5,"id":"5-16"},{"word":"well-suited","def_lines":[],"pos":"adj","definition":"to be complementary or appropriate; a good match","forms":[],"synonyms":["compatible"],"examples":["The design of the house is well-suited to its surroundings.","The experienced principal was well-suited for the job of superintendent of schools."],"lesson":5,"id":"5-17"}],"matching":[{"n":1,"word":"incessant","options":["unique","constant","blocked","baffled"],"answer":1},{"n":2,"word":"obstruct","options":["warn","tempt","enhance","block"],"answer":3},{"n":3,"word":"intrigue","options":["fascinate","elicit","intensify","enrich"],"answer":0},{"n":4,"word":"well-suited to","options":["unique to","compatible with","enhanced with","dedicated to"],"answer":1},{"n":5,"word":"recompense","options":["pinnacle","resilience","compensation","consequence"],"answer":2},{"n":6,"word":"convince","options":["assert","persuade","restore","yield"],"answer":1},{"n":7,"word":"rare","options":["determined","warned","vague","unique"],"answer":3},{"n":8,"word":"facilitate","options":["assist","refine","alter","discard"],"answer":0},{"n":9,"word":"enhance","options":["entice","strengthen","relinquish","encourage"],"answer":1},{"n":10,"word":"puzzled","options":["valid","assertive","baffled","astute"],"answer":2}],"tests":[{"n":1,"passage":"A newborn chick uses its egg tooth to break the shell of its egg and escape from it at hatching. This toothlike structure is then shed since its only use is to help the bird break the eggshell. Some animals, such as lizards and snakes, develop a true tooth that projects outside the row of other teeth. This tooth helps adults hatch their young.","prompt":"The word shed in the passage is closest in meaning to","options":["guarded","preserved","discarded","enhanced"],"answer":2,"target":"shed"},{"n":2,"passage":"Imitation gems are usually made of glass or plastics. In recent years, an enormous array of plastics has become available for imitations, but these materials are soft and lack the clarity present in real gemstones. Therefore, they are less satisfactory for the purpose than glass. Flint glasses, containing lead oxide, have higher refractive indices and therefore possess a brilliance not found in plastics. This makes flint glasses more suitable than plastic for imitation gems.","prompt":"The word brilliance in the passage is closest in meaning to","options":["radiance","lightness","enhancement","appeal"],"answer":0,"target":"brilliance"},{"n":3,"passage":"During a shower, meteors appear to spread from a point in the sky, called the radiant. These radiant points give each shower its name. For example, the Perseids shower appears to radiate from the constellation Perseus. During the heaviest showers, 30 to 70 meteors may be seen every hour, but on unique occasions in a spectacular display, that number may be visible every second.","prompt":"The word unique in the passage is closest in meaning to","options":["intriguing","amazing","celebrated","rare"],"answer":3,"target":"unique"},{"n":4,"passage":"Sometimes, advertisers impact society by the use of advocacy ads, whose purpose is not to persuade the public to buy a product, but to change the public’s view about a specific issue. Companies use this advertising to influence public opinion. Critics say that such ads are unfairly one-sided; advertisers say that the mass media have been equally one-sided in failing to report company views.","prompt":"The word persuade in the passage is closest in meaning to","options":["convince","dissuade","solicit","encourage"],"answer":0,"target":"persuade"},{"n":5,"passage":"In the mid-1800s, gold and silver were common components of dentures. As a result, they were very expensive. However, in 1851, a process to harden the juices of certain tropical plants into rubber was discovered. This new product could be molded to a model of a patient’s mouth and artificial teeth could be made. As a result, when used in conjunction with new manufacturing methods, these molds caused the cost of dentures to fall dramatically.","prompt":"The phrase in conjunction with in the passage is closest in meaning to","options":["along with","under","throughout","within limits"],"answer":0,"target":"in conjunction with"},{"n":6,"passage":"The issue of where human life first arose has always been an intriguing question for science. Many guesses, or hypotheses, have been advanced, ranging from Asia to Europe. However, the oldest known human bones, or fossils, were discovered in East Africa in 1972. They are nearly 2 million years old. Their age was determined by measuring the age of the rocks surrounding them and comparing them to other fossils.","prompt":"In stating that the origin of human life is an intriguing question, the author means that it","options":["interests a lot of scientists.","can never be answered.","receives too much attention.","will always be a mystery."],"answer":0,"target":""},{"n":7,"passage":"The Sioux and Cheyenne peoples told outsiders not to look for gold on Indian land. Eventually, the Sioux and Cheyenne had to defend their land against a U.S. army force in the Battle of Little Bighorn. This battle, also known as “Custer’s Last Stand,” was led by General George Custer. Custer was cautioned by his advisors not to underestimate the strength of his opponent, but ignored their advice, resulting in the defeat of the U.S. force.","prompt":"The word cautioned in the passage is closest in meaning to","options":["warned","discarded","advised","convinced"],"answer":0,"target":"cautioned"},{"n":8,"passage":"Clothing and adornments used among the southwest Native American populations often reflect the social status of an individual. Body painting and tattooing are common methods used to distinguish social status. Other methods include the use of lip, ear, and nose rings in addition to bracelets, arm bands, necklaces, and head ornaments made of delicate, colorful feathers. In addition to their use as status markers, adornments are also used to enhance beauty.","prompt":"The word delicate in the passage is closest in meaning to","options":["resilient","brilliant","rare","fragile"],"answer":3,"target":"delicate"},{"n":9,"passage":"Species of alyssum are particularly suitable as edging plants for flower gardens. Alyssum is generally grayish with yellow or white flowers. One popular species is sweet alyssum, a perennial that grows up to nine inches tall. The narrow, green-gray leaf of the sweet alyssum usually bears many silvery hairs.","prompt":"The word bears in the passage is closest in meaning to","options":["produces","elicits","attracts","inspires"],"answer":0,"target":"bears"},{"n":10,"passage":"In ancient times, the labyrinth was a structure composed of a complex series of passageways and chambers, probably at first designed to baffle enemies. A labyrinth either had branched paths with misleading ends, or it contained one long meandering path that led to a central end.","prompt":"The word baffle in the passage is closest in meaning to","options":["obstruct","puzzle","discard","astound"],"answer":1,"target":"baffle"}]},{"lesson":6,"words":[{"word":"chiefly","def_lines":[],"pos":"adv","definition":"the most important or most common","forms":[{"pos":"adj","word":"chief"}],"synonyms":["mostly"],"examples":["Houses are made chiefly of wood products.","Corn is the chief crop of the Midwest."],"lesson":6,"id":"6-1"},{"word":"coarse","def_lines":[],"pos":"adj","definition":"not fine or smooth; not delicate","forms":[{"pos":"adv","word":"coarsely"},{"pos":"n","word":"coarseness"}],"synonyms":["rough"],"examples":["Sandpaper is an extremely coarse material.","Wool clothing has a certain coarseness in texture."],"lesson":6,"id":"6-2"},{"word":"commonplace","def_lines":[],"pos":"adj","definition":"ordinary","forms":[],"synonyms":["frequent"],"examples":["In some parts of the world, text messaging is more commonplace than voice calling.","Female lawyers are commonplace in the United States."],"lesson":6,"id":"6-3"},{"word":"comparatively","def_lines":[],"pos":"adv","definition":"being measured or judged by comparison","forms":[{"pos":"adj","word":"comparative"},{"pos":"v","word":"compare"},{"pos":"n","word":"comparison"}],"synonyms":["relatively"],"examples":["It was comparatively easy for him to learn baseball because he had been a cricket player.","If you compare algebra and trigonometry, you’ll discover that algebra is less complex."],"lesson":6,"id":"6-4"},{"word":"complex","def_lines":[],"pos":"adj","definition":"difficult to understand or explain; having many parts","forms":[{"pos":"n","word":"complexity"}],"synonyms":["complicated"],"examples":["The businessmen astutely approached the complex production problem.","The universe has a complexity beyond comprehension."],"lesson":6,"id":"6-5"},{"word":"conventional","def_lines":[],"pos":"adj","definition":"following accepted rules or standards","forms":[{"pos":"adv","word":"conventionally"},{"pos":"n","word":"convention"}],"synonyms":["traditional"],"examples":["Professor Canfield agreed with the conventional theory about the origin of the Basque language.","To become integrated into a society, you must learn the conventions of that society."],"lesson":6,"id":"6-6"},{"word":"curious","def_lines":[],"pos":"adj","definition":"odd or strange; eager to learn","forms":[{"pos":"adv","word":"curiously"},{"pos":"n","word":"curiosity"}],"synonyms":["peculiar"],"examples":["A curious object was discovered in the remains.","Sally was curiously interested in the history of Alaska."],"lesson":6,"id":"6-7"},{"word":"emit","def_lines":[],"pos":"v","definition":"to send out; give off","forms":[{"pos":"n","word":"emission"},{"pos":"n","word":"emitter"}],"synonyms":["release"],"examples":["The raging forest fire emitted a dense, white smoke.","Modern telescopes can detect the faintest light emitted by distant stars."],"lesson":6,"id":"6-8"},{"word":"exceedingly","def_lines":[],"pos":"adv","definition":"very; to an unusual degree","forms":[{"pos":"v","word":"exceed"},{"pos":"n","word":"excess"},{"pos":"adj","word":"excessive"},{"pos":"adv","word":"excessively"}],"synonyms":["extremely"],"examples":["In tropical zones, it is exceedingly hot and humid.","It is not safe to exceed the speed limit."],"lesson":6,"id":"6-9"},{"word":"exclusively","def_lines":[],"pos":"adv","definition":"no one else; nothing else; not shared with others","forms":[{"pos":"adj","word":"exclusive"},{"pos":"n","word":"exclusion"},{"pos":"v","word":"exclude"}],"synonyms":["restrictively"],"examples":["This room is used exclusively by the faculty.","They excluded everyone under 21 from the contest."],"lesson":6,"id":"6-10"},{"word":"extinguish","def_lines":[],"pos":"v","definition":"to bring about the end of something","forms":[{"pos":"adj","word":"extinguishable"},{"pos":"n","word":"extinguishment"}],"synonyms":["terminate"],"examples":["The firefighters quickly extinguished the flames.","Modern medicine has extinguished many previously serious illnesses."],"lesson":6,"id":"6-11"},{"word":"immense","def_lines":[],"pos":"adj","definition":"extremely large","forms":[{"pos":"adv","word":"immensely"},{"pos":"n","word":"immensity"}],"synonyms":["massive"],"examples":["From the mountaintop you can see the immense valley.","She was immensely interested in the idea of teaching a foreign language."],"lesson":6,"id":"6-12"},{"word":"rigid","def_lines":[],"pos":"adj","definition":"not easy to bend; firm; inflexible","forms":[{"pos":"adv","word":"rigidly"}],"synonyms":["stiff"],"examples":["The teacher was very rigid in his ideas about class attendance.","He adhered rigidly to his opinions about marriage."],"lesson":6,"id":"6-13"},{"word":"routinely","def_lines":[],"pos":"adv","definition":"regularly; usually done","forms":[{"pos":"adj","word":"routine"},{"pos":"n","word":"routine"}],"synonyms":["ordinarily"],"examples":["She routinely gets a physical examination.","It is routine for students to become homesick at times."],"lesson":6,"id":"6-14"},{"word":"stamina","def_lines":[],"pos":"n","definition":"lasting physical or mental strength","forms":[],"synonyms":["endurance"],"examples":["The Olympic runner demonstrated incredible stamina.","The horse lacked the stamina to win the race."],"lesson":6,"id":"6-15"},{"word":"sufficiently","def_lines":[],"pos":"adv","definition":"enough; in a satisfying manner","forms":[{"pos":"n","word":"sufficiency"},{"pos":"adj","word":"sufficient"},{"pos":"v","word":"suffice"}],"synonyms":["adequately"],"examples":["Jenny is sufficiently mature to make her own decisions.","Her income is sufficient for her needs."],"lesson":6,"id":"6-16"},{"word":"visibly","def_lines":[],"pos":"adv","definition":"can be seen *power of imagination or wisdom, especially with regard to the future","forms":[{"pos":"adj","word":"visible"},{"pos":"n","word":"vision*"},{"pos":"v","word":"view"},{"pos":"adj","word":"visionary*"}],"synonyms":["noticeably"],"examples":["Ken was visibly upset about his performance evaluation.","Stars are more visible on a clear fall evening."],"lesson":6,"id":"6-17"}],"matching":[{"n":1,"word":"stiff","options":["delicate","agile","rigid","astute"],"answer":2},{"n":2,"word":"traditional","options":["arbitrary","astounding","conventional","frequent"],"answer":2},{"n":3,"word":"extinguish","options":["terminate","discard","emit","deceive"],"answer":0},{"n":4,"word":"curious","options":["annoying","brilliant","peculiar","enhanced"],"answer":2},{"n":5,"word":"adequately","options":["sufficiently","deceptively","intensely","amazingly"],"answer":0},{"n":6,"word":"immense","options":["abrupt","massive","ongoing","complicated"],"answer":1},{"n":7,"word":"exceedingly","options":["resiliently","extremely","assertively","resolutely"],"answer":1},{"n":8,"word":"visibly","options":["noticeably","frequently","persuasively","encouragingly"],"answer":0},{"n":9,"word":"stamina","options":["courage","indulgence","weakness","endurance"],"answer":3},{"n":10,"word":"restrictively","options":["exclusively","adversely","roughly","relatively"],"answer":0}],"tests":[{"n":1,"passage":"North American trade patterns offer remarkable contrasts. Canada has a small population but with vast resources and high productivity. It has a low home consumption and depends on foreign trade more than any other developed country on the North American continent. The United States, on the other hand, has an immense domestic market and the highest per capita consumption of goods in the world. It depends mainly on trade within its national borders.","prompt":"The word immense in the passage is closest in meaning to","options":["massive","successful","prominent","significant"],"answer":0,"target":"immense"},{"n":2,"passage":"By the end of the 20th century, computers had greatly influenced the way in which we produced and printed documents. Letters and reports could be easily prepared on personal computers, because the user could see on the monitor what the text would look like when printed. The task of writing was made even easier with the advent of more advanced word processing programs that checked spelling and grammar before printing. A wide range of fonts became available to the public, and their number was far greater than that of conventional printing processes. Thanks to progress in laser printing technology, the quality of text printed by laser printer soon surpassed that of commercially typeset material.","prompt":"The word conventional in the passage is closest in meaning to","options":["restricted","available","traditional","competing"],"answer":2,"target":"conventional"},{"n":3,"passage":"Contour mapping is the process by which a map is formed by constructing lines of equal values of that property from available data points. For example, a topographic map reveals the relief of an area by means of contour lines that represent elevation. In addition to topography, there are examples of geophysical, geochemical, meteorological, sociological, and other variables that are routinely mapped by the method. The availability of plotting devices has permitted mapping by computer, which reduces the effect of human bias on the final product.","prompt":"The word routinely in the passage is closest in meaning to","options":["ordinarily","effectively","sluggishly","efficiently"],"answer":0,"target":"routinely"},{"n":4,"passage":"Motion-picture technology is a curious blend of the old and the new. In much of the equipment, state-of-the-art digital electronics may be working with a mechanical system invented in 1895. Moreover, the technology of motion pictures is based not only on the invention of still photography but also on a combination of several more or less independent technologies: camera and projector design, film manufacture and processing, sound recording and reproduction, and lighting and light measurement.","prompt":"The word curious in the passage is closest in meaning to","options":["productive","peculiar","coveted","appealing"],"answer":1,"target":"curious"},{"n":5,"passage":"The durable surfacing of a road, airstrip, or similar area is known as a pavement. Its primary function is to transmit loads to the sub-base and underlying soil. Modern flexible pavements contain sand and gravel or crushed stone. These are compacted with a binder of bituminous material, such as asphalt or tar. Such a pavement demonstrates enough plasticity to absorb shocks. Rigid pavements are made of concrete, composed of coarse and fine aggregate and portland cement, and usually reinforced with steel rod or mesh.","prompt":"The word rigid in the passage is closest in meaning to","options":["strong","stiff","pliable","complex"],"answer":1,"target":"rigid"},{"n":6,"passage":"Research indicates that Internet use may cause a person’s attention span to shorten. Some experts estimate that the habitual user’s span can drop to as little as that of a goldfish, roughly nine seconds. Of course, attention depends as much on content as delivery. It is comparatively easy to switch off some images, but comparatively hard to abandon others. For example, computer games usually hold a user’s attention longer than advertising.","prompt":"In stating that it is comparatively easy to switch off some images, the author means that","options":["all images or games are equally engaging.","some have less of a hold on a user’s attention.","some even lengthen a user’s attention span.","users never vary in their Internet preferences."],"answer":1,"target":""},{"n":7,"passage":"Water is a powerful solvent that acts as a catalyst for many reactions. It also stores heat and cold well. In terms of its composition, water has an unusually high boiling and freezing point. It also shows unusual volume changes with temperature. Water is easily the most complex of all common substances that are single chemical compounds.","prompt":"The word complex in the passage is closest in meaning to","options":["renown","peculiar","nimble","intricate"],"answer":3,"target":"complex"},{"n":8,"passage":"Over several decades, scientists and engineers have confronted the issue of pollutants emitted by motor vehicles. Some of the waste products of the combustion process include carbon dioxide, nitrogen gas, and water vapor. Though these by-products are not really harmful, many scientists theorize that carbon dioxide may contribute to the problem of global warming. However, the combustion process also produces carbon monoxide, nitrogen oxides, and hydrocarbons, all of which are known threats to human health. Due to government regulations that set emission standards, motor vehicle companies have significantly reduced the amount of harmful gases that are discharged by installing catalytic converters in vehicles.","prompt":"The word emitted in the passage is closest in meaning to","options":["released","created","converted","maintained"],"answer":0,"target":"emitted"},{"n":9,"passage":"The cotton gin, invented by Eli Whitney, was commonplace on many nineteenth-century farms. Although patented in 1794, the ingenious design was imitated so much by others that Whitney gained only a modest financial reward from his simple invention. The cotton gin soon revolutionized farming in many parts of the South.","prompt":"The word commonplace in the passage is closest in meaning to","options":["noticeable","standard","celebrated","refined"],"answer":1,"target":"commonplace"},{"n":10,"passage":"The delicate look and feel of silk are deceptive. It is a strong, natural fiber, ranked in strength with synthetic nylon. To the naked eye, it appears to be smooth, but under the microscope, cultivated silk fiber looks coarse. It is the coolest of hot-weather fabrics, and it can absorb up to 30 percent of its weight in moisture without feeling wet.","prompt":"The word coarse in the passage is closest in meaning to","options":["stiff","strong","rough","refined"],"answer":2,"target":"coarse"}]},{"lesson":7,"words":[{"word":"attribute","def_lines":[],"pos":"n","definition":"Something that is thought to belong to a person or thing; a quality by which something is identified","forms":[{"pos":"v","word":"attribute"},{"pos":"adj","word":"attributable"}],"synonyms":["characteristic"],"examples":["His ability to work on a team is one of his many outstanding attributes.","The forest fire was attributed to careless campers who abandoned a live campfire."],"lesson":7,"id":"7-1"},{"word":"brash","def_lines":[],"pos":"adj","definition":"confident or aggressive; lacking regard for consequences","forms":[{"pos":"adv","word":"brashly"},{"pos":"n","word":"brashness"}],"synonyms":["reckless"],"examples":["The brash young man made many poor business decisions.","Lucy’s brashness often got her into trouble at school."],"lesson":7,"id":"7-2"},{"word":"clarify","def_lines":[],"pos":"v","definition":"to make more easily understood; to make clear","forms":[{"pos":"n","word":"clarification"}],"synonyms":["explain"],"examples":["Chapter 2 in the textbook clarifies the process of osmosis.","A clarification of the government’s position on this matter is necessary."],"lesson":7,"id":"7-3"},{"word":"conceal","def_lines":[],"pos":"v","definition":"to prevent from being seen or discovered","forms":[{"pos":"n","word":"concealment"}],"synonyms":["hide"],"examples":["The students concealed their feelings about the course.","His concealment of the evidence made his case more difficult to prove."],"lesson":7,"id":"7-4"},{"word":"confirm","def_lines":[],"pos":"v","definition":"to make certain; give support","forms":[{"pos":"adj","word":"confirmed"},{"pos":"n","word":"confirmation"}],"synonyms":["prove"],"examples":["The director confirmed that the meeting would be on the tenth.","We have just received confirmation of your reservation on the flight to Los Angeles."],"lesson":7,"id":"7-5"},{"word":"convenient","def_lines":[],"pos":"adj","definition":"easy to reach; near; suitable to one’s needs","forms":[{"pos":"adv","word":"conveniently"},{"pos":"n","word":"convenience"}],"synonyms":["practical"],"examples":["The investigator suspected that the disappearance of the evidence was too convenient to be accidental.","For the convenience of the student body, the library is located in a central location."],"lesson":7,"id":"7-6"},{"word":"core","def_lines":[],"pos":"adj","definition":"the central or most important part","forms":[{"pos":"n","word":"core"}],"synonyms":["chief"],"examples":["The core curriculum consists of courses that are required of all students.","They are loyal to the core."],"lesson":7,"id":"7-7"},{"word":"critical","def_lines":[],"pos":"adj","definition":"very serious or unsafe; finding fault","forms":[{"pos":"v","word":"critique"},{"pos":"n","word":"criticism"},{"pos":"n","word":"critic"},{"pos":"adv","word":"critically"}],"synonyms":["dangerous"],"examples":["It is critical to follow the directions for the experiment exactly as the instructor indicates.","The runner accepted criticism from his coach very well."],"lesson":7,"id":"7-8"},{"word":"discrepancy","def_lines":[],"pos":"n","definition":"a difference between things that should be similar or equal","forms":[],"synonyms":["inconsistency"],"examples":["The discrepancy in her experiment data led her to believe that she had made a mistake.","There is usually a discrepancy between how coffee smells and how it tastes."],"lesson":7,"id":"7-9"},{"word":"distort","def_lines":[],"pos":"v","definition":"to change from the original shape or condition, usually in an unnatural way","forms":[{"pos":"adj","word":"distorted"},{"pos":"n","word":"distortion"}],"synonyms":["deform"],"examples":["Time and space are distorted when traveling at the speed of light.","Distortion of the image from a microscope can be caused by low light."],"lesson":7,"id":"7-10"},{"word":"diverse","def_lines":[],"pos":"adj","definition":"various; distinct from others","forms":[{"pos":"adv","word":"diversely"},{"pos":"n","word":"diversity"},{"pos":"v","word":"diversify"}],"synonyms":["different"],"examples":["Freud had many diverse interests in psychology.","The diversity of life forms on the earth makes zoology an interesting area of study."],"lesson":7,"id":"7-11"},{"word":"eventually","def_lines":[],"pos":"adv","definition":"to happen at some time in the future, usually gradually","forms":[],"synonyms":["finally"],"examples":["A good education will eventually pay big dividends.","Eventually the couple will pay off their mortgage and own their house."],"lesson":7,"id":"7-12"},{"word":"prosperous","def_lines":[],"pos":"adj","definition":"successful, wealthy","forms":[{"pos":"adv","word":"prosperously"},{"pos":"v","word":"prosper"},{"pos":"n","word":"prosperity"}],"synonyms":["thriving"],"examples":["In the early 1900s, San Francisco was a prosperous city.","Bacteria prosper under the proper conditions."],"lesson":7,"id":"7-13"},{"word":"purposefully","def_lines":[],"pos":"adv","definition":"done for a special reason","forms":[{"pos":"adj","word":"purposeful"},{"pos":"adv","word":"purposely"},{"pos":"n","word":"purpose"}],"synonyms":["deliberately"],"examples":["The course syllabus was designed purposefully to be easy to follow.","He was authorized to spend the money for business purposes."],"lesson":7,"id":"7-14"},{"word":"reveal","def_lines":[],"pos":"v","definition":"to uncover; to expose","forms":[{"pos":"adv","word":"revealingly"},{"pos":"adj","word":"revealing"},{"pos":"n","word":"revelation"}],"synonyms":["disclose"],"examples":["The president revealed some of his ideas before he gave his speech.","The report made some revelations about the nature of the conflict."],"lesson":7,"id":"7-15"},{"word":"scarcely","def_lines":[],"pos":"adv","definition":"almost not","forms":[{"pos":"adj","word":"scarce"},{"pos":"n","word":"scarcity"}],"synonyms":["hardly"],"examples":["The woman scarcely spoke a word of English.","Due to a scarcity of water, a rationing plan was established."],"lesson":7,"id":"7-16"},{"word":"theoretically","def_lines":[],"pos":"adv","definition":"according to a reasoned, but not proven, point of view","forms":[{"pos":"adj","word":"theoretical"},{"pos":"n","word":"theory"},{"pos":"v","word":"theorize"}],"synonyms":["hypothetically"],"examples":["His argument was theoretically appealing, but not realistic.","Leonardo da Vinci theorized that Earth was not the center of the universe."],"lesson":7,"id":"7-17"}],"matching":[{"n":1,"word":"deform","options":["hide","distort","concur","block"],"answer":1},{"n":2,"word":"attribute","options":["advantage","alteration","clarification","characteristic"],"answer":3},{"n":3,"word":"eventually","options":["finally","soon","once","consequently"],"answer":0},{"n":4,"word":"clarify","options":["shed","enhance","explain","elicit"],"answer":2},{"n":5,"word":"brash","options":["distorted","thoughtful","reckless","deceptive"],"answer":2},{"n":6,"word":"thriving","options":["prosperous","resilient","convenient","tolerable"],"answer":0},{"n":7,"word":"inconsistency","options":["critique","discrepancy","deliberation","sufficiently"],"answer":1},{"n":8,"word":"different","options":["noticeable","diverse","conventional","curious"],"answer":1},{"n":9,"word":"hypothetically","options":["exceedingly","haphazardly","theoretically","routinely"],"answer":2},{"n":10,"word":"reveal","options":["disclose","baffle","conceal","confirm"],"answer":0}],"tests":[{"n":1,"passage":"The geologic history of Earth reveals much information about the evolution of the continents, oceans, atmosphere, and biosphere. The layers of rock at Earth’s surface contain evidence of the evolutionary processes these components underwent when each layer was formed. By studying this rock record from the beginning, it is possible to track their development through time.","prompt":"The word reveals in the passage is closest in meaning to","options":["teaches","discloses","traces","donates"],"answer":1,"target":"reveals"},{"n":2,"passage":"Day-to-day weather constitutes a major element of the environment and an important factor in human well-being and activity. Agriculture, animal husbandry, transportation, and public health and safety are all greatly influenced by weather. It is not surprising that one of humanity’s oldest environment-related interests has been to manage the weather purposefully.","prompt":"The word purposefully in the passage is closest in meaning to","options":["prosperously","eventually","exceedingly","deliberately"],"answer":3,"target":"purposefully"},{"n":3,"passage":"Illumination plays a great role in our psychological and physical well- being. Light can model objects or flatten them, reveal colors or distort them, provide a cheerful environment or a gloomy one. Glare and reflected glare can cause discomfort and reduce visibility. In addition to calculating illumination, a lighting engineer must deal with all of these problems through the choice of light sources and fixtures.","prompt":"The word distort in the passage is closest in meaning to","options":["hide","accentuate","deform","highlight"],"answer":2,"target":"distort"},{"n":4,"passage":"The different appearance of animals is chiefly superficial; the diverse variety of known forms can be assorted among only a half-dozen basic body plans. These plans are established during the embryonic stages of development and limit the size and complexity of the animals. Symmetry, number, and development of tissue, presence, and nature of body cavities, and several aspects of early development define these fundamental plans of organization.","prompt":"The word diverse in the passage is closest in meaning to","options":["recognized","acknowledged","different","critical"],"answer":2,"target":"diverse"},{"n":5,"passage":"When the settlers of the western United States abandoned their original log cabins, sod houses, and dugouts, they built small, wood-framed dwellings of one or two rooms without a basement. Rooms were usually added as prosperous families grew larger. This usually resulted in a series of large, open rooms laid end to end so that each would have an equal amount of sunlight.","prompt":"The word prosperous in the passage is closest in meaning to","options":["numerous","thriving","prominent","courageous"],"answer":1,"target":"prosperous"},{"n":6,"passage":"The medical profession is sometimes accused of being more interested in itself than the quality of care it delivers. Many patients feel they don’t get the attention they deserve; many see the profession as selfish to its core. Doctors rarely agree, as a recent survey comparing their attitudes and that of the public shows. Seventy percent of the public were disappointed in the quality of care; only 35 percent of the doctors agreed.","prompt":"In stating that the medical profession is selfish to its core, the author means that it","options":["is entirely interested only in itself.","contains a group of bad doctors.","has wide support among patients.","includes good and bad physicians."],"answer":0,"target":""},{"n":7,"passage":"Industrial cities appeared after the full development of industrial capitalism in the core nation-states of the eighteenth century. One of the features of this industrial revolution was a dramatic increase in per capita production. This increase was made possible by the improved methods of manufacturing that were adopted by factories.","prompt":"The word core in the passage is closest in meaning to","options":["chief","ancient","important","central"],"answer":0,"target":"core"},{"n":8,"passage":"The earliest complete calendars were probably based on lunar observations. But lunar years were not convenient for agricultural purposes. Therefore, to keep in step with the Sun, lunar-solar calendars were formed by adding an additional “leap” month when the observation of crops made it seem necessary. Eventually the Gregorian civil calendar, a solar calendar that is calculated without reference to the Moon, became the most popular method of measuring years.","prompt":"The word convenient in the passage is closest in meaning to","options":["useful","ideal","proper","practical"],"answer":3,"target":"convenient"},{"n":9,"passage":"Mollusks have existed for some 500 million years, and about 10,000 extinct species are known. There are 350 or more living species of cephalopods from the Mollusk family. One of these is the cuttlefish. Fossil evidence confirms that the ancient cuttlefish has existed in its present form for more than 20 million years. When we compare the modern-day cuttlefish to the ancient fossils, we see evidence that the well-developed head, the many arms, two gills, two kidneys, and three hearts of the contemporary cuttlefish were also present in the cuttlefish of long ago.","prompt":"The word confirms in the passage is closest in meaning to","options":["discloses","asserts","proves","challenges"],"answer":2,"target":"confirms"},{"n":10,"passage":"The first swimsuits concealed the shape of the human body. Over the decades, attitudes relaxed regarding the public display of one’s body shape. Designers could move away from conservative styles and promote those that revealed a body’s physical attributes.","prompt":"The word concealed in the passage is closest in meaning to","options":["hid","distorted","enhanced","disrupted"],"answer":0,"target":"concealed"}]},{"lesson":8,"words":[{"word":"accelerate","def_lines":[],"pos":"v","definition":"to go faster","forms":[{"pos":"n","word":"acceleration"},{"pos":"n","word":"accelerator"}],"synonyms":["hasten"],"examples":["The action of molecules accelerates when they are heated.","The poor condition of the motor made acceleration difficult."],"lesson":8,"id":"8-1"},{"word":"creep","def_lines":[],"pos":"v","definition":"to move slowly and quietly close to the ground; to begin to happen","forms":[{"pos":"adj","word":"creeping"}],"synonyms":["crawl"],"examples":["Some mistakes are beginning to creep into his work.","Ivy is a creeping variety of plant."],"lesson":8,"id":"8-2"},{"word":"crush","def_lines":[],"pos":"v","definition":"to press together so as to completely distort the shape or nature of the object","forms":[{"pos":"adj","word":"crushing"},{"pos":"n","word":"crush"}],"synonyms":["grind"],"examples":["The machine crushes corn to produce cornmeal.","Passage of the legislation was a crushing blow to the president’s program."],"lesson":8,"id":"8-3"},{"word":"cultivate","def_lines":[],"pos":"v","definition":"to plant and raise a crop; to encourage growth of a relationship or friendship","forms":[{"pos":"adj","word":"cultivated"},{"pos":"n","word":"cultivation"}],"synonyms":["grow"],"examples":["The professionals had common interests that allowed them to cultivate a working relationship with each other.","The cultivation of diverse crops in pre-Columbian America is well documented."],"lesson":8,"id":"8-4"},{"word":"dictate","def_lines":[],"pos":"v","definition":"to state demands with the power to enforce","forms":[{"pos":"adj","word":"dictatorial"},{"pos":"n","word":"dictator"}],"synonyms":["impose"],"examples":["The workers were not in a position to dictate demands to management.","His boss resembled a dictator."],"lesson":8,"id":"8-5"},{"word":"distinguish","def_lines":[],"pos":"v","definition":"to hear, see, or recognize differences","forms":[{"pos":"adj","word":"distinguishable"},{"pos":"adj","word":"distinguished"},{"pos":"adj","word":"distinguishing"}],"synonyms":["discriminate"],"examples":["Some people cannot distinguish colors well.","Anteaters are distinguished by their long noses."],"lesson":8,"id":"8-6"},{"word":"docile","def_lines":[],"pos":"adj","definition":"easy to control or train","forms":[{"pos":"adv","word":"docilely"},{"pos":"n","word":"docility"}],"synonyms":["manageable"],"examples":["The moose is typically a very docile animal.","Many rebellious young people see docility as a weakness."],"lesson":8,"id":"8-7"},{"word":"engender","def_lines":[],"pos":"v","definition":"to cause something new to exist; to create","forms":[],"synonyms":["produce"],"examples":["The politician’s charisma engendered enthusiasm.","Economic conditions in the 1950s engendered an era of industrial growth."],"lesson":8,"id":"8-8"},{"word":"engross","def_lines":[],"pos":"v","definition":"to become completely occupied or involved in an activity","forms":[{"pos":"n","word":"engrossment"},{"pos":"adj","word":"engrossing"}],"synonyms":["engage"],"examples":["The teacher’s lecture engrossed the entire class.","O. Henry’s short stories engross readers all the way to their surprise endings."],"lesson":8,"id":"8-9"},{"word":"flaw","def_lines":[],"pos":"n","definition":"a small sign of damage that makes an item imperfect","forms":[{"pos":"adj","word":"flawed"}],"synonyms":["defect"],"examples":["There is a flaw in his theory.","They noticed that the contract was flawed."],"lesson":8,"id":"8-10"},{"word":"harvest","def_lines":[],"pos":"n","definition":"the act of collecting a crop; the crops gathered","forms":[{"pos":"adj","word":"harvested"},{"pos":"v","word":"harvest"}],"synonyms":["gather"],"examples":["The United States had a comparatively good grain harvest this year.","They were able to harvest the crop before the rain."],"lesson":8,"id":"8-11"},{"word":"mammoth","def_lines":[],"pos":"adj","definition":"very large","forms":[{"pos":"n","word":"mammoth"}],"synonyms":["enormous"],"examples":["The successful entrepreneur is now known as a mammoth in the computer world.","The physics teacher required the students to purchase a mammoth textbook."],"lesson":8,"id":"8-12"},{"word":"mirror","def_lines":[],"pos":"v","definition":"to show, as in a mirror","forms":[{"pos":"n","word":"mirror"}],"synonyms":["reflect"],"examples":["The results of the study mirror public opinion.","The strength of the economy is mirrored in the standard of living of the people."],"lesson":8,"id":"8-13"},{"word":"obtain","def_lines":[],"pos":"v","definition":"to gain or secure something","forms":[{"pos":"adj","word":"obtainable"}],"synonyms":["gain"],"examples":["The university obtained a new particle accelerator.","The painting by Whistler was not obtainable."],"lesson":8,"id":"8-14"},{"word":"particle","def_lines":[],"pos":"n","definition":"a very small piece of something","forms":[],"synonyms":["fragment"],"examples":["Particles of dust can destroy electronic instruments.","Small particles of matter hold the keys to understanding the origin of life."],"lesson":8,"id":"8-15"},{"word":"settle","def_lines":[],"pos":"v","definition":"to establish a home; to resolve a disagreement","forms":[{"pos":"adj","word":"settled"},{"pos":"n","word":"settlement"}],"synonyms":["colonize"],"examples":["People arriving from the South settled in California.","The lawyers settled their differences and came to an agreement."],"lesson":8,"id":"8-16"},{"word":"transport","def_lines":[],"pos":"v","definition":"to move from one place to another","forms":[{"pos":"adj","word":"transportable"},{"pos":"adj","word":"transported"},{"pos":"n","word":"transportation"}],"synonyms":["carry"],"examples":["Flying is not always the fastest way to transport passengers to their destination.","The transportation expenses of products increase the final cost of the item."],"lesson":8,"id":"8-17"}],"matching":[{"n":1,"word":"flaw","options":["particle","agile","defect","creation"],"answer":2},{"n":2,"word":"dictate","options":["transport","engender","grow","impose"],"answer":3},{"n":3,"word":"hasten","options":["crawl","crush","conceal","accelerate"],"answer":3},{"n":4,"word":"crop","options":["harvest","advice","mirror","settlement"],"answer":0},{"n":5,"word":"fragment","options":["authorization","particle","cultivation","advantage"],"answer":1},{"n":6,"word":"mammoth","options":["assertive","enormous","chronic","minuscule"],"answer":1},{"n":7,"word":"manageable","options":["docile","relaxed","lovable","mundane"],"answer":0},{"n":8,"word":"discriminate","options":["enhance","persuade","distinguish","distort"],"answer":2},{"n":9,"word":"reflect","options":["mirror","confirm","produce","grind"],"answer":0},{"n":10,"word":"colonize","options":["crawl","cultivate","confirm","settle"],"answer":3}],"tests":[{"n":1,"passage":"Testing metals for quality assurance can be accomplished by several methods. One common nondestructive technique, used to locate surface cracks and flaws in metals, employs a penetrating liquid. Normally this fluid is brightly dyed or fluorescent. After being spread over the surface of the material, it soaks into any tiny cracks. The liquid is cleaned off, allowing cracks and blemishes to be easily seen.","prompt":"The word flaws in the passage is closest in meaning to","options":["bends","defects","cavities","dents"],"answer":1,"target":"flaws"},{"n":2,"passage":"An important task of management is to motivate individual workers to coordinate their collective efforts to achieve an organization’s goals. The concepts and methods used to structure work and to design organizations have changed considerably. An organization’s age can often be predicted by the way work is structured. Work practices tend to reflect the organization’s design theory present at the time the organization was founded.","prompt":"The word reflect in the passage is closest in meaning to","options":["influence","mirror","cultivate","accelerate"],"answer":1,"target":"reflect"},{"n":3,"passage":"The Mayflower Compact was a document signed by 41 of the male passengers on the Mayflower before their landing at Plymouth, Massachusetts. The passengers, concerned that some members of the company might leave the group and settle on their own, created the document. The Mayflower Compact created a political body whose purpose was to form a government. Those who signed pledged to abide by any future laws and regulations.","prompt":"The word settle in the passage is closest in meaning to","options":["enlist","move","linger","colonize"],"answer":3,"target":"settle"},{"n":4,"passage":"Before the invention of electroacoustic equipment that generates and measures sound, the available hearing tests gave approximate results in the best cases. A person’s hearing could be explained in terms of the ability to distinguish between the ticking of a watch and the clicking of coins or to determine the distance at which conversational speech or a whispered voice could no longer be understood.","prompt":"The word distinguish in the passage is closest in meaning to","options":["discriminate","listen","clarify","conceal"],"answer":0,"target":"distinguish"},{"n":5,"passage":"When DNA is subjected to restriction-enzyme activity, fragments of various sizes are formed. This process reveals a unique pattern of restriction-enzyme DNA. This specific DNA pattern found in each human genetic lineage is unique, because each person, except for identical twins, is formed from different combinations of the genetic material from two family lines. The pattern of sizes of the DNA from an individual is unique and can serve as a “DNA fingerprint” of that person.","prompt":"The word fragments in the passage is closest in meaning to","options":["growths","modifications","flaws","particles"],"answer":3,"target":"fragments"},{"n":6,"passage":"The invention of the airplane was a crushing blow for proponents of hot air ballooning. Early advocates of ballooning such as Jean-Pierre Blanchard and John Jeffries thought it would transform international travel. Instead, the cost of launching a balloon, the problem of controlling a balloon in high winds, and the instant attractiveness of more stable airplane travel have kept ballooning from becoming more than a hobby for a limited number of wealthy adventurers.","prompt":"In stating that the airplane’s invention was a crushing blow for proponents of ballooning, the author means that it","options":["led directly to the invention of the airplane.","caught on immediately among the public.","promoted hot air ballooning internationally.","kept ballooning from becoming more popular."],"answer":3,"target":""},{"n":7,"passage":"Farming continues to be an important activity on the eastern shore of Maryland. The eastern shore specializes in chickens for urban markets along the East Coast. Although market vegetables are also produced for the same urban markets, corn and soybeans continue to be the two most important crops cultivated on Maryland’s eastern shore.","prompt":"The word cultivated in the passage is closest in meaning to","options":["grown","gathered","developed","extracted"],"answer":0,"target":"cultivated"},{"n":8,"passage":"The earliest grain mills were hand-powered devices. Querns, which have been used for centuries to crush grains, are examples of such milling devices. A quern has an upper grinding stone with a handle. This handle rotates inside another stone, which contains the grain.","prompt":"The word crush in the passage is closest in meaning to","options":["produce","roughen","grind","elicit"],"answer":2,"target":"crush"},{"n":9,"passage":"From the core mouth on the underside of the starfish, channels with two or four rows of tube feet radiate outward along the arms. A hydraulic system that allows the starfish to move is connected to the tube feet. These rows of suctionlike feet enable the starfish to feed on mollusks and to creep along the ocean floor.","prompt":"The word creep in the passage is closest in meaning to","options":["race","drift","wander","crawl"],"answer":3,"target":"creep"},{"n":10,"passage":"The economic depression that plagued the United States in the 1930s was unique in its size and its consequences. During the worst period of the Depression, in 1933, one in every four American workers was out of a job. The great industrial slump engendered extreme hardship throughout the world that persisted throughout the 1930s.","prompt":"The word engendered in the passage is closest in meaning to","options":["accelerated","produced","persisted","developed"],"answer":1,"target":"engendered"}]},{"lesson":9,"words":[{"word":"accurate","def_lines":[],"pos":"adj","definition":"careful and exact","forms":[{"pos":"adv","word":"accurately"},{"pos":"n","word":"accuracy"}],"synonyms":["precise"],"examples":["She was able to make accurate observations with the new telescope.","Experiments must be conducted with accuracy."],"lesson":9,"id":"9-1"},{"word":"acute","def_lines":[],"pos":"adj","definition":"having a sudden consequence or severe effect","forms":[{"pos":"adv","word":"acutely"},{"pos":"n","word":"acuteness"}],"synonyms":["intense"],"examples":["The president was acutely aware of the fact that her decision would be unpopular.","He was suffering from an acute headache."],"lesson":9,"id":"9-2"},{"word":"classify","def_lines":[],"pos":"v","definition":"to place into groups according to type","forms":[{"pos":"adj","word":"classified"},{"pos":"n","word":"classification"}],"synonyms":["arrange"],"examples":["Biologists classify life forms into many phylla.","The library’s catalog is a classification of books in the library."],"lesson":9,"id":"9-3"},{"word":"currency","def_lines":[],"pos":"n","definition":"monetary unit; cash","forms":[],"synonyms":["money"],"examples":["Most purchases in foreign countries must be made in the local currency.","The Japanese currency is gaining strength against the dollar."],"lesson":9,"id":"9-4"},{"word":"deep","def_lines":[],"pos":"adj","definition":"far below the surface; complete understanding","forms":[{"pos":"adv","word":"deeply"},{"pos":"n","word":"depth"},{"pos":"v","word":"deepen"}],"synonyms":["thorough"],"examples":["Lake Baikal is the deepest lake in the world.","The depth of his understanding of math is remarkable."],"lesson":9,"id":"9-5"},{"word":"dense","def_lines":[],"pos":"adj","definition":"closely packed or crowded; difficult to see through","forms":[{"pos":"adv","word":"densely"},{"pos":"n","word":"density"}],"synonyms":["thick"],"examples":["The boating accident was caused by the dense fog.","Hong Kong is one of the most densely populated cities in the world."],"lesson":9,"id":"9-6"},{"word":"dim","def_lines":[],"pos":"adj","definition":"not bright or clear","forms":[{"pos":"adv","word":"dimly"},{"pos":"v","word":"dim"},{"pos":"n","word":"dimness"}],"synonyms":["faint"],"examples":["The light was too dim for studying.","The stars dimly lit the evening sky."],"lesson":9,"id":"9-7"},{"word":"display","def_lines":[],"pos":"v","definition":"to show; reveal","forms":[{"pos":"n","word":"display"}],"synonyms":["exhibit"],"examples":["The model displayed the details of the human hand.","The candidate’s display of anger was unfortunate."],"lesson":9,"id":"9-8"},{"word":"exports","def_lines":[],"pos":"n","definition":"products sold abroad","forms":[{"pos":"adj","word":"exported"},{"pos":"v","word":"export"}],"synonyms":["foreign sales"],"examples":["The United States’ imports now exceed its exports.","Exported goods are usually high in quality."],"lesson":9,"id":"9-9"},{"word":"gigantic","def_lines":[],"pos":"adj","definition":"very large","forms":[{"pos":"adv","word":"gigantically"}],"synonyms":["enormous"],"examples":["Reaching the moon was a gigantic step in space exploration for mankind.","New methods of farming offer gigantic advantages over the old methods."],"lesson":9,"id":"9-10"},{"word":"impressive","def_lines":[],"pos":"adj","definition":"causing admiration because of an object’s importance, size, or quality","forms":[{"pos":"adv","word":"impressively"},{"pos":"v","word":"impress"},{"pos":"n","word":"impression"}],"synonyms":["imposing"],"examples":["Lincoln’s power of persuasion was impressive.","Everyone left with a good impression of the play."],"lesson":9,"id":"9-11"},{"word":"install","def_lines":[],"pos":"v","definition":"to set up or create an office; to place in a fixed position","forms":[{"pos":"n","word":"installation"},{"pos":"n","word":"installer"}],"synonyms":["establish"],"examples":["The software we needed was already installed on the computer.","Antonia was installed as president of the art club last week."],"lesson":9,"id":"9-12"},{"word":"jargon","def_lines":[],"pos":"n","definition":"language specific to a profession or activity","forms":[{"pos":"adj","word":"jargony"}],"synonyms":["terminology"],"examples":["The legal jargon in the contract was confusing.","Science fiction jargon used in television shows and movies often comes from real science."],"lesson":9,"id":"9-13"},{"word":"lasting","def_lines":[],"pos":"adj","definition":"forever; without end","forms":[{"pos":"v","word":"last"}],"synonyms":["enduring"],"examples":["Kennedy left a lasting impression on the people who heard his inaugural address.","The introduction of robots will have a lasting effect on industry."],"lesson":9,"id":"9-14"},{"word":"straightforward","def_lines":[],"pos":"adj","definition":"easy to understand; simple; honest","forms":[{"pos":"adv","word":"straightforwardly"},{"pos":"n","word":"straightforwardness"}],"synonyms":["uncomplicated"],"examples":["The assembly directions were straightforward.","His straightforward approach to his business dealings earned him respect."],"lesson":9,"id":"9-15"},{"word":"uniform","def_lines":[],"pos":"adj","definition":"every part being the same","forms":[{"pos":"adv","word":"uniformly"},{"pos":"n","word":"uniformity"}],"synonyms":["consistent"],"examples":["Bread has a uniform texture.","The grades on the test were uniformly poor."],"lesson":9,"id":"9-16"},{"word":"vibrant","def_lines":[],"pos":"adj","definition":"lively; powerful; full of action; bright","forms":[{"pos":"adv","word":"vibrantly"},{"pos":"n","word":"vibrance"}],"synonyms":["brilliant"],"examples":["His vibrant personality made him well liked by everyone.","The vibrance of the city is attractive to many individuals."],"lesson":9,"id":"9-17"}],"matching":[{"n":1,"word":"enormous","options":["prosperous","autonomous","gigantic","classified"],"answer":2},{"n":2,"word":"dialect","options":["terminology","flaws","exports","jargon"],"answer":3},{"n":3,"word":"vibrant","options":["brilliant","critical","paint","deep"],"answer":0},{"n":4,"word":"straightforward","options":["agreeable","honest","useful","dependable"],"answer":1},{"n":5,"word":"imposing","options":["impressive","creative","intriguing","ambiguous"],"answer":0},{"n":6,"word":"uniform","options":["rigid","diverse","complex","consistent"],"answer":3},{"n":7,"word":"install","options":["hand in","set up","put on","get in"],"answer":1},{"n":8,"word":"lasting","options":["enduring","enriching","energetic","enhancing"],"answer":0},{"n":9,"word":"acute","options":["intense","accurate","precise","gigantic"],"answer":0},{"n":10,"word":"classify","options":["trust","learn","clarify","arrange"],"answer":3}],"tests":[{"n":1,"passage":"Written by Adam Smith in 1776, The Wealth of Nations is a vibrant attack against mercantilism and one of the most influential books ever written on economics. One of its main ideas is that when people pursue their own selfish interests, society as a whole benefits. Competition, rather than private or government monopoly, should regulate prices and wages. He also believed that competition produces socially beneficial consequences and that government should not interfere with market forces.","prompt":"The word vibrant in the passage is closest in meaning to","options":["critical","brilliant","intriguing","gigantic"],"answer":1,"target":"vibrant"},{"n":2,"passage":"Despite its weaknesses and inner conflicts, the humanistic movement was heroic in its scope and energy, and exceptional in its aspirations. For human development in all fields, it created a context of seldom- equaled fertility. Its characteristic modalities of thought, speech, and vision lent themselves to induce the genius of humankind and became the media for enduring achievement.","prompt":"The word enduring in the passage is closest in meaning to","options":["trivial","spectacular","significant","lasting"],"answer":3,"target":"enduring"},{"n":3,"passage":"The gigantic, intricately formed chasm of the Grand Canyon contains a great many impressive peaks, canyons, and ravines between its outer walls. The canyon includes a number of side canyons and surrounding plateaus. The deepest and most impressively beautiful section is within Grand Canyon National Park, which encompasses the Colorado River’s length from Lake Powell to Lake Mead.","prompt":"The word gigantic in the passage is closest in meaning to","options":["deep","turbulent","enormous","thrilling"],"answer":2,"target":"gigantic"},{"n":4,"passage":"The unified classical architectural style of the 1893 World’s Columbian Exposition buildings proved to be the most impressive and influential style of its time. A committee of East Coast architects and firms gathered in December 1890 to plan the fair buildings. The collective result was the construction of a group of 150 buildings known as the White City. Their design established white, columnar architecture as the only acceptable public style in the United States for 40 years thereafter.","prompt":"The word impressive in the passage is closest in meaning to","options":["imposing","influential","massive","enduring"],"answer":0,"target":"impressive"},{"n":5,"passage":"Maclean’s, a semimonthly news magazine published in Toronto, has earned a reputation for its depth of coverage of Canada’s national affairs and of North American and world news from a Canadian perspective. This coverage, along with its reputation for outstanding photography, has made it Canada’s leading magazine. Founded in 1905, it has consistently featured articles and fiction reflecting a conservative view of Canadian life and values.","prompt":"The word depth in the passage is closest in meaning to","options":["breadth","techniques","consistency","thoroughness"],"answer":3,"target":"depth"},{"n":6,"passage":"England is the second-most densely populated country in Europe, preceded only by Malta. It has 255 inhabitants per square kilometer. In comparison, Italy has 200 inhabitants and Spain 87. Many European countries have agricultural economies and their populations are unevenly distributed. For example, Paris has 20,741 people per square kilometer, while many parts of the rest of the country contain fewer than 30 people per square kilometer.","prompt":"In stating that England is densely populated, the author means that its","options":["population is the most unevenly distributed.","population is the largest in Europe.","population is the largest per square kilometer.","population is largest in its cities."],"answer":2,"target":""},{"n":7,"passage":"In the field of artificial intelligence, scientists are studying methods for developing computer programs that display aspects of intelligent behavior. Research into all aspects of artificial intelligence is vigorous. However, some researchers doubt that artificial intelligence can truly replicate forms of intelligent behavior like that observed in intelligent living organisms. Indeed, artificial intelligence programs are simple when compared to the intuitive reasoning and induction capabilities of the human brain.","prompt":"The word display in the passage is closest in meaning to","options":["exhibit","narrate","declare","arrange"],"answer":0,"target":"display"},{"n":8,"passage":"Canadian thistle is a bothersome North American weed that grows in clusters. However, some species such as the Scotch, or cotton thistle, which have dense heads of small pink or purple flowers, can make attractive garden plants and are widely cultivated for ornamental purposes throughout the Northeast.","prompt":"The word dense in the passage is closest in meaning to","options":["small","many","beautiful","thick"],"answer":3,"target":"dense"},{"n":9,"passage":"The Sun is the only star known to be accompanied by an extensive planetary system. However, a few nearby stars are now known to be encircled by particles of undetermined size; this opens the strong, unproven, hypothesis that the universe is filled with many solar systems. No deep understanding of the Solar System can be achieved without an appreciation of the basic properties of the Sun.","prompt":"The word deep in the passage is closest in meaning to","options":["enduring","proper","thorough","adequate"],"answer":2,"target":"deep"},{"n":10,"passage":"An exchange rate is the rate at which one country’s currency may be exchanged for that of another. Exchange rates have been governed in recent years primarily by the forces of supply and demand. The exchange rate normally changes, depending upon the strength of a country’s economy and its trade balance.","prompt":"The word currency in the passage is closest in meaning to","options":["exports","goods","gains","money"],"answer":3,"target":"currency"}]},{"lesson":10,"words":[{"word":"distinct","def_lines":[],"pos":"adj","definition":"clearly noticed; different","forms":[{"pos":"adv","word":"distinctly"},{"pos":"adj","word":"distinctive"},{"pos":"n","word":"distinction"}],"synonyms":["definite"],"examples":["There was a distinct aroma of coffee in the restaurant.","The two theories are distinctly different from each other."],"lesson":10,"id":"10-1"},{"word":"dominant","def_lines":[],"pos":"adj","definition":"primary or principal; having or exercising control over something","forms":[{"pos":"adv","word":"dominantly"},{"pos":"v","word":"dominate"},{"pos":"n","word":"domination"}],"synonyms":["major"],"examples":["The dominant life forms of the Paleozoic era lived in the water.","The skyscraper dominated the skyline."],"lesson":10,"id":"10-2"},{"word":"dormant","def_lines":[],"pos":"adj","definition":"not growing or producing; asleep","forms":[{"pos":"n","word":"dormitory"}],"synonyms":["inactive"],"examples":["The volcano had been dormant for hundreds of years before the eruption last month.","The seniors live in the new dormitory."],"lesson":10,"id":"10-3"},{"word":"drab","def_lines":[],"pos":"adj","definition":"lacking color; uninteresting, boring","forms":[{"pos":"adv","word":"drably"},{"pos":"n","word":"drabness"}],"synonyms":["colorless"],"examples":["Their clothing was quite drab.","The drabness of the desert made driving less interesting."],"lesson":10,"id":"10-4"},{"word":"dramatic","def_lines":[],"pos":"adj","definition":"something that captures the imagination; exciting","forms":[{"pos":"adv","word":"dramatically"},{"pos":"v","word":"dramatize"},{"pos":"n","word":"drama"}],"synonyms":["emotional"],"examples":["The dramatic finish to the game left us speechless.","The hurricane dramatically changed the coastline."],"lesson":10,"id":"10-5"},{"word":"eclectic","def_lines":[],"pos":"adj","definition":"to select or represent something chosen from many sources or places","forms":[{"pos":"adv","word":"eclectically"}],"synonyms":["diverse"],"examples":["He has an eclectic taste in music, from hard rock to classical.","The eclectic group of students came from fifteen different countries."],"lesson":10,"id":"10-6"},{"word":"elaborate","def_lines":[],"pos":"adj","definition":"something with a large number of parts; full of details","forms":[{"pos":"adv","word":"elaborately"},{"pos":"v","word":"elaborate"},{"pos":"n","word":"elaboration"}],"synonyms":["complex"],"examples":["An elaborate head dress indicated rank within the Aztec community.","His elaboration of the issue was quite thorough."],"lesson":10,"id":"10-7"},{"word":"exceptional","def_lines":[],"pos":"adj","definition":"unusual in a positive way","forms":[{"pos":"adv","word":"exceptionally"}],"synonyms":["phenomenal"],"examples":["The orchestra’s performance was exceptional.","The North Star is exceptionally bright."],"lesson":10,"id":"10-8"},{"word":"genuine","def_lines":[],"pos":"adj","definition":"honest or true; real","forms":[{"pos":"adv","word":"genuinely"},{"pos":"n","word":"genuineness"}],"synonyms":["authentic"],"examples":["She was genuinely concerned about world hunger.","This is a genuine artifact from the American Civil War."],"lesson":10,"id":"10-9"},{"word":"hazardous","def_lines":[],"pos":"adj","definition":"very risky, unsafe","forms":[{"pos":"adv","word":"hazardously"},{"pos":"n","word":"hazard"}],"synonyms":["dangerous"],"examples":["Handling flammable liquids is hazardous.","There are many hazards involved with starting a business."],"lesson":10,"id":"10-10"},{"word":"minuscule","def_lines":[],"pos":"adj","definition":"of little consequence; very small","forms":[{"pos":"adj","word":"minute"},{"pos":"n","word":"minutia"}],"synonyms":["tiny"],"examples":["The sale of the building had a minuscule effect on the profits of the corporation.","Some leaves are covered with minute hairs."],"lesson":10,"id":"10-11"},{"word":"prime","def_lines":[],"pos":"v","definition":"to make ready; *first in importance or in time","forms":[{"pos":"adj","word":"primed"},{"pos":"adj","word":"prime*"},{"pos":"n","word":"prime"}],"synonyms":["prepare"],"examples":["The directors primed the actors before the performance.","Mozart passed away in the prime of his life."],"lesson":10,"id":"10-12"},{"word":"rudimentary","def_lines":[],"pos":"adj","definition":"simple; not complex","forms":[{"pos":"n","word":"rudiment"}],"synonyms":["basic"],"examples":["He has a rudimentary knowledge of computers.","The rudiments of grammar are taught in all English classes."],"lesson":10,"id":"10-13"},{"word":"skeptical","def_lines":[],"pos":"adj","definition":"to question the truthfulness of information presented as fact; to not trust","forms":[{"pos":"adv","word":"skeptically"},{"pos":"n","word":"skeptic"}],"synonyms":["unconvinced"],"examples":["The professor was skeptical about the theories of climate change.","To answer his skeptics, the scientist presented proof of his conclusions at the conference."],"lesson":10,"id":"10-14"},{"word":"stoic","def_lines":[],"pos":"adj","definition":"showing no emotion; appearing disinterested","forms":[{"pos":"adv","word":"stoically"},{"pos":"n","word":"stoicism"}],"synonyms":["indifferent"],"examples":["His stoicism was unusual, since he is normally an emotional boy.","His stoic reaction to the event surprised his friends."],"lesson":10,"id":"10-15"},{"word":"superficial","def_lines":[],"pos":"adj","definition":"simple; not deep; near the surface","forms":[{"pos":"adv","word":"superficially"}],"synonyms":["shallow"],"examples":["The inspector determined that the crack in the bridge was only superficial.","You should not try to answer the question superficially."],"lesson":10,"id":"10-16"},{"word":"vigorous","def_lines":[],"pos":"adj","definition":"powerful, full of action","forms":[{"pos":"adv","word":"vigorously"},{"pos":"n","word":"vigor"}],"synonyms":["strong"],"examples":["His vigorous defense of the issues impressed everyone.","He approached his work with vigor."],"lesson":10,"id":"10-17"}],"matching":[{"n":1,"word":"exceptional","options":["dominant","dense","phenomenal","acceptable"],"answer":2},{"n":2,"word":"stoic","options":["distorted","indifferent","hazardous","straightforward"],"answer":1},{"n":3,"word":"prepare","options":["concur","display","depend","prime"],"answer":3},{"n":4,"word":"eclectic","options":["vibrant","energized","limited","diverse"],"answer":3},{"n":5,"word":"dangerous","options":["hazardous","rigid","commonplace","intolerable"],"answer":0},{"n":6,"word":"elaborate","options":["gigantic","impressive","complex","dramatic"],"answer":2},{"n":7,"word":"minuscule","options":["tiny","dim","drab","major"],"answer":0},{"n":8,"word":"superficial","options":["emotional","lasting","shallow","curious"],"answer":2},{"n":9,"word":"authentic","options":["basic","valid","genuine","rudimentary"],"answer":2},{"n":10,"word":"vigorous","options":["dominant","convenient","uniform","strong"],"answer":3}],"tests":[{"n":1,"passage":"The development of centralized governments was not accompanied by centralized responsibility for road maintenance. One important development in the construction and maintenance of public transportation systems was the establishment of turnpike trusts. Entrepreneurs would join together to obtain government permission to take over a length of road for 21 years or build a new one and pay for its maintenance by collecting tolls. However, in its early years, road engineering was rudimentary, and many trusts did not know how to preserve the roads.","prompt":"The word rudimentary in the passage is closest in meaning to","options":["elaborate","haphazard","flawed","basic"],"answer":3,"target":"rudimentary"},{"n":2,"passage":"Language is a system of communication specific to the human race. It is primarily oral-aural, since all naturally evolved large-scale linguistic systems have orderly patterns of sound produced by the human voice and perceived and processed by the ear. Despite the great variety of languages spoken throughout the world and the superficial differences among them, most linguists agree that all languages are essentially similar in structure and function.","prompt":"The word superficial in the passage is closest in meaning to","options":["certain","frightening","exceptional","shallow"],"answer":3,"target":"superficial"},{"n":3,"passage":"The layers of volatile gases and liquids near and above the surface of the Earth are of prime importance, along with solar energy, to maintaining life on Earth. They are distributed and recycled throughout the relatively thin atmosphere of the Earth. This atmosphere is a mixture of gases, primarily nitrogen and oxygen. However, the atmosphere also contains much smaller amounts of gases such as argon, carbon dioxide, methane, and water vapor along with minute solid and liquid particles in suspension.","prompt":"The word prime in the passage is closest in meaning to","options":["chief","dubious","superficial","dramatic"],"answer":0,"target":"prime"},{"n":4,"passage":"Avoidance is the most common form of defense in reptiles. At the first sign of danger, most snakes and lizards slither or dart away under cover; turtles and crocodiles plunge out of sight into water. But, in cases where danger presents itself abruptly and flight may be hazardous, reptiles may attack.","prompt":"The word hazardous in the passage is closest in meaning to","options":["futile","dangerous","arbitrary","unacceptable"],"answer":1,"target":"hazardous"},{"n":5,"passage":"As the Industrial Revolution developed in the nineteenth century, the era of wooden-hulled sailing ships gave way to that of steam-powered iron ships. Phenomenal changes took place in nearly every facet of ship design and operation. By the mid-1800s, these changes caused the end of the majestic wooden-hulled ship line. Despite its demise, another half century would elapse before it was clear what form its replacement would take.","prompt":"The word phenomenal in the passage is closest in meaning to","options":["vigorous","definite","exceptional","debilitating"],"answer":2,"target":"phenomenal"},{"n":6,"passage":"Research suggests that musical ability is genetic. Twins have the same genetic makeup. Therefore, researchers asked more than 500 children to sing along with recorded popular songs and discovered that 80 percent were equally able or unable to duplicate the melody. These results support the claim that musical talent is inherited—many children have some talent, but few are exceptionally talented, and only they have any hope of becoming concert pianists.","prompt":"In stating that few children are exceptionally talented, the author means that","options":["musical ability is evenly distributed.","almost everyone should study music.","the most talented are few in number.","twins cannot sing along with a song."],"answer":2,"target":""},{"n":7,"passage":"In the social sciences, conflict theory refers to the theoretical approach that views social phenomena as the result of conflict between individuals or groups. Conflict theory has developed at both micro and macro levels. Since much of the documented behavior is dramatic and unpredictable, theories of such behavior are more evaluative than analytic.","prompt":"The word dramatic in the passage is closest in meaning to","options":["frightening","distinctive","emotional","distorted"],"answer":2,"target":"dramatic"},{"n":8,"passage":"Feathers serve as an adaptable cover for the body of a bird. They form a smooth surface that reduces friction with the air, and they furnish flexible strong wings for flight and tails for steering. Feathers also act as superb insulation to conserve body heat and are relatively waterproof. Many songbirds in temperate zones reveal a drab plumage during the winter, in contrast to their brilliant springtime mating plumage.","prompt":"The word drab in the passage is closest in meaning to","options":["ideal","colorless","altered","basic"],"answer":1,"target":"drab"},{"n":9,"passage":"Comic books began as collections of newspaper comic strips and took on a life of their own in the 1930s. The favorite reading matter of several generations of children, comic books often dealt with heroic characters who fought crime or terror. The newspaper strip and the comic book represent the dominant graphic mythology of the twentieth century.","prompt":"The word dominant in the passage is closest in meaning to","options":["major","elaborate","lasting","critical"],"answer":0,"target":"dominant"},{"n":10,"passage":"The vast majority of animals exhibit a symmetrical form, therefore making form a fundamental, representative characteristic for most animals. All animals with a bilateral symmetry, those that have a distinct right and left side and a front and rear end, are classified together as Bilateria, a division of multicellular animals. Bilateria contrast with multicellular animals, which have a radial symmetry. An example is the jellyfish, which has no right or left sides.","prompt":"The word distinct in the passage is closest in meaning to","options":["dominant","uniform","definite","conventional"],"answer":2,"target":"distinct"}]},{"lesson":11,"words":[{"word":"amenity","def_lines":[],"pos":"n","definition":"something that makes life easier or more enjoyable","forms":[],"synonyms":["convenience"],"examples":["She missed all the amenities of home when she went camping.","One expects many amenities at a five-star hotel."],"lesson":11,"id":"11-1"},{"word":"disperse","def_lines":[],"pos":"v","definition":"to cause to move in many different directions","forms":[{"pos":"adj","word":"dispersed"}],"synonyms":["circulate"],"examples":["The high winds and rain dispersed the crowd.","After the hurricane, dispersed belongings cluttered the street."],"lesson":11,"id":"11-2"},{"word":"dwelling","def_lines":[],"pos":"n","definition":"where people live","forms":[{"pos":"n","word":"dweller"},{"pos":"v","word":"dwell"}],"synonyms":["house"],"examples":["Cavelike dwellings have been discovered throughout the world.","City dwellers often have trouble adjusting to life in the country."],"lesson":11,"id":"11-3"},{"word":"element","def_lines":[],"pos":"n","definition":"a part of the whole *environment","forms":[{"pos":"adj","word":"elemental"},{"pos":"n","word":"element*"}],"synonyms":["component"],"examples":["City dwellers are out of their element in the country.","Hard work and perseverance are the basic elements of success."],"lesson":11,"id":"11-4"},{"word":"elementary","def_lines":[],"pos":"adj","definition":"simple in structure, easy to do","forms":[],"synonyms":["primary"],"examples":["The solution to the problem was actually quite elementary.","You must take Elementary Physics before you can enroll in the advanced course."],"lesson":11,"id":"11-5"},{"word":"eliminate","def_lines":[],"pos":"v","definition":"to remove, free oneself of something","forms":[{"pos":"adj","word":"eliminated"},{"pos":"n","word":"elimination"}],"synonyms":["delete"],"examples":["Mistakes must be eliminated before you hand in a term paper.","The elimination of the runner from the race was decided by the judge."],"lesson":11,"id":"11-6"},{"word":"emerge","def_lines":[],"pos":"v","definition":"to come into view, or existence","forms":[{"pos":"n","word":"emergence"}],"synonyms":["appear"],"examples":["It took an hour for the newborn chick to emerge from its egg.","The sun emerged from the thick rain clouds, giving hope that the game would be played."],"lesson":11,"id":"11-7"},{"word":"emphasize","def_lines":[],"pos":"v","definition":"to show that something is especially important or exceptional","forms":[{"pos":"adv","word":"emphatically"},{"pos":"adj","word":"emphatic"},{"pos":"n","word":"emphasis"}],"synonyms":["highlight"],"examples":["The professor emphasized certain aspects of the historical period.","When asked if they would like to leave class early, the students answered with an emphatic “yes.”"],"lesson":11,"id":"11-8"},{"word":"encircle","def_lines":[],"pos":"v","definition":"to make a circle around","forms":[{"pos":"adj","word":"encircled"}],"synonyms":["surround"],"examples":["The players encircled their coach after winning the big game.","The encircled celebrity actually became afraid of her fans."],"lesson":11,"id":"11-9"},{"word":"erratic","def_lines":[],"pos":"adj","definition":"no regular pattern in thinking or movement; changeable without reason","forms":[{"pos":"adv","word":"erratically"}],"synonyms":["inconsistent"],"examples":["The artist’s paintings have an erratic quality, some being excellent, and others mediocre.","The unstable chemical reacted erratically."],"lesson":11,"id":"11-10"},{"word":"exaggerate","def_lines":[],"pos":"v","definition":"to make something more than what it is","forms":[{"pos":"adj","word":"exaggerated"},{"pos":"n","word":"exaggeration"}],"synonyms":["overstate"],"examples":["The federal government exaggerated the success of its programs.","To say that his business is successful would be a slight exaggeration."],"lesson":11,"id":"11-11"},{"word":"integral","def_lines":[],"pos":"adj","definition":"to be an essential or basic part of something","forms":[{"pos":"adv","word":"integrally"},{"pos":"n","word":"integrallity"}],"synonyms":["vital"],"examples":["Knowledge of spelling is an integral part of writing in any language.","A film’s music is integral to drawing the viewers into the story."],"lesson":11,"id":"11-12"},{"word":"justify","def_lines":[],"pos":"v","definition":"to show to be right or reasonable; to support","forms":[{"pos":"n","word":"justification"},{"pos":"adj","word":"justifiably"}],"synonyms":["defend"],"examples":["The young boy could not justify his rude behavior.","There was no justification for the criminal’s attack."],"lesson":11,"id":"11-13"},{"word":"mention","def_lines":[],"pos":"v","definition":"to say; relate in written form","forms":[{"pos":"adj","word":"mentioned"},{"pos":"n","word":"mention"}],"synonyms":["remark"],"examples":["Theatergoers often mention that they enjoy watching movies on a large screen.","The book mentioned above was included in the bibliography that was handed out in class last week."],"lesson":11,"id":"11-14"},{"word":"mortify","def_lines":[],"pos":"v","definition":"to embarrass","forms":[{"pos":"n","word":"mortification"}],"synonyms":["humiliate"],"examples":["He was mortified upon forgetting his lines during the play.","She mortified her son by showing Alice his baby pictures."],"lesson":11,"id":"11-15"},{"word":"prevalent","def_lines":[],"pos":"adj","definition":"existing widely or commonly","forms":[{"pos":"n","word":"prevalence"}],"synonyms":["commonplace"],"examples":["Comfortable trade winds are prevalent in the Caribbean islands.","There is a prevalence of disease where poor sanitation conditions exist."],"lesson":11,"id":"11-16"},{"word":"release","def_lines":[],"pos":"v","definition":"to allow to come out; to give freedom","forms":[{"pos":"n","word":"release"}],"synonyms":["free"],"examples":["A new movie was just released.","The release of the Supreme Court’s decision was expected today."],"lesson":11,"id":"11-17"}],"matching":[{"n":1,"word":"amenity","options":["advice","convenience","element","emphasis"],"answer":1},{"n":2,"word":"justify","options":["defend","conform","disperse","forbid"],"answer":0},{"n":3,"word":"mention","options":["surround","remark","assert","clarify"],"answer":1},{"n":4,"word":"mortify","options":["frighten","humiliate","criticize","extinguish"],"answer":1},{"n":5,"word":"exaggerate","options":["impress","dominate","elaborate","overstate"],"answer":3},{"n":6,"word":"disperse","options":["circulate","classify","distort","encircle"],"answer":0},{"n":7,"word":"release","options":["free","restore","settle","block"],"answer":0},{"n":8,"word":"vital","options":["rigid","complex","erratic","integral"],"answer":3},{"n":9,"word":"commonplace","options":["elementary","rudimentary","prevalent","uniform"],"answer":2},{"n":10,"word":"emerge","options":["join","distort","appear","release"],"answer":2}],"tests":[{"n":1,"passage":"Kapok is made from the silky fiber that encircles the seeds of the tropical silk-cotton tree. This dense mat of cottony fibers surrounds each seed within the fruit. However, unlike cotton fibers, kapok fibers do not lend themselves to spinning. Since they are water resistant and buoyant, kapok fibers were extensively used for padding and insulation until the development of synthetic fibers.","prompt":"The word encircles in the passage is closest in meaning to","options":["releases","circulates","surrounds","disperses"],"answer":2,"target":"encircles"},{"n":2,"passage":"Lewis and Clark’s expedition’s central objective, the discovery of the “water communication,” was not realized. However, a huge blank space on the map of North America had been filled as a result of the expedition. The rumor and myth related to the American West had been eliminated and new knowledge about the Wild West was made known to the American people.","prompt":"The word eliminated in the passage is closest in meaning to","options":["released","circulated","deleted","exaggerated"],"answer":2,"target":"eliminated"},{"n":3,"passage":"The most elementary type of convection can be explained by the fact that heat rises. Convection currents permit buildings to be heated without the use of circulatory devices. The heated air moves solely by gravity. In the atmosphere, convection causes the wind to blow. Most severe weather conditions, such as tornadoes, result from particularly sharp convection currents.","prompt":"The word elementary in the passage is closest in meaning to","options":["dispersed","erratic","prevalent","primary"],"answer":3,"target":"elementary"},{"n":4,"passage":"The key element of the air conditioner is a fluorocarbon refrigerant that flows constantly through the conditioner’s mechanisms. It becomes a liquid and gives off heat when it is compressed, and becomes a gas and absorbs heat when the pressure is removed. The mechanisms that evaporate and compress the refrigerant are divided into two areas, one on the interior, which includes an air filter, fan, and cooling coil, and one on the exterior, which includes a compressor, condenser coil, and fan.","prompt":"The word element in the passage is closest in meaning to","options":["amenity","component","purpose","advantage"],"answer":1,"target":"element"},{"n":5,"passage":"A common inhabitant of the southwest United States, the prairie dog lives in groups called coteries. A breeding coterie contains one male, one to four females, and the young of the past two years. Several coteries form large groups called wards, which are determined by the structure of the terrain. The wards in turn are united into towns— complex dwellings of interconnecting burrows and many entrances. The towns may cover as many as 65 to 160 acres, which contain thousands of individuals.","prompt":"The word dwellings in the passage is closest in meaning to","options":["abodes","systems","tunnels","shifts"],"answer":0,"target":"dwellings"},{"n":6,"passage":"The sport utility vehicle, or SUV, is the most popular type of automobile in the United States today. SUVs are spacious, powerful, and rugged; they have more room for passengers, equipment, groceries, and boxes than ordinary cars. Therefore, they are more commonly found in the country than in the city, and in some suburban neighborhoods they are more prevalent than compact cars or vans. Even their high consumption of gas has little effect on their popularity.","prompt":"In stating that SUVs are more prevalent than compact cars, the author means that they","options":["cost more than compact cars.","are more numerous than compacts.","take up more parking space.","use more gas than other vehicles."],"answer":1,"target":""},{"n":7,"passage":"Water whirlwinds, commonly called waterspouts, are whirling columns of air and watery mist. Brief whirlwinds are erratic in motion, but the longer-lasting ones move slowly with the prevailing winds and are more regular in their movement. Storms generate most waterspouts, but tornado spouts, generated in thunderstorms, in association with tropical cyclones, are the most dangerous.","prompt":"The word erratic in the passage is closest in meaning to","options":["unique","inconsistent","arbitrary","complex"],"answer":1,"target":"erratic"},{"n":8,"passage":"Partly because it has promoted U.S. interests, the Monroe Doctrine has had considerable effect and enjoyed strong support in the United States. It has been used to justify intervention in the internal affairs of other American nations. However, U.S. diplomatic relations are strained due to growing anxiety over the prevalent instability of Latin American politics and recent controversial interventions.","prompt":"The word prevalent in the passage is closest in meaning to","options":["definite","determined","constant","commonplace"],"answer":3,"target":"prevalent"},{"n":9,"passage":"A caricature is a picture or other representation that exaggerates a particular physical, facial appearance, dress, or the manners of an individual to produce a distinct comical effect. It is used to ridicule political, social, or religious situations and institutions, or actions by individuals, groups, or classes of a society. The latter types of caricature are usually done with satirical rather than humorous intent, in order to encourage political or social change.","prompt":"The word exaggerates in the passage is closest in meaning to","options":["emphasizes","astonishes","embellishes","fabricates"],"answer":2,"target":"exaggerates"},{"n":10,"passage":"Geologic changes provide a convincing explanation for the puzzling way that plant species are spread around the world. The conifers of the genus Araucaria, for example, have large seeds that do not float in seawater and are dispersed only short distances. However, they have been found either as fossils or as actively growing plants on all continents and on some islands that appear to be fragments of continents.","prompt":"The word dispersed in the passage is closest in meaning to","options":["scattered","discarded","arranged","released"],"answer":0,"target":"dispersed"}]},{"lesson":12,"words":[{"word":"benefit","def_lines":[],"pos":"v","definition":"to be useful or helpful","forms":[{"pos":"adv","word":"beneficially"},{"pos":"adj","word":"beneficial"},{"pos":"n","word":"benefit"},{"pos":"n","word":"beneficiary"}],"synonyms":["assist"],"examples":["Use of solar power will benefit all mankind.","It is extremely beneficial to prepare for a test."],"lesson":12,"id":"12-1"},{"word":"blind","def_lines":[],"pos":"adj","definition":"unable to see or understand; to conceal; showing poor judgment or understanding","forms":[{"pos":"adv","word":"blindly"},{"pos":"n","word":"blindness"}],"synonyms":["unaware"],"examples":["They were blind to the fact that they had little chance to succeed.","He went into the job blindly, with no previous experience."],"lesson":12,"id":"12-2"},{"word":"broaden","def_lines":[],"pos":"v","definition":"to make larger or greater","forms":[{"pos":"adv","word":"broadly"},{"pos":"adj","word":"broad"},{"pos":"n","word":"breadth"}],"synonyms":["enlarge"],"examples":["Education will broaden your opportunities to land a good job.","The breadth of his knowledge is impressive."],"lesson":12,"id":"12-3"},{"word":"burgeon","def_lines":[],"pos":"v","definition":"growing at a fast pace","forms":[{"pos":"adj","word":"burgeoning"}],"synonyms":["thrive"],"examples":["The burgeoning population of major cities is creating a demand for more services.","His talent as a pianist burgeoned at the age of 14."],"lesson":12,"id":"12-4"},{"word":"conspicuously","def_lines":[],"pos":"adv","definition":"attracting attention","forms":[{"pos":"adj","word":"conspicuous"}],"synonyms":["noticeably"],"examples":["His name was conspicuously absent from the list of winners.","The attorneys were conspicuous for their aggressive manner in the courtroom."],"lesson":12,"id":"12-5"},{"word":"deficient","def_lines":[],"pos":"adj","definition":"not having enough of something","forms":[{"pos":"adv","word":"deficiently"},{"pos":"n","word":"deficiency"}],"synonyms":["lacking"],"examples":["A diet deficient in calcium can lead to bad health.","There is a deficiency of qualified engineers in the country."],"lesson":12,"id":"12-6"},{"word":"eloquent","def_lines":[],"pos":"adj","definition":"expressing clearly, effectively, and convincingly","forms":[{"pos":"adv","word":"eloquently"},{"pos":"n","word":"eloquence"}],"synonyms":["articulate (adj.)"],"examples":["Successful politicians are usually eloquent speakers.","That student’s essay is eloquently written."],"lesson":12,"id":"12-7"},{"word":"endorse","def_lines":[],"pos":"v","definition":"to express approval","forms":[{"pos":"n","word":"endorsement"}],"synonyms":["support"],"examples":["The union endorsed the new contract.","The president’s endorsement of the project guaranteed its funding."],"lesson":12,"id":"12-8"},{"word":"enormous","def_lines":[],"pos":"adj","definition":"very large","forms":[{"pos":"adv","word":"enormously"},{"pos":"n","word":"enormity"}],"synonyms":["tremendous"],"examples":["His enormous wealth allows him to contribute to many charities.","A diet with many fruits and vegetables is enormously beneficial to the body."],"lesson":12,"id":"12-9"},{"word":"entirely","def_lines":[],"pos":"adv","definition":"completely","forms":[{"pos":"adj","word":"entire"},{"pos":"n","word":"entirety"}],"synonyms":["thoroughly"],"examples":["The economist was entirely right in his analysis.","The president released the speech in its entirety before the news conference."],"lesson":12,"id":"12-10"},{"word":"erode","def_lines":[],"pos":"v","definition":"to wear away; disappear slowly","forms":[{"pos":"n","word":"erosion"}],"synonyms":["deteriorate"],"examples":["The senator’s support is eroding because of his unpopular positions on the major issues.","It took millions of years of erosion for nature to form the Grand Canyon."],"lesson":12,"id":"12-11"},{"word":"evaporate","def_lines":[],"pos":"v","definition":"to vanish","forms":[{"pos":"n","word":"evaporation"}],"synonyms":["disappear"],"examples":["The chances of the two sides reaching an agreement have evaporated.","The evaporation of the funds was unexplainable."],"lesson":12,"id":"12-12"},{"word":"noteworthy","def_lines":[],"pos":"adj","definition":"deserving positive recognition or attention","forms":[{"pos":"n","word":"noteworthiness"}],"synonyms":["remarkable"],"examples":["The university has a noteworthy collection of ancient texts.","There was a noteworthy increase in the amount of money the school raised."],"lesson":12,"id":"12-13"},{"word":"recover","def_lines":[],"pos":"v","definition":"to get back; to have something returned","forms":[{"pos":"adj","word":"recovered"},{"pos":"adj","word":"recoverable"},{"pos":"n","word":"recovery"}],"synonyms":["retrieve"],"examples":["The NASA team was unable to recover the space capsule.","The recovered objects had not been damaged."],"lesson":12,"id":"12-14"},{"word":"reportedly","def_lines":[],"pos":"adv","definition":"to know by report; unconfirmed; supposedly","forms":[{"pos":"adj","word":"reported"},{"pos":"v","word":"report"},{"pos":"n","word":"report"}],"synonyms":["rumored"],"examples":["The students reportedly sent a representative, but she has not yet arrived.","The reported tornado has not been confirmed."],"lesson":12,"id":"12-15"},{"word":"shift","def_lines":[],"pos":"n","definition":"a change in position or direction","forms":[{"pos":"adj","word":"shifting"},{"pos":"v","word":"shift"},{"pos":"adj","word":"shifty"}],"synonyms":["switch"],"examples":["The shift in the wind was helpful to the sailors.","Earthquakes are caused by shifting layers of earth along faults."],"lesson":12,"id":"12-16"},{"word":"susceptible","def_lines":[],"pos":"adj","definition":"to be subject to influence; capable of being affected by a person or thing","forms":[{"pos":"n","word":"susceptibleness"},{"pos":"adj","word":"susceptibly"}],"synonyms":["vulnerable"],"examples":["When traveling in tropical climates, travelers are susceptible to malaria.","Adolescents are especially susceptible to the influence of their friends."],"lesson":12,"id":"12-17"}],"matching":[{"n":1,"word":"benefit","options":["prosper","demand","assist","distinguish"],"answer":2},{"n":2,"word":"noticeably","options":["incessantly","enormously","conspicuously","broadly"],"answer":2},{"n":3,"word":"rumored","options":["routinely","purposefully","comparatively","reportedly"],"answer":3},{"n":4,"word":"lacking","options":["deficient","unaware","slim","enjoyable"],"answer":0},{"n":5,"word":"thrive","options":["exaggerate","burgeon","dominate","endorse"],"answer":1},{"n":6,"word":"susceptible","options":["vulnerable","conspicuous","exaggerated","released"],"answer":0},{"n":7,"word":"broaden","options":["impress","elicit","reveal","enlarge"],"answer":3},{"n":8,"word":"switch","options":["enrich","shift","propose","support"],"answer":1},{"n":9,"word":"retrieve","options":["recover","deteriorate","disperse","relinquish"],"answer":0},{"n":10,"word":"eloquent","options":["articulate","remarkable","enduring","conspicuous"],"answer":0}],"tests":[{"n":1,"passage":"Politics are an integral aspect of modern sports. In many places, political decisions determine which sports will be encouraged, how much public support will be available to promote recreational sports, and whether or not athletes will be free to compete in certain international competitions. Bitter controversies have arisen as some political support for popular sporting events has evaporated in various parts of the world.","prompt":"The word evaporated in the passage is closest in meaning to","options":["burgeoned","intensified","broadened","disappeared"],"answer":3,"target":"evaporated"},{"n":2,"passage":"Rolltop desks are named after their sliding roll tops, or tambours, that cover the working surface of the upper part and can be locked. First introduced into England from France in the late eighteenth century, the rolltop desk had become a standard piece of office equipment by the end of the nineteenth century. It was mass-produced in large quantities. Shortly after this period of mass production, its popularity eroded.","prompt":"The word eroded in the passage is closest in meaning to","options":["recovered","shifted","intensified","deteriorated"],"answer":3,"target":"eroded"},{"n":3,"passage":"The American architect Frank Lloyd Wright designed furniture, but its distinctive appearance defies categorization. The furniture design was entirely dependent on the design of the building; the same motifs appear in both. He consistently favored built-in furniture because then the furniture was part of the architecture.","prompt":"The word entirely in the passage is closest in meaning to","options":["slowly","reportedly","completely","conspicuously"],"answer":2,"target":"entirely"},{"n":4,"passage":"While the potential benefit of genetic engineering is substantial, the potential dangers may be equivalent. Improper handling could pose a health hazard to the public. For example, the introduction of cancer- causing genes into common infectious organisms like the influenza virus could be one of these dangers.","prompt":"The word benefit in the passage is closest in meaning to","options":["danger","assistance","endorsement","recovery"],"answer":1,"target":"benefit"},{"n":5,"passage":"Jogging has been endorsed by many medical authorities as valuable exercise for the heart and for general physical conditioning. It should be conducted every other day. Other medical authorities, however, warn that fallen arches and other ailments can result from jogging. Warm-up exercises before jogging, properly designed shoes, proper jogging technique, loose clothing, and general good health are vital for safe participation in this activity.","prompt":"The word endorsed in the passage is closest in meaning to","options":["reported","supported","criticized","exaggerated"],"answer":1,"target":"endorsed"},{"n":6,"passage":"In 1900, when countries such as Russia, Italy, and Japan claimed an exclusive right to trade with China, the secret society of “Boxers” was formed to oppose this intrusion into Chinese affairs. Members of the group were reported to have magical powers that protected them in attacks from invading foreigners. Nevertheless, more than 20,000 foreign troops eventually landed in China, successfully attacked Beijing, established their right to remain, and disbanded the Boxers.","prompt":"In stating that the Boxers were reported to have magical powers, the author means that their magical powers","options":["were an established fact.","were alleged to exist.","had been reported as false.","had been verified as true."],"answer":1,"target":""},{"n":7,"passage":"From 1890 to 1940, Los Angeles was the core orange-growing area. The city was inland from any potential port, but city leaders persuaded the U.S. Congress to finance a breakwater at the city of San Pedro. The territory between the two cities was annexed, and a great harbor was constructed between 1899 and 1914. As a result, Los Angeles experienced burgeoning economic growth.","prompt":"The word burgeoning in the passage is closest in meaning to","options":["enduring","hastened","ideal","thriving"],"answer":3,"target":"burgeoning"},{"n":8,"passage":"Normal schools were established chiefly to train elementary-school teachers. They were commonly state-supported and offered a two-year course beyond high school. In the twentieth century, schools broadened their teacher-training requirements to at least four years. Therefore, after World War II, teacher-training institutions lengthened their programs. By the 1960s, most former normal schools had been absorbed into colleges or universities as departments or schools of education.","prompt":"The word broadened in the passage is closest in meaning to","options":["replaced","shifted","enlarged","advanced"],"answer":2,"target":"broadened"},{"n":9,"passage":"Experiments are underway to prove the usefulness of new oil discovery technology. They will enable vast accumulations of crude oil to be recovered along both the Athabasca River in northcentral Alberta, Canada, and along the Orinoco River in eastern Venezuela. If these experiments are successful and a significant volume of crude is found, the world’s petroleum supply may be extended by several decades.","prompt":"The word recovered in the passage is closest in meaning to","options":["retrieved","exported","reported","extracted"],"answer":0,"target":"recovered"},{"n":10,"passage":"The Internet is a powerful tool available to students around the world. Thanks to its rapid growth, researching any topic is now as easy as a mouse click. It is no longer commonplace to see students using information from books in a library because the Internet is far more convenient. Students can carry an enormous amount of information in their backpacks or briefcases just by having a laptop computer with access to the worldwide web. Some people claim that digital books will soon replace physical books. Others believe that libraries will become obsolete and that scholars will turn to online sources to conduct research.","prompt":"The word enormous in the passage is closest in meaning to","options":["astounding","exceptional","advantageous","tremendous"],"answer":3,"target":"enormous"}]},{"lesson":13,"words":[{"word":"crucial","def_lines":[],"pos":"adj","definition":"of great importance; extremely necessary","forms":[{"pos":"adv","word":"crucially"}],"synonyms":["critical"],"examples":["Favorable weather is crucial to a good harvest.","Having all the information necessary to make a good decision is crucially important."],"lesson":13,"id":"13-1"},{"word":"dignitary","def_lines":[],"pos":"n","definition":"a very important or famous person, usually associated with a high position in government","forms":[],"synonyms":["celebrity"],"examples":["Every dignitary in Washington was invited to the wedding.","All of the high-ranking dignitaries attended the economic summit."],"lesson":13,"id":"13-2"},{"word":"elude","def_lines":[],"pos":"v","definition":"to escape in a tricky way","forms":[{"pos":"adj","word":"elusive"},{"pos":"n","word":"elusiveness"}],"synonyms":["evade"],"examples":["The criminal has eluded the police for months.","Success has been elusive for the team."],"lesson":13,"id":"13-3"},{"word":"evident","def_lines":[],"pos":"adj","definition":"easy to see, usually because of some proof","forms":[{"pos":"adv","word":"evidently"},{"pos":"n","word":"evidence"}],"synonyms":["apparent"],"examples":["It is evident that you are not feeling well.","All the evidence points to the presence of hydrogen."],"lesson":13,"id":"13-4"},{"word":"exhaust","def_lines":[],"pos":"v","definition":"to use completely; to expend all energy; very thorough","forms":[{"pos":"adv","word":"exhaustively"},{"pos":"adj","word":"exhaustive"},{"pos":"adj","word":"exhausting"},{"pos":"adj","word":"exhausted"},{"pos":"n","word":"exhaustion"}],"synonyms":["deplete"],"examples":["They exhausted their energy in ten minutes.","The exhaustive report was acclaimed by everyone."],"lesson":13,"id":"13-5"},{"word":"extensive","def_lines":[],"pos":"adj","definition":"large in area or number *to offer; to make longer","forms":[{"pos":"adv","word":"extensively"},{"pos":"v","word":"extend*"},{"pos":"n","word":"extension*"}],"synonyms":["comprehensive"],"examples":["The extensive snowfall caused problems throughout the city.","The professor extended a warm welcome to the new student."],"lesson":13,"id":"13-6"},{"word":"face","def_lines":[],"pos":"v","definition":"to be in the presence of and oppose","forms":[],"synonyms":["confront"],"examples":["The mountain climbers faced grave danger on the cliff.","He finds it difficult to face his problems."],"lesson":13,"id":"13-7"},{"word":"facet","def_lines":[],"pos":"n","definition":"element or component","forms":[{"pos":"adj","word":"faceted"}],"synonyms":["aspect"],"examples":["The proposal had many beneficial facets.","It was a multifaceted problem that challenged the entire student body."],"lesson":13,"id":"13-8"},{"word":"idol","def_lines":[],"pos":"n","definition":"a person or image that is loyally admired or respected","forms":[{"pos":"n","word":"idolatry"},{"pos":"adj","word":"idolatrous"}],"synonyms":["hero"],"examples":["The Beatles, a famous singing group of the 1960s, were the idols of many teenage girls.","Talented athletes often become idols in the eyes of their fans."],"lesson":13,"id":"13-9"},{"word":"inaccessible","def_lines":[],"pos":"adj","definition":"something that cannot be reached or communicated with","forms":[{"pos":"n","word":"inaccessibility"},{"pos":"adv","word":"inaccessibly"}],"synonyms":["remote"],"examples":["The summit of the mountain was inaccessible.","The dignitary’s inaccessibility frustrated the reporter."],"lesson":13,"id":"13-10"},{"word":"oblivious","def_lines":[],"pos":"adj","definition":"obliviously","forms":[{"pos":"n","word":"obliviousness"},{"pos":"adj","word":"to be unaware of or forgetful"}],"synonyms":["ignorant"],"examples":["The students were oblivious to the fact that the test would cover the entire chapter.","The coastal inhabitants were oblivious to the dangers of the approaching hurricane."],"lesson":13,"id":"13-11"},{"word":"obviously","def_lines":[],"pos":"adv","definition":"in a clear, easy-to-understand way","forms":[{"pos":"adj","word":"obvious"}],"synonyms":["evidently"],"examples":["It had obviously rained.","It was obvious that he had not practiced his oral report."],"lesson":13,"id":"13-12"},{"word":"offensive","def_lines":[],"pos":"adj","definition":"causing anger; rude; being unpleasant","forms":[{"pos":"n","word":"offensiveness"},{"pos":"adv","word":"offensively"}],"synonyms":["insulting"],"examples":["Rotten eggs emit an offensive odor.","Her offensive remarks angered the entire audience."],"lesson":13,"id":"13-13"},{"word":"predictably","def_lines":[],"pos":"adv","definition":"in a way that foretells future events","forms":[{"pos":"adj","word":"predictable"},{"pos":"v","word":"predict"},{"pos":"n","word":"prediction"}],"synonyms":["expectedly"],"examples":["She predictably forgot to do her assignment.","The government’s predictions were accurate."],"lesson":13,"id":"13-14"},{"word":"suitable","def_lines":[],"pos":"adj","definition":"appropriate; correct; convenient","forms":[{"pos":"adv","word":"suitably"},{"pos":"v","word":"suit"}],"synonyms":["appropriate"],"examples":["Her dress was not suitable for the occasion.","The agreement suits all the members of the negotiating team."],"lesson":13,"id":"13-15"},{"word":"surpass","def_lines":[],"pos":"v","definition":"to go beyond","forms":[{"pos":"adj","word":"surpassable"},{"pos":"n","word":"surpasser"}],"synonyms":["exceed"],"examples":["The movie surpassed even the film critics’ high expectations.","The soccer player will probably surpass the scoring record set last year."],"lesson":13,"id":"13-16"},{"word":"uphold","def_lines":[],"pos":"v","definition":"to support or maintain","forms":[{"pos":"n","word":"upholder"}],"synonyms":["sustain"],"examples":["The tree house was upheld by three thick tree branches.","Each president of the United States must promise to uphold the constitution."],"lesson":13,"id":"13-17"}],"matching":[{"n":1,"word":"oblivious","options":["elusive","blind","eclectic","valid"],"answer":1},{"n":2,"word":"critical","options":["prevalent","elusive","prime","crucial"],"answer":3},{"n":3,"word":"predictably","options":["obliviously","expectedly","conspicuously","extensively"],"answer":1},{"n":4,"word":"sustain","options":["uphold","emit","creep","distinguish"],"answer":0},{"n":5,"word":"inaccessible","options":["depleted","incessant","remote","enormous"],"answer":2},{"n":6,"word":"elude","options":["erode","evade","endorse","enrich"],"answer":1},{"n":7,"word":"extensive","options":["delicate","impressive","comprehensive","disruptive"],"answer":2},{"n":8,"word":"celebrity","options":["settler","dignitary","petitioner","dweller"],"answer":1},{"n":9,"word":"evidently","options":["routinely","entirely","exceptionally","obviously"],"answer":3},{"n":10,"word":"exceed","options":["surpass","benefit","ascertain","recompense"],"answer":0}],"tests":[{"n":1,"passage":"Engineering geologists survey the geology of an area, and then prepare a geological map. One of their main responsibilities is to determine whether the geological structure of a location is suitable for the building of huge structures such as dams.","prompt":"The word suitable in the passage is closest in meaning to","options":["appropriate","extensive","recoverable","perfect"],"answer":0,"target":"suitable"},{"n":2,"passage":"Experts believe that a child’s family experiences are crucial for personality development. The ways that basic needs are met in infancy, along with later techniques of child rearing, can leave a permanent mark on personality. Children learn behavior appropriate to their sex by identifying with the parent of the same sex. A warm, caring relationship with that parent helps such learning.","prompt":"The word crucial in the passage is closest in meaning to","options":["evident","extensive","critical","obvious"],"answer":2,"target":"crucial"},{"n":3,"passage":"The Everglades comprises one of the wildest and most inaccessible areas in the United States. Its wildlife is plentiful and is largely protected within the Everglades National Park. The only inhabitants of the Everglades are several hundred Seminole Indians.","prompt":"The word inaccessible in the passage is closest in meaning to","options":["remote","indiscriminate","inactive","immense"],"answer":0,"target":"inaccessible"},{"n":4,"passage":"Bank credit and debit cards, now used worldwide, are examples of general purpose bank cards. Establishments offering almost every kind of product or service now honor such cards. These cards are designed to give customers access to credit, savings, and checking accounts, eliminating the need to purchase items with cash. It is predicted that, in the future, these cards will completely eliminate the need for carrying cash.","prompt":"The word predicted in the passage is closest in meaning to","options":["inconceivable","evident","justified","anticipated"],"answer":3,"target":"predicted"},{"n":5,"passage":"In Western culture, until about the middle of the seventeenth century, biographies were generally tributes to famous individuals. Their purpose was to enlighten and motivate. They often dealt with the exemplary lives of people who became heroes and heroines to the public, but sometimes also glorified the lives of infamous doers of bad deeds.","prompt":"The word heroines in the passage is closest in meaning to","options":["dignitary","idol","benefactor","philanthropist"],"answer":1,"target":"heroines"},{"n":6,"passage":"Kinesics is the name given to the study of nonverbal interactions such as facial expressions, gestures, and eye contact. In many cultures, direct eye contact is seen as a sign of disrespect in face-to-face encounters. Students, for example, are expected to lower their eyes while addressing a teacher. In other cultures, lowered eyes are construed as an indication of shame, embarrassment, or dishonesty. Kinesics focuses on many such cultural differences.","prompt":"In discussing face-to-face encounters, the author is referring to social interactions in which two people are","options":["sitting back to back.","in front of each other.","keeping their eyes down.","staring into space."],"answer":1,"target":""},{"n":7,"passage":"High standards and rigorous early training are evident where dance is an art performed before an audience. In early cultures, dance was something in which everyone participated; dancers were not singled out and trained because of their skill or charm. Once religious worship developed into ritual, it became important for dancers to be as skilled as possible.","prompt":"The word evident in the passage is closest in meaning to","options":["rumored","apparent","vibrant","enhanced"],"answer":1,"target":"evident"},{"n":8,"passage":"Mineral deposits form because there is a transporting agent for the ore minerals. The transporting agent removes the minerals it carries from one area and deposits them in another. Groundwater and seawater are examples of transporting agents. The transporting agent process is involved in the creation of deposits of both abundant and exhausted metals.","prompt":"The word exhausted in the passage is closest in meaning to","options":["depleted","eroded","released","restricted"],"answer":0,"target":"exhausted"},{"n":9,"passage":"The independent African states encounter numerous problems implementing an educational policy that will encourage economic and social development. The difficulties most governments face are basically political. There is also concern about the financial problems of the different states. The lack of communication between educational policy makers and economic and social planners may also create hardships.","prompt":"The word face in the passage is closest in meaning to","options":["bear","resolve","confront","endorse"],"answer":2,"target":"face"},{"n":10,"passage":"Pop artists seek to portray modern culture. Their art emphasizes modern social values, the sprawl of urban life, and the flashy, frivolous, transitory, and offensive facets of modern life. These values are the very opposites of the values cherished by artists of the past.","prompt":"The word facets in the passage is closest in meaning to","options":["aspects","ideals","facts","particles"],"answer":0,"target":"facets"}]},{"lesson":14,"words":[{"word":"ample","def_lines":[],"pos":"adj","definition":"more than enough","forms":[{"pos":"adv","word":"amply"}],"synonyms":["sufficient"],"examples":["There is ample evidence that the young man was speeding when the accident occurred.","She was amply paid for the work she completed."],"lesson":14,"id":"14-1"},{"word":"arduous","def_lines":[],"pos":"adj","definition":"very difficult or challenging; requiring hard work","forms":[{"pos":"adv","word":"arduously"},{"pos":"n","word":"arduousness"}],"synonyms":["demanding"],"examples":["The mountain tour guides climbed the mountain at an arduous pace.","The farmer’s crops survived despite the arduous summer heat."],"lesson":14,"id":"14-2"},{"word":"arid","def_lines":[],"pos":"adj","definition":"being of little rain or water","forms":[],"synonyms":["dry"],"examples":["The area known as the Sahara Desert is one of the most arid places in the world.","The valley on the leeward side of the mountain was extremely arid."],"lesson":14,"id":"14-3"},{"word":"avert","def_lines":[],"pos":"v","definition":"to stop from occurring; to turn away or aside","forms":[{"pos":"n","word":"aversion"},{"pos":"adj","word":"avertable"}],"synonyms":["prevent"],"examples":["She could have averted the accident if she had not been texting while driving.","The citizens packed sandbags along the river bank to avert the flooding of their streets."],"lesson":14,"id":"14-4"},{"word":"defy","def_lines":[],"pos":"v","definition":"to show little fear or regard for rules or established norms; to challenge","forms":[{"pos":"adv","word":"defyingly"},{"pos":"adj","word":"defying"}],"synonyms":["resist"],"examples":["I defy you to find that book in the library’s collection.","The circus performer demonstrated her death-defying routine."],"lesson":14,"id":"14-5"},{"word":"diligent","def_lines":[],"pos":"adj","definition":"done with persistence and hard work; with attention to details","forms":[{"pos":"n","word":"diligence"},{"pos":"adv","word":"diligently"}],"synonyms":["conscientious"],"examples":["Stephanie displayed great diligence in the completion of her assignments.","The diligent worker received recognition for his accomplishments."],"lesson":14,"id":"14-6"},{"word":"enact","def_lines":[],"pos":"v","definition":"to pass a law","forms":[{"pos":"adj","word":"enacted"},{"pos":"n","word":"enactment"}],"synonyms":["legislate"],"examples":["Congress enacted the legislation during its last session.","The enactment of the laws was in the hands of the Senate."],"lesson":14,"id":"14-7"},{"word":"feign","def_lines":[],"pos":"v","definition":"to pretend; make believe","forms":[{"pos":"adj","word":"feigned"}],"synonyms":["simulate"],"examples":["She feigned illness when it was time to visit the dentist.","The athlete feigned his injury."],"lesson":14,"id":"14-8"},{"word":"fertile","def_lines":[],"pos":"adj","definition":"able to produce abundantly","forms":[{"pos":"v","word":"fertilize"},{"pos":"n","word":"fertility"},{"pos":"n","word":"fertilizer"}],"synonyms":["rich"],"examples":["The delta areas of rivers are known for their fertile soil.","Fertilizers are used on crops to increase yields."],"lesson":14,"id":"14-9"},{"word":"freshly","def_lines":[],"pos":"adv","definition":"caught or produced not long ago","forms":[{"pos":"adj","word":"fresh"},{"pos":"v","word":"freshen"},{"pos":"n","word":"freshness"}],"synonyms":["recently"],"examples":["Freshly harvested produce is hard to find in the winter months.","The product’s freshness depends on an efficient transportation system to bring it to market."],"lesson":14,"id":"14-10"},{"word":"function","def_lines":[],"pos":"n","definition":"the normal purpose of something","forms":[{"pos":"adv","word":"functionally"},{"pos":"adj","word":"functional"},{"pos":"v","word":"function"}],"synonyms":["role"],"examples":["It is the function of the director to organize and lead the department.","Most appliances cannot function without electricity."],"lesson":14,"id":"14-11"},{"word":"fundamental","def_lines":[],"pos":"adj","definition":"a primary or basic element","forms":[{"pos":"adv","word":"fundamentally"}],"synonyms":["essential"],"examples":["The student government promised fundamental changes in the registration process.","He is fundamentally strong in his area of expertise."],"lesson":14,"id":"14-12"},{"word":"indiscriminate","def_lines":[],"pos":"adj","definition":"not chosen carefully; unplanned","forms":[{"pos":"adv","word":"indiscriminately"}],"synonyms":["arbitrary"],"examples":["The indiscriminate arrangement of the products made the store confusing.","The book’s chapters seem to be organized indiscriminately."],"lesson":14,"id":"14-13"},{"word":"pinpoint","def_lines":[],"pos":"v","definition":"to find or describe something with precision","forms":[{"pos":"adj","word":"pinpoint"}],"synonyms":["locate"],"examples":["The engineers were immediately able to pinpoint the problem with the bridge.","The new, advanced thermometer measures the temperature with pinpoint accuracy."],"lesson":14,"id":"14-14"},{"word":"selective","def_lines":[],"pos":"adj","definition":"carefully chosen","forms":[{"pos":"adv","word":"selectively"},{"pos":"adv","word":"select"},{"pos":"v","word":"select"},{"pos":"n","word":"selection"},{"pos":"n","word":"selectivity"}],"synonyms":["discriminating"],"examples":["They were very selective when they chose the members of the academic team.","He selected Spanish as his language class."],"lesson":14,"id":"14-15"},{"word":"spacious","def_lines":[],"pos":"adj","definition":"having a lot of room","forms":[{"pos":"adv","word":"spaciously"},{"pos":"n","word":"space"},{"pos":"n","word":"spaciousness"}],"synonyms":["expansive"],"examples":["The spacious plains of the Midwest make up the nation’s breadbasket.","A vacuum is an empty space."],"lesson":14,"id":"14-16"},{"word":"withstand","def_lines":[],"pos":"v","definition":"to fight without surrender; to persist","forms":[],"synonyms":["survive"],"examples":["She cannot withstand the pressures of her job.","The old building withstood the terrible storm."],"lesson":14,"id":"14-17"}],"matching":[{"n":1,"word":"sufficient","options":["crucial","essential","ample","extensive"],"answer":2},{"n":2,"word":"survive","options":["erode","weaken","elude","withstand"],"answer":3},{"n":3,"word":"defy","options":["resist","determine","simulate","discriminate"],"answer":0},{"n":4,"word":"arduous","options":["predictable","demanding","functional","chronic"],"answer":1},{"n":5,"word":"arid","options":["dry","fertile","fresh","drab"],"answer":0},{"n":6,"word":"avert","options":["prevent","amaze","assert","allow"],"answer":0},{"n":7,"word":"selective","options":["inaccessible","rich","recent","discriminating"],"answer":3},{"n":8,"word":"diligent","options":["fundamental","erratic","evident","conscientious"],"answer":3},{"n":9,"word":"spacious","options":["crucial","superficial","minuscule","expansive"],"answer":3},{"n":10,"word":"pinpoint","options":["locate","enact","dictate","sustain"],"answer":0}],"tests":[{"n":1,"passage":"Naturally formed caves evolve mainly as a result of the solvent action of water and the chemical compounds it contains. Known as caves of solution, they are most common in regions that have ample rainfall.","prompt":"The word ample in the passage is closest in meaning to","options":["infrequent","abundant","exemplary","erratic"],"answer":1,"target":"ample"},{"n":2,"passage":"In the early days of gliding, gliders were towed by cars. Today, gliders are towed in the sky by airplanes to a height between 600 and 900 meters above the ground. Flight duration depends on finding updrafts of air along mountain slopes, near cumulus clouds, or over arid terrain where rising thermal currents occur.","prompt":"The word arid in the passage is closest in meaning to","options":["rocky","hot","dry","high"],"answer":2,"target":"arid"},{"n":3,"passage":"The Conestoga Indians were a powerful people, defying the invading Iroquois, until the Iroquois defeated them in about 1675. Part of the tribe fled to the Roanoke River. Others subsequently settled at Conestoga, near what is now Lancaster, Pennsylvania.","prompt":"The word defying in the passage is closest in meaning to","options":["ridiculing","honoring","resisting","overthrowing"],"answer":2,"target":"defying"},{"n":4,"passage":"Fasting has been practiced for centuries for many diverse purposes. Some fasts were to induce fertility. Others were intended to avert catastrophe or to serve as penance for sin. American Indians held tribal fasts to escape threatening disasters. The Aztecs of Mexico and the Incas of Peru observed penitential fasts to pacify their gods.","prompt":"The word avert in the passage is closest in meaning to","options":["overcome","assert","confirm","prevent"],"answer":3,"target":"avert"},{"n":5,"passage":"Monte Albán, near Oaxaca, Mexico, was the center of the Zapotec culture that flourished around the year 100 A.D. Its gigantic stone structures were set around a spacious plaza created by leveling the top of a mountain.","prompt":"The word spacious in the passage is closest in meaning to","options":["exhaustive","expansive","circular","fertile"],"answer":1,"target":"spacious"},{"n":6,"passage":"Space exploration has had its share of problems throughout the years. A flaw in the Challenger’s design led to a fatal accident in 1986, the Mir station was often in trouble, and the Columbia shuttle crashed on reentry in 2003. Despite these tragedies, the program has profited from its mistakes, and from new engineering and new materials. Today, NASA is confident that spacecraft are fundamentally sound and perfectly safe.","prompt":"In saying that spacecraft are fundamentally sound, the author means that they are","options":["basically well designed and built.","equipped with electronic music.","dangerously old and worn.","entirely new and experimental."],"answer":0,"target":""},{"n":7,"passage":"Food serves three functions in most living organisms. First, it provides material that is used to sustain the activities of the organism. Second, food supplies the electron donors required for the formative processes that occur within the cell. Third, food provides the materials from which all of the structural components of the living cell can be assembled.","prompt":"The word functions in the passage is closest in meaning to","options":["cores","facets","resolutions","roles"],"answer":3,"target":"functions"},{"n":8,"passage":"Harvested wood is dried and preserved as a treatment against insect infestation and rot. These processes ensure that it will last. Some wood products, such as posts and poles, are freshly cut. Most other wood products are made up of intermediate materials, which require further processing before they are manufactured into final products.","prompt":"The word freshly in the passage is closest in meaning to","options":["hardly","recently","routinely","scarcely"],"answer":1,"target":"freshly"},{"n":9,"passage":"Loess is topsoil left by glaciers. Vast deposits of loess make the Midwestern plain of the United States extremely fertile and one of the most important farming areas in the world. In addition, the soils in the land along the many rivers and streams of the region also add to its farming potential.","prompt":"The word fertile in the passage is closest in meaning to","options":["rich","hardy","vital","adaptable"],"answer":0,"target":"fertile"},{"n":10,"passage":"Since opossums are largely arboreal, their homes are often found in hollow trees or under stumps and roots. Feigning death is one of the opossum’s principal defense mechanisms. This confuses its predators, protecting the opossum from danger.","prompt":"The word feigning in the passage is closest in meaning to","options":["imagining","enacting","pretending","displaying"],"answer":2,"target":"feigning"}]},{"lesson":15,"words":[{"word":"adhere","def_lines":[],"pos":"v","definition":"to stick to or follow precisely","forms":[{"pos":"n","word":"adherence"}],"synonyms":["comply"],"examples":["Travelers must adhere to the laws of the country they are visiting.","The referee’s excessively strict adherence to the rules upset the players."],"lesson":15,"id":"15-1"},{"word":"durable","def_lines":[],"pos":"adj","definition":"something that lasts a long time *time during which something lasts","forms":[{"pos":"n","word":"durability"},{"pos":"n","word":"duration*"}],"synonyms":["sturdy"],"examples":["It was a durable refrigerator, but it finally broke.","The durability of tires is a key factor in determining their quality."],"lesson":15,"id":"15-2"},{"word":"foster","def_lines":[],"pos":"v","definition":"to promote growth or development","forms":[],"synonyms":["stimulate"],"examples":["The industrial revolution fostered the rise of the middle class.","Parents usually foster the development of good habits in their children."],"lesson":15,"id":"15-3"},{"word":"gain","def_lines":[],"pos":"v","definition":"to obtain something needed or useful; to increase to the amount of something","forms":[{"pos":"adj","word":"gainful"},{"pos":"n","word":"gain"}],"synonyms":["attain"],"examples":["He gained a lot of experience working as a volunteer.","His gain in knowledge was impressive."],"lesson":15,"id":"15-4"},{"word":"halt","def_lines":[],"pos":"v","definition":"to stop or discontinue","forms":[{"pos":"adv","word":"haltingly"},{"pos":"adj","word":"halting"},{"pos":"n","word":"halt"}],"synonyms":["stop"],"examples":["Bus service to the city was halted due to poor road conditions.","The supervisor put a halt to the tardiness of the employees."],"lesson":15,"id":"15-5"},{"word":"handle","def_lines":[],"pos":"v","definition":"to deal with or control","forms":[{"pos":"n","word":"handling"}],"synonyms":["manage"],"examples":["They handled themselves very well given the circumstances.","The president’s handling of the crisis was widely applauded."],"lesson":15,"id":"15-6"},{"word":"harbor","def_lines":[],"pos":"v","definition":"to give protection; to not express a desire or opinion, usually bad","forms":[],"synonyms":["shelter"],"examples":["He harbors ill feelings for her.","They harbored the political refugee in their home."],"lesson":15,"id":"15-7"},{"word":"harmful","def_lines":[],"pos":"adj","definition":"something that causes pain or damage","forms":[{"pos":"adv","word":"harmfully"},{"pos":"v","word":"harm"},{"pos":"n","word":"harm"}],"synonyms":["unhealthy"],"examples":["Excessive radiation is harmful to the body.","Bleach harms certain fabrics."],"lesson":15,"id":"15-8"},{"word":"insignificant","def_lines":[],"pos":"adj","definition":"not important; of little value","forms":[{"pos":"adv","word":"insignificantly"},{"pos":"n","word":"insignificance"}],"synonyms":["meaningless"],"examples":["The amount of rainfall this summer has been insignificant.","The insignificance of his comment became apparent with the passing of time."],"lesson":15,"id":"15-9"},{"word":"mysterious","def_lines":[],"pos":"adj","definition":"not easily understood or figured out","forms":[{"pos":"adv","word":"mysteriously"},{"pos":"n","word":"mystery"},{"pos":"n","word":"mysteriousness"}],"synonyms":["baffling"],"examples":["He had a mysterious effect on everyone who heard him speak.","The man’s disappearance was a mystery."],"lesson":15,"id":"15-10"},{"word":"perilous","def_lines":[],"pos":"adj","definition":"threatening or risky; harmful","forms":[{"pos":"adv","word":"perilously"},{"pos":"n","word":"peril"}],"synonyms":["dangerous"],"examples":["It is perilous to exceed the speed limit.","There are ample perils in the sport of mountain climbing."],"lesson":15,"id":"15-11"},{"word":"promote","def_lines":[],"pos":"v","definition":"to encourage or advertise; to elevate in rank or grade","forms":[{"pos":"n","word":"promoter"},{"pos":"n","word":"promotion"}],"synonyms":["boost"],"examples":["Many nations promote tourism to lure foreign currency.","The customers responded favorably to the half-price promotion."],"lesson":15,"id":"15-12"},{"word":"redundant","def_lines":[],"pos":"adj","definition":"being excessive; showing unnecessary repetition","forms":[{"pos":"n","word":"redundancy"},{"pos":"adv","word":"redundantly"}],"synonyms":["repetitious"],"examples":["Students who ask teachers to “repeat that again” are being redundant because “repeat” means “again.”","Lush, redundant vegetation is common in tropical climates."],"lesson":15,"id":"15-13"},{"word":"reject","def_lines":[],"pos":"v","definition":"to refuse","forms":[{"pos":"n","word":"rejection"}],"synonyms":["refuse"],"examples":["The insurance company rejected the claim.","The rejection of his work was difficult for him to understand."],"lesson":15,"id":"15-14"},{"word":"substantial","def_lines":[],"pos":"adj","definition":"important; strongly made; of value","forms":[{"pos":"adv","word":"substantially"},{"pos":"adj","word":"substantive"}],"synonyms":["significant"],"examples":["The discovery of a vaccine for smallpox was a substantial medical achievement.","This substantive article will change your opinion of rock music."],"lesson":15,"id":"15-15"},{"word":"trait","def_lines":[],"pos":"n","definition":"specific qualities that distinguish one from another","forms":[],"synonyms":["characteristic"],"examples":["Her sense of humor and cheerful personality are some of her most impressive traits.","Alma’s blonde hair is a trait inherited from her father."],"lesson":15,"id":"15-16"},{"word":"underscore","def_lines":[],"pos":"v","definition":"to make evident or emphasize","forms":[],"synonyms":["highlight"],"examples":["The high quality of the student’s science fair project underscored her talent in biology.","The conclusion of the report should underscore its main ideas."],"lesson":15,"id":"15-17"}],"matching":[{"n":1,"word":"foster","options":["exaggerate","stimulate","gain","enhance"],"answer":1},{"n":2,"word":"halt","options":["evaporate","avoid","defy","stop"],"answer":3},{"n":3,"word":"trait","options":["dwelling","characteristic","function","abundance"],"answer":1},{"n":4,"word":"durable","options":["ample","crucial","dominant","sturdy"],"answer":3},{"n":5,"word":"redundant","options":["repetitious","creative","round","active"],"answer":0},{"n":6,"word":"substantial","options":["haphazard","diverse","significant","perilous"],"answer":2},{"n":7,"word":"underscore","options":["shelter","highlight","boost","exaggerate"],"answer":1},{"n":8,"word":"mysterious","options":["unhealthy","dangerous","dramatic","baffling"],"answer":3},{"n":9,"word":"insignificant","options":["meaningless","rudimentary","vigorous","spacious"],"answer":0},{"n":10,"word":"adhere","options":["exhaust","reject","comply","withstand"],"answer":2}],"tests":[{"n":1,"passage":"Scientists can only speculate on the possible fate of the Cosmos. If the universe is unbound, there is little possibility that its expansion will halt. Thus, eventually the galaxies and stars will all die. The Cosmos then would be a cold, dark, and virtually empty place. If the universe is bound, the mass and energy content will come together again in a big fiery squeeze.","prompt":"The word halt in the passage is closest in meaning to","options":["continue","stop","expand","intensify"],"answer":1,"target":"halt"},{"n":2,"passage":"The perception of depth and distance depends on information transmitted through various sense organs. Sensory cues indicate the distance at which objects are located from the individual and from each other. The senses of sight and hearing transmit depth and distance cues that are substantially independent of one another.","prompt":"The word substantially in the passage is closest in meaning to","options":["significantly","absurdly","critically","vigorously"],"answer":0,"target":"substantially"},{"n":3,"passage":"Because the needs of human communication are so various, the study of meaning is probably the most difficult and mysterious aspect of serious language study. Traditionally, language has been defined as the expression of thought. But this idea is far too narrow an interpretation of language and far too broad a view of thought to be worthwhile. The expression of thought is just one of the many roles of language.","prompt":"The word mysterious in the passage is closest in meaning to","options":["substantial","meaningful","promising","baffling"],"answer":3,"target":"mysterious"},{"n":4,"passage":"The theory of environmental determinism says that the physical surroundings of a people, including natural resources, climate, and geography, are the major determining factors in the development of their culture. Therefore, determinism rejects the idea that history and tradition, social and economic factors, and other elements of culture explain social development.","prompt":"The word rejects in the passage is closest in meaning to","options":["refuses","ignores","promotes","withstands"],"answer":0,"target":"rejects"},{"n":5,"passage":"The greatest benefit of a regular exercise program is an improvement in overall fitness. Appropriate exercise boosts muscular strength and endurance, flexibility, and cardiorespiratory endurance. The level of maximum oxygen intake or cardiorespiratory endurance is usually not of great importance to most individuals. The most important thing is to attain their maximum level of performance.","prompt":"The word boosts in the passage is closest in meaning to","options":["harms","manages","promotes","alters"],"answer":2,"target":"boosts"},{"n":6,"passage":"The number of giant pandas in the world is dwindling. The chief reason is that their natural habitat in China has been reduced as bamboo forests have been cleared to increase available land for China’s vast human population. In fact, the world came perilously close to losing the panda altogether in the 1980s as a result. Today, the panda’s future is brighter. The Chinese government now protects most of the panda’s natural habitat.","prompt":"In saying that the world came perilously close to losing the panda, the author means that the giant panda","options":["has been set free from zoos.","endangered human beings.","threatened the extinction of bamboo.","was nearly entirely eliminated."],"answer":3,"target":""},{"n":7,"passage":"Several pilots were killed during the competition for the Orteig Prize, which was promised to the first pilot to fly nonstop from New York to Paris. Charles Lindbergh believed he could win it if he had the right airplane, and he was right. He received the $25,000 prize in 1927 for being the first to make the perilous flight across the Atlantic.","prompt":"The word perilous in the passage is closest in meaning to","options":["substantial","dangerous","haphazard","prosperous"],"answer":1,"target":"perilous"},{"n":8,"passage":"In parts of the world that lack modern sewage treatment plants, water carrying human waste can flow into drinking water supplies. Disease- carrying bacteria in the waste can make the drinking water harmful. Even in certain U.S. cities, such contaminants have been found in urban water supplies.","prompt":"The word harmful in the passage is closest in meaning to","options":["frail","adverse","conspicuous","unhealthy"],"answer":3,"target":"harmful"},{"n":9,"passage":"Commercial arbitration has been practiced in European countries for many years. In the United States, commercial arbitration to handle disputes is gaining in popularity. The American Arbitration Association hires panels of arbitrators who mediate disagreements and propose solutions. The decisions of these panels have been enforced by the courts of many states.","prompt":"The word handle in the passage is closest in meaning to","options":["face","manage","enact","promote"],"answer":1,"target":"handle"},{"n":10,"passage":"Martin Luther King Jr. had a magnificent speaking ability. This quality enabled him to effectively express African-Americans’ need for social justice. He gained the support of millions of people, both black and white, through his eloquent pleas for nonviolent social action. He received international acclaim when he was awarded the 1964 Nobel Peace Prize, after many years of struggle to assure basic civil rights for all citizens.","prompt":"The word gained in the passage is closest in meaning to","options":["observed","created","extended","attained"],"answer":3,"target":"gained"}]},{"lesson":16,"words":[{"word":"conscientious","def_lines":[],"pos":"adj","definition":"showing serious purpose; one who works carefully and with enthusiasm","forms":[{"pos":"adv","word":"conscientiously"}],"synonyms":["meticulous"],"examples":["She is a conscientious representative of the student body.","They approached the task conscientiously."],"lesson":16,"id":"16-1"},{"word":"convey","def_lines":[],"pos":"v","definition":"to make something known to others; to communicate","forms":[],"synonyms":["communicate"],"examples":["The manager of the store conveyed his displeasure directly to the workers.","He was able to convey his message to the audience with ease."],"lesson":16,"id":"16-2"},{"word":"encompass","def_lines":[],"pos":"v","definition":"to surround completely; to envelop","forms":[],"synonyms":["include"],"examples":["Her plan of study encompasses every aspect of computer science.","The course encompasses all the literature of the nineteenth century."],"lesson":16,"id":"16-3"},{"word":"expansion","def_lines":[],"pos":"n","definition":"the act of making larger","forms":[{"pos":"adj","word":"expandable"},{"pos":"v","word":"expand"},{"pos":"n","word":"expansion"}],"synonyms":["growth"],"examples":["Expansion occurs when matter is heated.","The laboratory is expanding its capacity to produce computer chips."],"lesson":16,"id":"16-4"},{"word":"heighten","def_lines":[],"pos":"v","definition":"to cause to become greater","forms":[{"pos":"adj","word":"heightened"},{"pos":"n","word":"height"}],"synonyms":["intensify"],"examples":["A very successful interview can heighten a candidate’s chances to get a job.","The public was in a heightened state of nervousness as the hurricane approached."],"lesson":16,"id":"16-5"},{"word":"highlight","def_lines":[],"pos":"v","definition":"to emphasize the part of a greater whole","forms":[{"pos":"n","word":"highlight"}],"synonyms":["emphasize"],"examples":["The owner’s manual highlights the basic functions of the camera.","The final goal was the highlight of the game."],"lesson":16,"id":"16-6"},{"word":"inadvertently","def_lines":[],"pos":"adv","definition":"by accident; without paying attention; unexpectedly","forms":[{"pos":"adj","word":"inadvertent"}],"synonyms":["carelessly"],"examples":["The reporters had inadvertently failed to include the name of one of the dignitaries.","His inadvertent calculation caused him to derive the wrong answer."],"lesson":16,"id":"16-7"},{"word":"inevitable","def_lines":[],"pos":"adj","definition":"something that cannot be prevented","forms":[{"pos":"adv","word":"inevitably from happening"},{"pos":"n","word":"inevitability"}],"synonyms":["unavoidable"],"examples":["When two weather systems meet, unsettled weather conditions are inevitable.","The inevitability of the outcome made the challenge less exciting."],"lesson":16,"id":"16-8"},{"word":"infancy","def_lines":[],"pos":"n","definition":"in the beginning stages of development","forms":[{"pos":"adj","word":"infantile"},{"pos":"n","word":"infant"}],"synonyms":["beginning"],"examples":["The new theory is in its infancy and will be thoroughly tested by its critics.","The author’s infantile writing style appeals to young readers."],"lesson":16,"id":"16-9"},{"word":"mimic","def_lines":[],"pos":"v","definition":"to copy an action","forms":[{"pos":"n","word":"mimicker"}],"synonyms":["imitate"],"examples":["The comedian mimicked the president’s gestures.","Parrots mimic the speech that they hear in their surroundings."],"lesson":16,"id":"16-10"},{"word":"paramount","def_lines":[],"pos":"adj","definition":"to be of highest importance","forms":[{"pos":"adv","word":"paramountly"},{"pos":"n","word":"paramountcy"}],"synonyms":["foremost"],"examples":["The club’s paramount goal is to raise awareness of the importance of community service.","Being quiet is of paramount importance while watching a movie at the theater."],"lesson":16,"id":"16-11"},{"word":"proficient","def_lines":[],"pos":"adj","definition":"to be skilled or experienced in something","forms":[{"pos":"adv","word":"proficiently"},{"pos":"n","word":"proficiency"}],"synonyms":["competent"],"examples":["The exam will test the students’ proficiency in the Portuguese language.","Highly proficient athletes earn the privilege of competing in the Olympics."],"lesson":16,"id":"16-12"},{"word":"retrieve","def_lines":[],"pos":"v","definition":"to find and bring back","forms":[{"pos":"adj","word":"retrieved"},{"pos":"n","word":"retrieval"}],"synonyms":["recover"],"examples":["Will Detroit retrieve its status as the car manufacturing center of the world?","This computerized information retrieval system is the most up-to-date system available."],"lesson":16,"id":"16-13"},{"word":"systematically","def_lines":[],"pos":"adv","definition":"done according to a plan","forms":[{"pos":"adj","word":"systematic"},{"pos":"n","word":"system"}],"synonyms":["methodically"],"examples":["The plan was developed systematically by a team of experts.","Systematic changes in foreign policy have been proposed."],"lesson":16,"id":"16-14"},{"word":"unlikely","def_lines":[],"pos":"adj","definition":"not probable","forms":[],"synonyms":["doubtful"],"examples":["Rain is unlikely to occur during the dry season.","It is unlikely that he will want to attend the conference."],"lesson":16,"id":"16-15"},{"word":"unwarranted","def_lines":[],"pos":"adj","definition":"without good reason or cause; inappropriate","forms":[],"synonyms":["unjustified"],"examples":["His negative reaction was unwarranted.","The motorist felt that the ticket for the infraction was unwarranted."],"lesson":16,"id":"16-16"},{"word":"zenith","def_lines":[],"pos":"n","definition":"the highest point","forms":[],"synonyms":["apex"],"examples":["He reached the zenith of his profession at a very young age.","The publication of the book represented the zenith of his career."],"lesson":16,"id":"16-17"}],"matching":[{"n":1,"word":"convey","options":["intensify","promote","communicate","engender"],"answer":2},{"n":2,"word":"proficient","options":["suitable","persistent","competent","inevitable"],"answer":2},{"n":3,"word":"growth","options":["expansion","function","highlight","recover"],"answer":0},{"n":4,"word":"meticulously","options":["haphazardly","conscientiously","inadvertently","conspicuously"],"answer":1},{"n":5,"word":"retrieve","options":["disperse","recover","accelerate","broaden"],"answer":1},{"n":6,"word":"encompass","options":["emphasize","gain","heighten","include"],"answer":3},{"n":7,"word":"apex","options":["facet","zenith","trait","flaw"],"answer":1},{"n":8,"word":"systematically","options":["unexpectedly","persuasively","astoundingly","methodically"],"answer":3},{"n":9,"word":"paramount","options":["likely","foremost","appealing","meticulous"],"answer":1},{"n":10,"word":"mimic","options":["exceed","imitate","astonish","highlight"],"answer":1}],"tests":[{"n":1,"passage":"The first elevated rail system was successfully operated in New York City in 1871, using steam power. Because steam power had many disadvantages, the lines were later electrified. An extensive network of elevated lines was built in New York City. It was in service for many years, but was systematically eliminated because of its antiquated appearance and because it contributed to traffic congestion.","prompt":"The word systematically in the passage is closest in meaning to","options":["inadvertently","appropriately","meticulously","methodically"],"answer":3,"target":"systematically"},{"n":2,"passage":"Municipal solid waste must be collected and treated in order to reduce the total volume and weight of the material that requires final disposal. Treatment changes the form of the waste and makes it easier to handle. It can also be used to recover certain materials, as well as heat energy, for recycling or reuse.","prompt":"The word recover in the passage is closest in meaning to","options":["retrieve","convey","deplete","develop"],"answer":0,"target":"recover"},{"n":3,"passage":"American biographer and historian Samuel Eliot Morrison colorfully recreated notable stories of modern history. Combining a gift for storytelling with meticulous scholarship, he took the reader back into history to relive the adventures of such characters as Ferdinand Magellan, Christopher Columbus, and Sir Francis Drake. He also recorded the accomplishments of the U.S. Navy during World War II.","prompt":"The word meticulous in the passage is closest in meaning to","options":["unwarranted","infantile","valid","conscientious"],"answer":3,"target":"meticulous"},{"n":4,"passage":"Space medicine protects human beings from the environment of space and studies their reactions to that environment. The foundations of space medicine can be traced to aviation medicine. The term aerospace medicine has evolved to encompass practice in both areas. Aerospace medicine has been a certified subspecialty of the American Board of Preventive Medicine since 1953.","prompt":"The word encompass in the passage is closest in meaning to","options":["favor","promote","emphasize","include"],"answer":3,"target":"encompass"},{"n":5,"passage":"If some motion is possible according to physical laws, then a motion in which events appear in reverse order is also possible. For example, it would be unusual to observe a real process in which a vase broken on the floor collects itself and flies up whole into a person’s hand. Nevertheless, according to known physical laws, such a process is not impossible, although it is too unlikely to expect it to actually happen.","prompt":"The word unlikely in the passage is closest in meaning to","options":["difficult","doubtful","astonishing","superficial"],"answer":1,"target":"unlikely"},{"n":6,"passage":"In 1896 a Swedish chemist first assessed the effects of greenhouse gases. He showed that activities such as burning coal, destroying forests, and even raising cattle dangerously increase atmospheric concentrations of such gases as carbon dioxide, methane, and nitrous oxide. Since then, heightened awareness of the effects cars and factories have on the environment has led to more concern about these gas concentrations. Recently they have been blamed for an apparent warming trend in Earth’s atmosphere.","prompt":"In referring to heightened awareness, the author means that people are","options":["less conscious of the situation.","more conscious of the situation.","unconcerned about the problem.","ashamed that the problem exists."],"answer":1,"target":""},{"n":7,"passage":"Great technological advances were made during the infancy of the United States’ industrial growth. But the modern trends of the 1920s brought about problems as well as benefits. Many Americans had trouble adjusting to the impersonal, fast-paced life of cities. The complex life in cities tended to weaken the strong family ties that had always been part of American society.","prompt":"The word infancy in the passage is closest in meaning to","options":["prime","beginnings","miracle","ambiguity"],"answer":1,"target":"infancy"},{"n":8,"passage":"Careful testing is one of a pharmaceutical company’s most important responsibilities. Pharmaceutical companies and the Food and Drug Administration constantly guard against the possibility of a harmful drug being sold to the public. But even the most careful testing cannot always reveal the possibility that a drug may produce an inadvertent harmful effect.","prompt":"The word inadvertent in the passage is closest in meaning to","options":["acute","unlikely","agilely","unexpected"],"answer":3,"target":"inadvertent"},{"n":9,"passage":"Basketball was invented by a Canadian in 1891. Today, it is the world’s most popular indoor sport. Basketball emphasizes teamwork and the athletic qualities of endurance, agility, and skill. Tall players have an advantage because they can reach closer to the basket or above other players to shoot and rebound the ball. But smaller players also make contributions to their teams as shooters and ball handlers.","prompt":"The word emphasizes in the passage is closest in meaning to","options":["encompasses","elaborates","highlights","enhances"],"answer":2,"target":"emphasizes"},{"n":10,"passage":"Daniel Webster was a well-known American speaker, and one of the most capable lawyers and statesmen of his time. He used his speaking ability to establish a strong national government in the Senate. He also applied the speaking skills he had mastered as a lawyer to heighten his appeal for the end to slavery.","prompt":"The word heighten in the passage is closest in meaning to","options":["intensify","persuade","enhance","convey"],"answer":0,"target":"heighten"}]},{"lesson":17,"words":[{"word":"agitate","def_lines":[],"pos":"v","definition":"to shake or move; to cause worry","forms":[{"pos":"n","word":"agitation"},{"pos":"n","word":"agitator"}],"synonyms":["disturb"],"examples":["The fact that she had not arrived by midnight agitated her parents.","He was known as a political agitator."],"lesson":17,"id":"17-1"},{"word":"comply","def_lines":[],"pos":"v","definition":"to agree to follow a request or command; to adhere to specific standards","forms":[{"pos":"adj","word":"compliant"},{"pos":"n","word":"compliance"}],"synonyms":["acquiesce"],"examples":["A well-trained dog will comply when told to sit.","Students must maintain a B average to remain in compliance with the scholarship’s rules."],"lesson":17,"id":"17-2"},{"word":"confidential","def_lines":[],"pos":"adj","definition":"to be said or written in secret","forms":[{"pos":"v","word":"confide"},{"pos":"adj","word":"confidential"},{"pos":"adv","word":"confidentially"},{"pos":"n","word":"confidant"}],"synonyms":["secret"],"examples":["We were told that the information is strictly confidential.","She confided to me that she had always wanted to be a movie star."],"lesson":17,"id":"17-3"},{"word":"delighted","def_lines":[],"pos":"adj","definition":"to be satisfied; very happy","forms":[{"pos":"adj","word":"delightfully"},{"pos":"adj","word":"delightful"},{"pos":"n","word":"delight"}],"synonyms":["elated"],"examples":["He was delighted with the results of the experiment.","It was a delightful afternoon."],"lesson":17,"id":"17-4"},{"word":"discreetly","def_lines":[],"pos":"adv","definition":"in a careful, polite manner","forms":[{"pos":"adj","word":"discreet"}],"synonyms":["cautiously"],"examples":["The teacher discreetly told the parents about their child’s inappropriate behavior.","You can count on me to be discreet."],"lesson":17,"id":"17-5"},{"word":"documented","def_lines":[],"pos":"adj","definition":"proven with written evidence","forms":[{"pos":"adj","word":"documentary"},{"pos":"v","word":"document"},{"pos":"n","word":"documentation"}],"synonyms":["proven"],"examples":["He had documented proof that the bank had made an error.","The car’s documentation was in order."],"lesson":17,"id":"17-6"},{"word":"evoke","def_lines":[],"pos":"v","definition":"to call up or produce memories or feelings; to cause to remember","forms":[],"synonyms":["remind"],"examples":["Hearing her favorite song evoked fond memories of her high school years.","Most sounds evoke hints of time and place."],"lesson":17,"id":"17-7"},{"word":"gradually","def_lines":[],"pos":"adv","definition":"slowly, but surely","forms":[{"pos":"adj","word":"gradual"}],"synonyms":["steadily"],"examples":["The bay has gradually deteriorated over the years.","There has been a gradual change in the climate over the past decade."],"lesson":17,"id":"17-8"},{"word":"impartial","def_lines":[],"pos":"adj","definition":"showing no favoritism; being fair or just","forms":[{"pos":"n","word":"impartiality"}],"synonyms":["objective"],"examples":["Teachers must be impartial judges of their students’ work.","Judges are known for their impartiality."],"lesson":17,"id":"17-9"},{"word":"inordinate","def_lines":[],"pos":"adj","definition":"a large amount or quantity; more than reasonable","forms":[{"pos":"adv","word":"inordinately"}],"synonyms":["excessive"],"examples":["The airlines had to cancel an inordinate number of flights due to the fog.","There was an inordinately large number of whales off the coast."],"lesson":17,"id":"17-10"},{"word":"instantly","def_lines":[],"pos":"adv","definition":"happening immediately; in a short period of time","forms":[{"pos":"adj","word":"instantaneous"},{"pos":"adj","word":"instant"},{"pos":"n","word":"instant"}],"synonyms":["immediately"],"examples":["The computer finished the job instantly.","It happened in an instant."],"lesson":17,"id":"17-11"},{"word":"intentionally","def_lines":[],"pos":"adv","definition":"with definite purpose and planning","forms":[{"pos":"adj","word":"intentional"},{"pos":"n","word":"intention"},{"pos":"n","word":"intent"}],"synonyms":["deliberately"],"examples":["The machine was left on intentionally.","Her action was an indication of her good intentions."],"lesson":17,"id":"17-12"},{"word":"intrinsic","def_lines":[],"pos":"adj","definition":"being a primary part of something","forms":[{"pos":"adv","word":"intrinsically"}],"synonyms":["inherent"],"examples":["A penny has little intrinsic value.","The forests of the Northwest are intrinsically rich in natural resources."],"lesson":17,"id":"17-13"},{"word":"inundate","def_lines":[],"pos":"v","definition":"to flood","forms":[{"pos":"n","word":"inundation"}],"synonyms":["overwhelm"],"examples":["The radio stations were inundated with reports of a severe traffic accident.","The foundation experienced an inundation of requests for money."],"lesson":17,"id":"17-14"},{"word":"mindset","def_lines":[],"pos":"n","definition":"an established attitude or mood","forms":[],"synonyms":["mentality"],"examples":["A person is more likely to succeed if he or she approaches projects with a positive mindset.","The political mindset is different in every region of the country."],"lesson":17,"id":"17-15"},{"word":"nominal","def_lines":[],"pos":"adj","definition":"very small; in form, but not in substance","forms":[{"pos":"adv","word":"nominally"}],"synonyms":["moderate"],"examples":["The office building was sold at a nominal price.","She was nominally successful as an actress."],"lesson":17,"id":"17-16"},{"word":"presumably","def_lines":[],"pos":"adv","definition":"reported, but not confirmed","forms":[{"pos":"adj","word":"presumable"},{"pos":"v","word":"presume"},{"pos":"n","word":"presumption"}],"synonyms":["supposedly"],"examples":["The old wreck was presumably located southwest of Florida.","I presume that you have been camping before."],"lesson":17,"id":"17-17"}],"matching":[{"n":1,"word":"impartial","options":["objective","overwhelmed","conscientious","confident"],"answer":0},{"n":2,"word":"diminutive","options":["conscientious","minuscule","conspicuous","obvious"],"answer":1},{"n":3,"word":"documented","options":["proven","intrinsic","substantial","durable"],"answer":0},{"n":4,"word":"nominal","options":["moderate","inherent","inevitable","harmful"],"answer":0},{"n":5,"word":"excessive","options":["impressive","lasting","deliberate","inordinate"],"answer":3},{"n":6,"word":"discreetly","options":["obviously","cautiously","unlikely","deceptively"],"answer":1},{"n":7,"word":"agitate","options":["heighten","reject","inundate","disturb"],"answer":3},{"n":8,"word":"steadily","options":["gradually","uniquely","intentionally","immediately"],"answer":0},{"n":9,"word":"mentality","options":["mindset","proficiency","docility","jargon"],"answer":0},{"n":10,"word":"delighted","options":["involved","elated","overwhelm","highlight"],"answer":1}],"tests":[{"n":1,"passage":"Modes of suggestion, while usually verbal, may be visual or involve other senses. In fact, a mere suggestion may evoke a memory that causes a specific reaction. For instance, a person who is allergic to roses may develop an attack of asthma just from looking at a seed catalog. The element of suggestion also plays a significant role in group behavior and hypnosis.","prompt":"The word evoke in the passage is closest in meaning to","options":["produce","engross","emit","favor"],"answer":0,"target":"evoke"},{"n":2,"passage":"The American actor-director Orson Welles worked on the stage and in films for nearly 50 years. Yet his fame rests principally on two projects. The first, his 1938 radio adaptation of H. G. Wells’s The War of the Worlds, was a fictitious eyewitness report of a Martian attack. The radio broadcast created a panic among listeners who, believing the attack to be real, inundated law enforcement agencies with numerous inquiries.","prompt":"The word inundated in the passage is closest in meaning to","options":["agitated","overwhelmed","astonished","delighted"],"answer":1,"target":"inundated"},{"n":3,"passage":"The use of cast-metal pieces as a medium of exchange is an ancient tradition. It probably developed out of the use in commerce of ordinary ingots of bronze and other metals that had an intrinsic value. Until the development of bills of exchange in medieval Europe and paper currency in medieval China, metal coins were the only means of exchange for goods and services.","prompt":"The word intrinsic in the passage is closest in meaning to","options":["inherent","nominal","documented","inordinate"],"answer":0,"target":"intrinsic"},{"n":4,"passage":"The stimuli in a projective test are intentionally ambiguous and open to diverse interpretations so that each person will project his unique reactions in his answers. Techniques for evaluating such responses range from the intuitive impressions of the rater to complex schemes for scoring and interpretation that require extensive calculations and interpretation.","prompt":"The word intentionally in the passage is closest in meaning to","options":["confidentially","fundamentally","arbitrarily","deliberately"],"answer":3,"target":"intentionally"},{"n":5,"passage":"Anaximander argued that human beings are so helpless at birth that they would instantly die if left on their own. He also argued that known elements are continuously opposing and changing into one another and that as a result something different from these elements must underlie and cause changes.","prompt":"The word instantly in the passage is closest in meaning to","options":["gradually","presumably","immediately","discreetly"],"answer":2,"target":"instantly"},{"n":6,"passage":"Some economists resist the notion that cutting taxes is beneficial. Theoretically, decreasing taxes returns money to citizens, therefore increasing jobs and improving conditions for everyone. Some economists say that will happen only with a large, sudden tax reduction. A gradual decrease, they say, will not stimulate spending or result in more jobs or a stronger economy. Still others oppose tax reduction altogether.","prompt":"In referring to a gradual decrease in taxes, the author means one that","options":["is imposed all at once.","occurs slowly over time.","stimulates a lot of jobs.","affects everyone equally."],"answer":1,"target":""},{"n":7,"passage":"Without exception, children of Southwest Indian tribes were treated with warmth and submissiveness during the period of infancy. Weaning was gradual, and training in cleanliness was delayed until a child could walk. Care was taken so that the children were not unduly agitated, and that they were protected from harm.","prompt":"The word agitated in the passage is closest in meaning to","options":["disturbed","inundated","favored","exhausted"],"answer":0,"target":"agitated"},{"n":8,"passage":"Most Latin-American countries achieved nominal independence in the ninteenth century. Yet they remained politically, economically, and culturally dependent on U.S. and European powers throughout the first half of the twentieth century. By 1960, people believed that this dependency could best be alleviated through educational reform.","prompt":"The word nominal in the passage is closest in meaning to","options":["scarce","durable","gradual","moderate"],"answer":3,"target":"nominal"},{"n":9,"passage":"Opinion polls have been developed since the 1930s. Polls are a scientific way of learning what large numbers of people think about various topics. They are used extensively in politics and business. In both fields many polling companies provide political candidates and businesses with confidential information about their public image.","prompt":"The word confidential in the passage is closest in meaning to","options":["discreet","mysterious","secret","classified"],"answer":2,"target":"confidential"},{"n":10,"passage":"At a meeting to discuss the federal Constitution, John Hancock was persuaded to support ratification. To get Hancock’s support, some people promised him a nomination for the presidency if George Washington declined. Though appearing to be among the leaders of the revolutionaries, he was not considered an independent figure. Rather, he was a tool of Samuel Adams, who took advantage of Hancock’s ambition, vanity, and inordinate love of popularity.","prompt":"The word inordinate in the passage is closest in meaning to","options":["excessive","unwarranted","exhaustive","overwhelming"],"answer":0,"target":"inordinate"}]},{"lesson":18,"words":[{"word":"absurd","def_lines":[],"pos":"adj","definition":"clearly false; without reason","forms":[{"pos":"adv","word":"absurdly"},{"pos":"n","word":"absurdity"}],"synonyms":["ridiculous"],"examples":["Confidentially, I think his suggestion is absurd.","They are absurdly irrational about the issue."],"lesson":18,"id":"18-1"},{"word":"allocation","def_lines":[],"pos":"n","definition":"a share; a part set aside for a special purpose; an assignment of portions","forms":[{"pos":"adj","word":"allocated"},{"pos":"v","word":"allocate"}],"synonyms":["distribution"],"examples":["His allocation of materials was gradually used up.","Allocating office space in the building was a difficult task."],"lesson":18,"id":"18-2"},{"word":"balanced","def_lines":[],"pos":"adj","definition":"a state where everything is of the same size or weight; an element on one side that counters an equal element on the other","forms":[{"pos":"v","word":"balance"},{"pos":"n","word":"balance"}],"synonyms":["equalized"],"examples":["He made a balanced presentation of both points of view.","The museum contains a pleasant balance of paintings from the eighteenth and nineteenth centuries."],"lesson":18,"id":"18-3"},{"word":"come across","def_lines":[],"pos":"v","definition":"to find or discover, usually by chance or mistake","forms":[],"synonyms":["encounter"],"examples":["The woman came across the old love letters while looking through photos of her youth.","The professor came across the article while searching the Internet."],"lesson":18,"id":"18-4"},{"word":"culminate","def_lines":[],"pos":"v","definition":"to finish; to reach a climax or the highest point","forms":[{"pos":"n","word":"culmination"},{"pos":"adj","word":"culminating"}],"synonyms":["conclude"],"examples":["The rock song culminated in a loud guitar solo.","After four years of diligent study, the student’s hard work culminated in several offers of full scholarships for college."],"lesson":18,"id":"18-5"},{"word":"demeanor","def_lines":[],"pos":"n","definition":"someone’s outward appearance or behavior","forms":[],"synonyms":["conduct (n.)"],"examples":["The old woman had a pleasant demeanor.","The dog was huge, but its friendly demeanor eased my fears."],"lesson":18,"id":"18-6"},{"word":"exert","def_lines":[],"pos":"v","definition":"to put into use; to put forth an effort","forms":[{"pos":"n","word":"exertion"}],"synonyms":["apply"],"examples":["He had to exert all of his strength to move the heavy box.","Your body will be better prepared for physical exertion if you exercise daily."],"lesson":18,"id":"18-7"},{"word":"fallacious","def_lines":[],"pos":"adj","definition":"having errors","forms":[{"pos":"adv","word":"fallaciously"},{"pos":"n","word":"fallacy"}],"synonyms":["incorrect"],"examples":["Her fallacious argument could not be defended.","It is a fallacy to think that money will bring you happiness."],"lesson":18,"id":"18-8"},{"word":"feasible","def_lines":[],"pos":"adj","definition":"able to be done","forms":[{"pos":"adv","word":"feasibly"},{"pos":"n","word":"feasibility"}],"synonyms":["possible"],"examples":["It is a feasible design for the high-rise building.","Before they begin the project, a study must be done of its feasibility."],"lesson":18,"id":"18-9"},{"word":"lack","def_lines":[],"pos":"n","definition":"a need for; an insufficient amount","forms":[{"pos":"adj","word":"lacking"},{"pos":"v","word":"lack"}],"synonyms":["shortage"],"examples":["There was an inordinate lack of rain last fall.","The mathematician was lacking in communication skills."],"lesson":18,"id":"18-10"},{"word":"limber","def_lines":[],"pos":"adj","definition":"to be stretched; easily shaped","forms":[],"synonyms":["flexible"],"examples":["The dancer has a limber body.","She was able to make the limber movements that are required of gymnasts."],"lesson":18,"id":"18-11"},{"word":"means","def_lines":[],"pos":"n","definition":"ways","forms":[],"synonyms":["methods"],"examples":["He was told to finish the job by any means available to him.","The most convenient means of communicating with someone is by phone."],"lesson":18,"id":"18-12"},{"word":"narrow","def_lines":[],"pos":"adj","definition":"small from one side to the other; limited","forms":[{"pos":"adv","word":"narrowly"},{"pos":"n","word":"narrowness"}],"synonyms":["thin"],"examples":["The canal was extremely narrow.","The driver narrowly escaped injury when his car ran off the road."],"lesson":18,"id":"18-13"},{"word":"preconception","def_lines":[],"pos":"n","definition":"an opinion formed in advance without experience or knowledge of something","forms":[{"pos":"adj","word":"preconceived"},{"pos":"v","word":"preconceive"}],"synonyms":["bias"],"examples":["It is difficult to overcome preconceptions if we are not open to new ideas.","His preconceived notions about Los Angeles disappeared after he visited the city."],"lesson":18,"id":"18-14"},{"word":"robust","def_lines":[],"pos":"adj","definition":"showing good health; in good shape","forms":[{"pos":"adv","word":"robustly"},{"pos":"n","word":"robustness"}],"synonyms":["energetic"],"examples":["The robust economy is expected to continue growing quickly.","The new product is selling robustly."],"lesson":18,"id":"18-15"},{"word":"steady","def_lines":[],"pos":"adj","definition":"firm; in a fixed position; without change; reliable; dependable","forms":[{"pos":"adv","word":"steadily"},{"pos":"v","word":"steady"},{"pos":"n","word":"steadiness"}],"synonyms":["constant"],"examples":["Steady growth is projected for companies involved in genetic engineering.","The secretary has steadily earned respect for her work."],"lesson":18,"id":"18-16"},{"word":"swift","def_lines":[],"pos":"adj","definition":"quick","forms":[{"pos":"adv","word":"swiftly"},{"pos":"n","word":"swiftness"}],"synonyms":["fast"],"examples":["The contestants were swift thinkers.","They swiftly agreed with the conclusion of the report."],"lesson":18,"id":"18-17"}],"matching":[{"n":1,"word":"demeanor","options":["function","conduct","expansion","bias"],"answer":1},{"n":2,"word":"steady","options":["constant","ample","arid","nominal"],"answer":0},{"n":3,"word":"robust","options":["energetic","flexible","narrow","ridiculous"],"answer":0},{"n":4,"word":"fast","options":["swift","spacious","intrinsic","vital"],"answer":0},{"n":5,"word":"balanced","options":["rigid","documented","fundamental","equalized"],"answer":3},{"n":6,"word":"distribution","options":["shortage","allocation","methods","disapproval"],"answer":1},{"n":7,"word":"fallacious","options":["inordinate","incorrect","unwarranted","inevitable"],"answer":1},{"n":8,"word":"apply","options":["exert","expand","conclude","halt"],"answer":0},{"n":9,"word":"feasible","options":["absurd","possible","limber","selective"],"answer":1},{"n":10,"word":"come across","options":["proceed","travel","encounter","transport"],"answer":2}],"tests":[{"n":1,"passage":"Early analog televisions used carrier waves that were picked up by a receiving antenna and then carried to the television receiver. Inside the receiver, the video and audio signals were separated and amplified. They then passed into the picture tube, which reproduced a picture of the original image from the video signals using a narrow beam of electrons that bombarded, in a scanning motion, the back of a screen coated with a fluorescent compound.","prompt":"The word narrow in the passage is closest in meaning to","options":["steady","balanced","thin","negative"],"answer":2,"target":"narrow"},{"n":2,"passage":"A simple example of a means by which energy is converted from one form to another is demonstrated in the tossing of a ball into the air. When the ball is thrown vertically from the ground, its speed and its kinetic energy decreases steadily until it comes to rest momentarily at its highest point.","prompt":"The word means in the passage is closest in meaning to","options":["description","method","theory","benefit"],"answer":1,"target":"means"},{"n":3,"passage":"The First Continental Congress was formed to protest the British Parliament’s intrusion into certain colony affairs. This congress urged the colonies to arm themselves for defense of their rights. It believed that it would be absurd not to give a forceful response to England’s closing of the port of Boston. By the time the Second Continental Congress convened, the American Revolution had begun.","prompt":"The word absurd in the passage is closest in meaning to","options":["ridiculous","difficult","feasible","fallacious"],"answer":0,"target":"absurd"},{"n":4,"passage":"The modern sport of gymnastics was essentially the result of the work of the German Friedrich Jahn, in the early nineteenth century. He invented many of the exercises and some of the apparatus of later gymnastics, such as the parallel bars, the rings, and the horizontal bar. Jahn’s work was aimed mainly at strengthening the body. The result of gymnastics training is a well-toned, limber body.","prompt":"The word limber in the passage is closest in meaning to","options":["flexible","slender","tiny","disciplined"],"answer":0,"target":"limber"},{"n":5,"passage":"Many experts believe that in the early years of the twenty-first century the lack of water, rather than the availability of fertile land, will be the major obstacle to increased worldwide food production. As with land, the amount of water available for agricultural use cannot easily be increased. Research is now being conducted to improve water availability and thereby increase the amount of land available for farming.","prompt":"The word lack in the passage is closest in meaning to","options":["misuse","abuse","shortage","distribution"],"answer":2,"target":"lack"},{"n":6,"passage":"The aim of TV advertising is to motivate viewers to spend money on products; the aim of TV news is to give a balanced view of people, products, and events. These aims sometimes conflict with each other. While advertisers stress product features that contribute to a feeling of well-being or enhanced status, reporters have an obligation to describe products more objectively. Reporters have a responsibility to describe both positive and negative product features.","prompt":"In referring to a balanced view, the author is referring to","options":["a clearly biased summary.","information for and against.","an advocate’s point of view.","factual support for TV ads."],"answer":1,"target":""},{"n":7,"passage":"A typical cellar may be located beneath a house. It may also be located outdoors, partly underground, with the upper part mounded over with earth. This would protect items from freezing and maintain a fairly uniform temperature and humidity level. Unheated basements or heated and insulated ground-level buildings make it feasible to store fruits and vegetables for short periods.","prompt":"The word feasible in the passage is closest in meaning to","options":["balanced","possible","enacted","persuasive"],"answer":1,"target":"feasible"},{"n":8,"passage":"The operating system of a computer network protects computers from access by illegal users. It also prevents data corruption introduced by unintentional mistakes made by legitimate users. A robust security scheme is particularly important for computers that are connected to a communications network, since it has many potential users.","prompt":"The word robust in the passage is closest in meaning to","options":["steady","intrinsic","strong","complex"],"answer":2,"target":"robust"},{"n":9,"passage":"Knowledge of how early wheels were constructed is derived from “chariot burials” found in the city-states of Kish and Ur. Wheels were formed from three planks of wood that were clamped by wooden struts and bound with leather tires that were held in place by copper nails. The simplicity of their design allowed for swift repairs.","prompt":"The word swift in the passage is closest in meaning to","options":["steady","ample","suitable","rapid"],"answer":3,"target":"swift"},{"n":10,"passage":"The law of large numbers, popularly known as “the law of averages,” is often thought to require that future outcomes balance past outcomes. This is a fallacy. A three-digit lottery number has the same probability of being selected every day. The fact that it has not been selected for a given number of days does not increase this probability.","prompt":"The word fallacy in the passage is closest in meaning to","options":["endorsement","sufficiency","misconception","preconception"],"answer":2,"target":"fallacy"}]},{"lesson":19,"words":[{"word":"antiquated","def_lines":[],"pos":"adj","definition":"too old to be presently useful; outmoded","forms":[{"pos":"n","word":"antique"}],"synonyms":["old-fashioned"],"examples":["This antiquated machinery breaks down too frequently.","Their home is filled with antique furniture."],"lesson":19,"id":"19-1"},{"word":"coherent","def_lines":[],"pos":"adj","definition":"well reasoned; ideas that are clearly presented *sticking together as a group","forms":[{"pos":"adv","word":"coherently"},{"pos":"v","word":"cohere"},{"pos":"n","word":"coherence"},{"pos":"adj","word":"cohesive*"},{"pos":"n","word":"cohesion*"}],"synonyms":["logical"],"examples":["It was a well-balanced, coherent presentation.","There was a cohesive feeling among the new workers."],"lesson":19,"id":"19-2"},{"word":"evolve","def_lines":[],"pos":"v","definition":"to grow; to go through a period of change","forms":[{"pos":"n","word":"evolution"}],"synonyms":["develop"],"examples":["The management team’s idea evolved over a period of two years.","The country’s hopes for a rapid evolution of its economy depend on approval of free trade agreements."],"lesson":19,"id":"19-3"},{"word":"fabricate","def_lines":[],"pos":"v","definition":"to make up, usually with an intent to fool or trick; to lie","forms":[{"pos":"adj","word":"fabricated"},{"pos":"n","word":"fabrication"}],"synonyms":["invent"],"examples":["The executive fabricated the story about the merger.","His alibi is the weakest fabrication I have ever heard."],"lesson":19,"id":"19-4"},{"word":"generic","def_lines":[],"pos":"adj","definition":"relating to a whole group or category of things","forms":[{"pos":"adv","word":"generically"}],"synonyms":["general"],"examples":["“Bird” is the generic term used to describe animals with feathers.","Universities provide students with the generic skills needed to compete in the workplace."],"lesson":19,"id":"19-5"},{"word":"investigation","def_lines":[],"pos":"n","definition":"a careful examination in order to determine facts","forms":[{"pos":"adj","word":"investigative"},{"pos":"v","word":"investigate"},{"pos":"n","word":"investigator"}],"synonyms":["probe"],"examples":["The comprehensive investigation of the bank revealed no illegal activity.","Some members of the Senate wanted to appoint a special investigator."],"lesson":19,"id":"19-6"},{"word":"normally","def_lines":[],"pos":"adv","definition":"commonly; usually","forms":[{"pos":"adj","word":"normal"},{"pos":"v","word":"normalize"},{"pos":"n","word":"normalization"},{"pos":"n","word":"norm"}],"synonyms":["typically"],"examples":["It is normally quite cold this time of the year.","The new treaty led to a normalization of relations between the two countries."],"lesson":19,"id":"19-7"},{"word":"notion","def_lines":[],"pos":"n","definition":"an idea, belief, or opinion","forms":[],"synonyms":["concept"],"examples":["She has the notion that she wants to become an architect.","Some outlandish notions about the origin of the solar system have been disproved."],"lesson":19,"id":"19-8"},{"word":"novel","def_lines":[],"pos":"adj","definition":"something unusual, uncommon; new","forms":[],"synonyms":["original"],"examples":["The physicist had some novel ideas about traveling at the speed of light.","The novel suggestions were implemented."],"lesson":19,"id":"19-9"},{"word":"nurture","def_lines":[],"pos":"v","definition":"to support and encourage the development of something","forms":[{"pos":"adj","word":"nurturing"},{"pos":"n","word":"nurture"}],"synonyms":["cultivate"],"examples":["The owner of the vineyard carefully nurtures the grapevines in order to produce the best grapes.","That school is well-known for having a nurturing learning environment."],"lesson":19,"id":"19-10"},{"word":"opposition","def_lines":[],"pos":"n","definition":"the state of acting against; not being in agreement","forms":[{"pos":"adj","word":"opposed"},{"pos":"v","word":"oppose"}],"synonyms":["resistance"],"examples":["The students voiced their opposition to the rise in tuition.","The government opposed price controls."],"lesson":19,"id":"19-11"},{"word":"relate","def_lines":[],"pos":"v","definition":"to tell; to show a connection between two things","forms":[{"pos":"adj","word":"related"},{"pos":"n","word":"relation"},{"pos":"n","word":"relationship"}],"synonyms":["communicate"],"examples":["Although they did not agree with the plan, they did not relate their opposition to it.","What is the relationship between supply and demand?"],"lesson":19,"id":"19-12"},{"word":"suspect","def_lines":[],"pos":"v","definition":"to think that something is true, but having no proof","forms":[{"pos":"adj","word":"suspected"},{"pos":"n","word":"suspicion"},{"pos":"n","word":"suspect"}],"synonyms":["speculate"],"examples":["He suspected that the substance was not present in the compound.","I have a suspicion that he will want to participate in the investigation."],"lesson":19,"id":"19-13"},{"word":"transform","def_lines":[],"pos":"v","definition":"to change in form or appearance","forms":[{"pos":"n","word":"transformation"},{"pos":"n","word":"transformer"}],"synonyms":["alter"],"examples":["The leader’s policies transformed the country in many positive ways.","The student’s transformation from a “D” student to a “B” student was remarkable."],"lesson":19,"id":"19-14"},{"word":"trigger","def_lines":[],"pos":"v","definition":"to initiate, cause or start","forms":[{"pos":"adj","word":"triggered"}],"synonyms":["generate"],"examples":["The possibility of being in the path of a hurricane triggered fear in the residents of coastal areas.","The town hall meeting triggered a lively debate about the need for increased taxes."],"lesson":19,"id":"19-15"},{"word":"unbiased","def_lines":[],"pos":"adj","definition":"with no preconceptions","forms":[],"synonyms":["objective"],"examples":["Her unbiased analysis of the problem allowed her to find the solution more rapidly.","Here is unbiased proof that nitrogen exists in this compound."],"lesson":19,"id":"19-16"},{"word":"varied","def_lines":[],"pos":"adj","definition":"being of many different types","forms":[{"pos":"adv","word":"variably"},{"pos":"adj","word":"variable"},{"pos":"adj","word":"various"},{"pos":"v","word":"vary"},{"pos":"n","word":"variant"},{"pos":"n","word":"variety"},{"pos":"n","word":"variation"},{"pos":"n","word":"variability"}],"synonyms":["diverse"],"examples":["The class expressed varied opinions about the movie.","There are various ways to solve the problem."],"lesson":19,"id":"19-17"}],"matching":[{"n":1,"word":"nurture","options":["function","cultivate","convey","agitate"],"answer":1},{"n":2,"word":"coherent","options":["novel","original","logical","robust"],"answer":2},{"n":3,"word":"resistance","options":["opposition","preservation","preconception","allocation"],"answer":0},{"n":4,"word":"evolve","options":["develop","elude","involve","influence"],"answer":0},{"n":5,"word":"varied","options":["diverse","feasible","hazardous","nominal"],"answer":0},{"n":6,"word":"trigger","options":["harbor","transform","encounter","generate"],"answer":3},{"n":7,"word":"probe","options":["expansion","means","investigation","abuse"],"answer":2},{"n":8,"word":"generic","options":["docile","original","general","mundane"],"answer":2},{"n":9,"word":"suspect","options":["select","confide","speculate","bias"],"answer":2},{"n":10,"word":"unbiased","options":["antiquated","noteworthy","exhausted","objective"],"answer":3}],"tests":[{"n":1,"passage":"The capacity among animals to reconstruct body appendages is not as common as the ability to compensate for lost tissues. This is due to the complex anatomy of appendages, which requires more elaborate regeneration control mechanisms. Among the vertebrates, salamanders are the best regenerators of appendages. Because of this characteristic, they are the subject of much folklore. For example, the fire salamander is so called because of an antiquated belief that it could withstand fire.","prompt":"The word antiquated in the passage is closest in meaning to","options":["outmoded","old-fashioned","illogical","original"],"answer":1,"target":"antiquated"},{"n":2,"passage":"Throughout history, most technological progress has been a result of relatively minor improvements and refinements rather than through major inventions. Organized research is well suited for this kind of development. However, organized research may discourage novel approaches and inhibit creativity, so seminal discoveries are still likely to be made by inventors in the classic individualistic tradition.","prompt":"The word novel in the passage is closest in meaning to","options":["original","varied","coherent","unbiased"],"answer":0,"target":"novel"},{"n":3,"passage":"Economist Alfred Marshall received acclaim for his economic ideas that integrated modern and classical economic theory. Classicists believed that price was determined by the cost of producing goods, but the modern school believed that price was dependent on the notion of marginal utility, or usefulness of the goods. Marshall’s theory that price is determined by both cost and utility gained wide acceptance.","prompt":"The word notion in the passage is closest in meaning to","options":["investigation","concept","effectiveness","opposition"],"answer":1,"target":"notion"},{"n":4,"passage":"Tidal waves are triggered by tectonic displacements. Volcanoes, landslides, or earthquakes on the sea floor can cause a sudden displacement of the water above. This displacement forms a small group of water waves having a wavelength equal to the water depth at the point of origin. In deep water, tidal waves are so long and so slight that ships seldom notice their presence. But as the waves reach shallow water, they increase in amplitude, making them potentially the most catastrophic of all ocean waves.","prompt":"The word triggered in the passage is closest in meaning to","options":["fostered","heightened","inundated","generated"],"answer":3,"target":"triggered"},{"n":5,"passage":"Throughout the ages, the role of the heart was long considered a mystery. Some thought that it was the source of the soul. Others thought that it was the center of love, courage, happiness, and sadness. Primitive humans were no doubt aware of the heartbeat and probably recognized that the tiny heart, normally about the size of a fist, was an organ whose malfunction could cause sudden death.","prompt":"The word normally in the passage is closest in meaning to","options":["roughly","rarely","scarcely","typically"],"answer":3,"target":"normally"},{"n":6,"passage":"There is a growing sentiment in opposition to sea bass fishing. Most sea bass spawn between May and August, which coincides with the height of the fishing season. Fishing affects the reproductive capacity of the species disproportionately since it does not distinguish between males and females. Instead, it captures both indiscriminately. However, it takes six years longer for a female bass to become fertile than a male.","prompt":"In stating that there is a growing sentiment in opposition to sea bass fishing, the author means that people","options":["favor the fishing of sea bass.","see it as a positive activity.","dislike sea bass.","are against its continuation."],"answer":3,"target":""},{"n":7,"passage":"Gymnastic competitions are judged and scored on both an individual and a team basis. Judges award points to each participant in each event on a 0-to-10 scale, 10 being perfect. The goal of completely unbiased judging is very difficult to achieve. Although guidelines are provided, judges seldom agree on the quality of a performance.","prompt":"The word unbiased in the passage is closest in meaning to","options":["objective","balanced","logical","suitable"],"answer":0,"target":"unbiased"},{"n":8,"passage":"Sounding rockets are unmanned rockets that record atmospheric conditions at heights 50–100 miles beyond the reach of airplanes and balloons. These rockets usually follow a vertical path as they investigate upper atmospheric conditions with their scientific instruments.","prompt":"The word investigate in the passage is closest in meaning to","options":["recover","solve","observe","probe"],"answer":3,"target":"investigate"},{"n":9,"passage":"Reality is perceived through appearances. However, appearances are incompatible with reality. If an oar in water looks broken but feels straight to the touch, this must be acknowledged. Thus, a coherent picture of reality requires that we acknowledge that appearances can be deceptive.","prompt":"The word coherent in the passage is closest in meaning to","options":["logical","acceptable","distributed","vital"],"answer":0,"target":"coherent"},{"n":10,"passage":"“Speedwriting” was a writing system devised and patented by Emma Dearborn in 1924. The system used words that were recorded as they sounded, and only employed “long vowels.” Thus, “you” is written “u” and “like” is “lik.” Some letters were transformed to allow for speedy transcription, and the system often employed abbreviations and flourishes.","prompt":"The word transformed in the passage is closest in meaning to","options":["illustrated","altered","written","conveyed"],"answer":1,"target":"transformed"}]},{"lesson":20,"words":[{"word":"accentuate","def_lines":[],"pos":"v","definition":"to highlight; to give more importance to","forms":[{"pos":"adj","word":"accentuated"},{"pos":"n","word":"accentuation"}],"synonyms":["emphasize"],"examples":["The colorful dress accentuated the joy of the occasion.","The supervisor accentuated her preference for hard-working employees during the performance appraisal."],"lesson":20,"id":"20-1"},{"word":"devise","def_lines":[],"pos":"v","definition":"to brainstorm; to come up with an idea","forms":[{"pos":"adj","word":"devisable"}],"synonyms":["formulate"],"examples":["The firefighters devised a plan to safely bring the cat down from the tree.","The scientists had to devise an entirely new experiment after the first one failed."],"lesson":20,"id":"20-2"},{"word":"disguise","def_lines":[],"pos":"v","definition":"to hide the usual appearance of something","forms":[{"pos":"adj","word":"disguised"},{"pos":"n","word":"disguise"}],"synonyms":["conceal"],"examples":["It is hard to disguise the fact that business is slow.","Everyone saw through his disguise."],"lesson":20,"id":"20-3"},{"word":"ignite","def_lines":[],"pos":"v","definition":"to set on fire; to give energy or life to something","forms":[{"pos":"adj","word":"ignitable"},{"pos":"n","word":"ignition"}],"synonyms":["kindle"],"examples":["The jury’s decision ignited a fierce debate in the legal community.","Wood is difficult to ignite if it is damp."],"lesson":20,"id":"20-4"},{"word":"indifferent","def_lines":[],"pos":"adj","definition":"being uninterested or not caring about something","forms":[{"pos":"n","word":"indifference"}],"synonyms":["apathetic"],"examples":["The teacher was indifferent to student requests to extend the project’s deadline.","The player’s indifference about his error on the field upset the coach."],"lesson":20,"id":"20-5"},{"word":"initiate","def_lines":[],"pos":"v","definition":"to begin; to establish; to take decisive action without help","forms":[{"pos":"adj","word":"initiated"},{"pos":"n","word":"initiation"},{"pos":"n","word":"initiative"}],"synonyms":["launch"],"examples":["The newcomers initiated the long citizenship process.","Their work shows a lot of initiative."],"lesson":20,"id":"20-6"},{"word":"innovative","def_lines":[],"pos":"adj","definition":"something newly introduced; creative","forms":[{"pos":"n","word":"innovator"},{"pos":"n","word":"innovation"}],"synonyms":["creative"],"examples":["This innovative project is worthy of support.","There have been many innovations in the field of genetic engineering."],"lesson":20,"id":"20-7"},{"word":"narrate","def_lines":[],"pos":"v","definition":"to tell a story; relate","forms":[{"pos":"adj","word":"narrative"},{"pos":"n","word":"narrative"},{"pos":"n","word":"narration"},{"pos":"n","word":"narrator"}],"synonyms":["relate"],"examples":["Walter Cronkite narrated the documentary film.","Her fabricated narrative generated a lot of excitement."],"lesson":20,"id":"20-8"},{"word":"nevertheless","def_lines":[],"pos":"conj","definition":"in spite of that","forms":[],"synonyms":["nonetheless"],"examples":["She was quite sick; nevertheless, she attended all of her classes.","His project was flawed; nevertheless, it won second prize."],"lesson":20,"id":"20-9"},{"word":"obsolete","def_lines":[],"pos":"adv","definition":"being old fashioned; no longer in general use","forms":[{"pos":"n","word":"obsolescence"}],"synonyms":["outdated"],"examples":["Some people believe that writing instruments, such as pencils and pens, will soon be obsolete.","Some products are manufactured with planned obsolescence."],"lesson":20,"id":"20-10"},{"word":"omit","def_lines":[],"pos":"v","definition":"to leave out; not include","forms":[{"pos":"adj","word":"omitted"},{"pos":"n","word":"omission"}],"synonyms":["neglect"],"examples":["She inadvertently omitted some important data from the report.","His paper had several notable omissions."],"lesson":20,"id":"20-11"},{"word":"outlandish","def_lines":[],"pos":"adj","definition":"strange and unpleasant; beyond accepted norms","forms":[{"pos":"adv","word":"outlandishly"}],"synonyms":["bizarre"],"examples":["His outlandish ideas demonstrated his creativity.","Rebellious youth in many countries dress outlandishly."],"lesson":20,"id":"20-12"},{"word":"overcome","def_lines":[],"pos":"v","definition":"to defeat; fight with success; to take control of an individual","forms":[],"synonyms":["conquer"],"examples":["The young woman was overcome with emotion when she learned she had won a scholarship.","The family overcame many obstacles to purchase the house."],"lesson":20,"id":"20-13"},{"word":"partially","def_lines":[],"pos":"n","definition":"part","forms":[{"pos":"adv","word":"partly"},{"pos":"adj","word":"partial"},{"pos":"adv","word":"a part of the whole; incomplete"}],"synonyms":["somewhat"],"examples":["The clerk was only partially responsible for the error.","The business venture was only a partial success."],"lesson":20,"id":"20-14"},{"word":"pass","def_lines":[],"pos":"v","definition":"to accept formally by vote","forms":[{"pos":"adj","word":"passable"},{"pos":"n","word":"passage"}],"synonyms":["approve"],"examples":["The proposed amendment passed unanimously.","The passage of the resolution is in doubt."],"lesson":20,"id":"20-15"},{"word":"portray","def_lines":[],"pos":"v","definition":"to represent; to act","forms":[{"pos":"n","word":"portrayal"}],"synonyms":["depict"],"examples":["The actress portrayed an orphan in the movie.","The book’s portrayal of Mozart as a calm, mature individual is inaccurate."],"lesson":20,"id":"20-16"},{"word":"streamline","def_lines":[],"pos":"v","definition":"to update; to make more efficient or concise","forms":[{"pos":"adj","word":"streamlined"}],"synonyms":["simplify"],"examples":["The planning process must be streamlined in order for it to be more reliable.","Internet stores have streamlined the process of finding, buying, and selling merchandise."],"lesson":20,"id":"20-17"}],"matching":[{"n":1,"word":"kindle","options":["initiate","ignite","persuade","overcome"],"answer":1},{"n":2,"word":"indifferent","options":["dissimilar","outlandish","diverse","apathetic"],"answer":3},{"n":3,"word":"streamline","options":["transform","simplify","allocate","navigate"],"answer":1},{"n":4,"word":"creative","options":["fallacious","coherent","innovative","conspicuous"],"answer":2},{"n":5,"word":"obsolete","options":["outdated","current","omitted","opposed"],"answer":0},{"n":6,"word":"relate","options":["restore","record","narrate","balance"],"answer":2},{"n":7,"word":"nevertheless","options":["nonetheless","albeit","although","presumably"],"answer":0},{"n":8,"word":"formulate","options":["conceal","delight","feign","devise"],"answer":3},{"n":9,"word":"emphasize","options":["accentuate","conquer","suspect","select"],"answer":0},{"n":10,"word":"portray","options":["refine","depict","pass","abuse"],"answer":1}],"tests":[{"n":1,"passage":"In 1982, after years of debate, the Canadian government agreed to extend a constitutional guarantee to a bill of rights. This Charter of Rights and Freedoms reinforced the Constitution and has a constitutional guarantee. Yet Parliament and the provincial legislatures have limited power to pass laws that might conflict with certain charter rights.","prompt":"The word pass in the passage is closest in meaning to","options":["approve","allocate","streamline","initiate"],"answer":0,"target":"pass"},{"n":2,"passage":"Although the assertion is at least partially true, the citizens of Kansas resent the suggestion that they live in a cultural vacuum. Most of the larger cities have amateur theater groups, while Topeka and Wichita support symphony orchestras. The numerous colleges and universities in the state provide a concentration of art and music in many small communities that otherwise would have no similar activities.","prompt":"The word partially in the passage is closest in meaning to","options":["somewhat","undeniably","nevertheless","occasionally"],"answer":0,"target":"partially"},{"n":3,"passage":"Before becoming proficient, sword swallowers must first overcome their fear of projecting the sharp sword down their throat. Only after long hours of practice and experience can one swallow the sword comfortably. Beyond their entertainment value, exhibits of sword swallowing have helped to further medicine. By demonstrating to physicians that the pharynx could be accustomed to contact, experimentation and exploration of the involved organs is possible.","prompt":"The word overcome in the passage is closest in meaning to","options":["disguise","conquer","treat","accentuate"],"answer":1,"target":"overcome"},{"n":4,"passage":"Sun Ra was an important African-American jazz pianist and bandleader of the 1930s. Having a flare for being creative, he dressed his band in purple blazers, white gloves, and propeller beanies. The band developed into The Arkestra, and over time the costumes and showmanship grew ever more outlandish. The musicianship, however, was uniformly excellent, and Sun Ra developed into a serious experimenter, fusing jazz with African music, dance, and acrobatics.","prompt":"The word outlandish in the passage is closest in meaning to","options":["prosperous","bizarre","relaxing","melodical"],"answer":1,"target":"outlandish"},{"n":5,"passage":"Modern descriptions of written languages are in most cases excellent, but they still omit an explicit account of a native speaker’s competence in his language, by virtue of which one calls him a speaker of English, Japanese, Arabic, or Chinese. Recent studies of language have revealed how more research is needed in order to fully describe linguistic competence.","prompt":"The word omit in the passage is closest in meaning to","options":["portray","contribute","neglect","relate"],"answer":2,"target":"omit"},{"n":6,"passage":"All team sports require reactive and proactive players. In soccer, for example, fullbacks, stoppers, sweepers, and midfielders have the job of preventing the opposing team from advancing very far. Goalies are responsible for stopping the ball and keeping their opponents from scoring. By comparison, the center forward has to take the initiative, seize the ball, move it down the field, keep it going, and move it forward into the enemy end zone.","prompt":"In stating that the center forward has to take the initiative, the author means that the center forward’s responsibility is to","options":["play in an offensive way.","assume a supportive role.","react to opposing moves.","wait for others to score."],"answer":0,"target":""},{"n":7,"passage":"A disguise is often used to create an interesting or amusing character. The mask is a type of disguise that is still used in the 21st century during festive occasions. Masks may be outlandish, hideous, or superficially horrible. Festival masks are commonly used during Halloween and Mardi Gras, or at masquerade-themed gatherings.","prompt":"The word disguise in the passage is closest in meaning to","options":["elusiveness","confidant","omission","concealment"],"answer":3,"target":"disguise"},{"n":8,"passage":"The length, content, and form of folktales vary enormously. Both a short joke and an adventure-filled romance requiring several hours to narrate can be characterized as folktales. Folktales may be set in a mythical past, in historic times, or in the present. Storytelling is a basic human need. Therefore folktales, even in technological cultures, remain strong.","prompt":"The word narrate in the passage is closest in meaning to","options":["relate","dictate","elaborate","mention"],"answer":0,"target":"narrate"},{"n":9,"passage":"Jan Swammerdam was a biologist who studied relatively few organisms, but in great detail. He employed highly innovative techniques such as injecting wax into the circulatory system to hold the blood vessels firm. He also dissected fragile structures under water to avoid destroying them.","prompt":"The word innovative in the passage is closest in meaning to","options":["intricate","absurd","conspicuous","inventive"],"answer":3,"target":"innovative"},{"n":10,"passage":"Contracts between employees and employers state that the worker will do what the employer asks. In return, the employer pays the worker a fee, which the worker can use to purchase goods and services made by other workers who have also entered into a voluntary relationship with another employer. A cooperative spirit and a desire for mutual benefit accentuate healthy employer-employee relationships.","prompt":"The word accentuate in the passage is closest in meaning to","options":["steady","influence","emphasize","substantial"],"answer":2,"target":"accentuate"}]},{"lesson":21,"words":[{"word":"decline","def_lines":[],"pos":"v","definition":"to move from good to bad, or from much to little; to refuse","forms":[{"pos":"n","word":"decline"}],"synonyms":["decrease"],"examples":["The old man’s health has declined since he retired.","Serious communicable diseases are on the decline in most parts of the world."],"lesson":21,"id":"21-1"},{"word":"gather","def_lines":[],"pos":"v","definition":"to collect","forms":[{"pos":"n","word":"gathering"}],"synonyms":["collect"],"examples":["He carefully gathered his thoughts just before the interview.","A gathering of citizens developed outside the courthouse."],"lesson":21,"id":"21-2"},{"word":"motion","def_lines":[],"pos":"n","definition":"the state of changing one’s position *to direct by moving","forms":[{"pos":"v","word":"motion*"}],"synonyms":["movement"],"examples":["The motion of the flame was hypnotic.","They motioned her to leave the area."],"lesson":21,"id":"21-3"},{"word":"outburst","def_lines":[],"pos":"n","definition":"a sudden and intense release of something","forms":[],"synonyms":["eruption"],"examples":["The joke caused an outburst of laughter from the audience.","There was an outburst of complaints from the students when the teacher moved the test to Monday."],"lesson":21,"id":"21-4"},{"word":"partisan","def_lines":[],"pos":"adj","definition":"strongly supporting a group or point of view","forms":[],"synonyms":["biased"],"examples":["Partisan political infighting caused Congress’s influence to decline.","His views reflected his partisan bias."],"lesson":21,"id":"21-5"},{"word":"pattern","def_lines":[],"pos":"n","definition":"a regular, repeated arrangement or action","forms":[{"pos":"adj","word":"patterned"},{"pos":"v","word":"pattern"}],"synonyms":["habit"],"examples":["The bright pattern of the monarch butterfly distracts its predators.","The new stadium was patterned after the old traditional ballparks."],"lesson":21,"id":"21-6"},{"word":"phenomena","def_lines":[],"pos":"n","definition":"natural events or facts; strange or notable happenings","forms":[{"pos":"adv","word":"phenomenally"},{"pos":"adj","word":"phenomenal"},{"pos":"n","word":"phenomenon"}],"synonyms":["events"],"examples":["Rain showers are almost unknown phenomena in the Atacama Desert of Chile.","The musician’s phenomenal performance was applauded by the critics."],"lesson":21,"id":"21-7"},{"word":"philanthropic","def_lines":[],"pos":"adj","definition":"a feeling of love for people, usually resulting in financial aid to worthy causes","forms":[{"pos":"n","word":"philanthropist"},{"pos":"n","word":"philanthropy"}],"synonyms":["humanitarian"],"examples":["The philanthropic work of the foundation benefits all sectors of society.","His philanthropy is recognized around the world."],"lesson":21,"id":"21-8"},{"word":"placid","def_lines":[],"pos":"adj","definition":"quiet; not easily upset","forms":[{"pos":"adv","word":"placidly"}],"synonyms":["calm"],"examples":["The placid nature of her personality made her easy to work with.","The waves moved placidly toward shore."],"lesson":21,"id":"21-9"},{"word":"plentiful","def_lines":[],"pos":"adj","definition":"more than sufficient","forms":[{"pos":"adv","word":"plentifully"},{"pos":"n","word":"plenty"}],"synonyms":["abundant"],"examples":["Examples of Miro’s art are plentiful.","A balanced diet normally provides plenty of the necessary vitamins."],"lesson":21,"id":"21-10"},{"word":"reaction","def_lines":[],"pos":"n","definition":"a reply; a change that occurs when substances are mixed","forms":[{"pos":"adv","word":"reactively"},{"pos":"adj","word":"reactive"},{"pos":"v","word":"react"},{"pos":"adj","word":"reactionary"}],"synonyms":["response"],"examples":["When chlorine and ammonia are mixed, the chemical reaction causes chlorine gas.","They reacted to the report by making some swift changes in management."],"lesson":21,"id":"21-11"},{"word":"rhythm","def_lines":[],"pos":"n","definition":"a regular pattern, usually in music","forms":[{"pos":"adv","word":"rhythmically"},{"pos":"adj","word":"rhythmic"}],"synonyms":["pulse"],"examples":["The rhythm of the rain hitting the roof put him to sleep.","She noticed the rhythmic beating of her heart as the moment of truth arrived."],"lesson":21,"id":"21-12"},{"word":"scenic","def_lines":[],"pos":"adj","definition":"concerning pleasant natural surroundings","forms":[{"pos":"adv","word":"scenically"},{"pos":"n","word":"scenery"},{"pos":"n","word":"scene"}],"synonyms":["picturesque"],"examples":["The scenic route to the summit is much more interesting than the fastest route.","The scenery in rural Japan is impressive."],"lesson":21,"id":"21-13"},{"word":"shallow","def_lines":[],"pos":"adj","definition":"not far from top to bottom","forms":[{"pos":"adv","word":"shallowly"},{"pos":"n","word":"shallowness"}],"synonyms":["superficial"],"examples":["Estuaries are typically shallow bodies of water.","The results of their research demonstrated the shallowness of the hypothesis."],"lesson":21,"id":"21-14"},{"word":"sheltered","def_lines":[],"pos":"adj","definition":"protected from harmful elements; isolated from reality","forms":[{"pos":"v","word":"shelter"},{"pos":"n","word":"shelter"}],"synonyms":["protected"],"examples":["She has led a sheltered life, her parents having done everything for her.","Everyone looked for shelter from the blazing sun."],"lesson":21,"id":"21-15"},{"word":"vanishing","def_lines":[],"pos":"adj","definition":"going out of sight","forms":[{"pos":"v","word":"vanish"}],"synonyms":["disappearing"],"examples":["The red squirrel is a vanishing species that needs a protected habitat to survive.","No one knows with certainty what caused the dinosaurs to vanish from the face of the earth."],"lesson":21,"id":"21-16"}],"matching":[{"n":1,"word":"picturesque","options":["scenic","calm","outlandish","fertile"],"answer":0},{"n":2,"word":"partisan","options":["patterned","bizarre","abundant","biased"],"answer":3},{"n":3,"word":"eruption","options":["disguise","outburst","omission","decrease"],"answer":1},{"n":4,"word":"disappear","options":["vary","vanish","reject","fabricate"],"answer":1},{"n":5,"word":"shallow","options":["swift","substantial","placid","superficial"],"answer":3},{"n":6,"word":"gather","options":["broaden","collect","distribute","enhance"],"answer":1},{"n":7,"word":"reaction","options":["allocation","investigation","response","means"],"answer":2},{"n":8,"word":"motion","options":["innovation","narration","reaction","movement"],"answer":3},{"n":9,"word":"protected","options":["plentiful","phenomenal","sheltered","passable"],"answer":2},{"n":10,"word":"rhythm","options":["pulse","pattern","function","notion"],"answer":0}],"tests":[{"n":1,"passage":"Until the latter half of the twentieth century, the Chesapeake Bay’s sheltered, nutrient-rich waters supported plentiful populations of marine life. Commercial fishing and recreational activities abounded. By the 1970s, however, residential and industrial development of the surrounding land had led to significant pollution of the bay. Various projects have been initiated in an effort to reverse the environmental damage that the bay has suffered.","prompt":"The word plentiful in the passage is closest in meaning to","options":["vanishing","abundant","fascinating","declining"],"answer":1,"target":"plentiful"},{"n":2,"passage":"The bee family Apidae, which includes honeybees, no longer uses honeypots that could be damaged by exposure to the elements. Instead, honey and pollen are stored in vertical combs with a layer of cells on each surface. Of the four species of honeybees in this family, only three are found in Asia. Their nests have several combs and are sheltered in crevices of rocks or hollows of trees.","prompt":"The word sheltered in the passage is closest in meaning to","options":["recovered","abundant","discovered","protected"],"answer":3,"target":"sheltered"},{"n":3,"passage":"Andrew Carnegie established several independent, philanthropic foundations. Among them are funds for the recognition of heroic acts. These include the Carnegie United Kingdom Trust, the Endowment for International Peace, and the Carnegie Foundation for the Advancement of Teaching, which was established in 1905 to provide pensions for college teachers.","prompt":"The word philanthropic in the passage is closest in meaning to","options":["partisan","service","humanitarian","financial"],"answer":2,"target":"philanthropic"},{"n":4,"passage":"The world of magic comprises a wide range of phenomena, from the intricate ritual beliefs and practices of religious systems, to acts of conjuring and sleight of hand for entertainment. Magic is a social and cultural phenomenon found in all places and in all periods of history, with varying degrees of importance.","prompt":"The word phenomena in the passage is closest in meaning to","options":["motions","patterns","expectations","occurrences"],"answer":3,"target":"phenomena"},{"n":5,"passage":"A person’s need for food is determined by age and by average heights and weights. Individual activity levels are also used to determine the level of ideal calorie consumption. For example, a decrease in recommended daily calorie consumption with increasing age is consistent with the known reduction in metabolism that occurs with aging and with a normal decrease in physical activity.","prompt":"The word decrease in the passage is closest in meaning to","options":["decline","balance","resistance","development"],"answer":0,"target":"decrease"},{"n":6,"passage":"Liquids vary in the amount of acid they contain. For example, water contains relatively little acid, while vinegar contains a large quantity. Acidic content is determined by dipping litmus paper into a liquid. This paper is saturated with a colorant obtained from plants called lichens. The colorant reacts to the presence of acid by turning different shades of red—the brightness of the shade can be measured on a scale called a pH scale.","prompt":"In stating that the colorant reacts to the presence of acid in the liquid, the author means that it","options":["combines chemically with the acid.","disappears or dissolves in the liquid.","causes the liquid to lose its redness.","neutralizes the acid into a base."],"answer":0,"target":""},{"n":7,"passage":"Gars are long, slender, predatory fish, with a long, tooth-studded jaw and a tough, armored skin. They are a primitive fish that inhabit placid fresh waters of the Western Hemisphere. Because of the highly vascular and cellular nature of the gar’s swim bladder, it functions as a lung. This makes the gar able to survive in large numbers in the Everglades of the southern United States.","prompt":"The word placid in the passage is closest in meaning to","options":["steady","protected","calm","sheltered"],"answer":2,"target":"placid"},{"n":8,"passage":"In the human body, different toxins produce different reactions. Irritation of the upper respiratory tract by inhaled formaldehyde gas is rapidly reversible because as soon as inhalation ends, the irritation subsides. In contrast, the response produced by silica dust is irreversible, because once the silicotic nodules are formed, they remain in the lung.","prompt":"The word reactions in the passage is closest in meaning to","options":["responses","narrations","influences","harvests"],"answer":0,"target":"reactions"},{"n":9,"passage":"Much of the world’s unique heritage is endangered by pollution, the advance of human settlements, conflicts over the use of land and resources, and other problems. Thus, many countries are setting aside scenic natural areas as rapidly as possible. The tendency of many governments has been to establish as many parks as possible before natural environments are altered by human activities.","prompt":"The word scenic in the passage is closest in meaning to","options":["cultivated","traditional","delightful","picturesque"],"answer":3,"target":"scenic"},{"n":10,"passage":"A “must carry” rule is designed to ensure that local TV stations do not vanish from cable TV offerings. It requires cable systems to carry all local broadcast channels within a certain area of their transmitters. The law was struck down in 1985, although many aspects of that case are still being argued.","prompt":"The word vanish in the passage is closest in meaning to","options":["graduate","pass","disappear","elude"],"answer":2,"target":"vanish"}]},{"lesson":22,"words":[{"word":"account","def_lines":[],"pos":"n","definition":"a report of an event; money kept in a bank; a statement of something used or received, usually a financial report","forms":[{"pos":"adj","word":"accountable"},{"pos":"v","word":"account"},{"pos":"n","word":"accounting"},{"pos":"n","word":"accountant"}],"synonyms":["story"],"examples":["His account of the incident varied from that of the other witnesses.","We need an accounting of all the money that was spent."],"lesson":22,"id":"22-1"},{"word":"archaic","def_lines":[],"pos":"adj","definition":"very old; old-fashioned; no longer used","forms":[],"synonyms":["ancient"],"examples":["These archaic methods of farming must be brought up-to-date.","His speech was full of archaic expressions."],"lesson":22,"id":"22-2"},{"word":"bring about","def_lines":[],"pos":"ph. v","definition":"to cause something to happen","forms":[],"synonyms":["generate"],"examples":["The invention of the cell phone brought about an end to the popularity of traditional telephones.","The newly elected president of the club promised to bring about positive changes."],"lesson":22,"id":"22-3"},{"word":"enlighten","def_lines":[],"pos":"v","definition":"to give information or understanding to someone","forms":[{"pos":"n","word":"enlightenment"},{"pos":"adj","word":"enlightened"}],"synonyms":["instruct"],"examples":["Books often enlighten readers to different ways of thinking.","The speaker enlightened the audience on how to succeed in college."],"lesson":22,"id":"22-4"},{"word":"hasten","def_lines":[],"pos":"v","definition":"to cause to go faster; move forward more quickly","forms":[{"pos":"adj","word":"hastily"},{"pos":"adj","word":"hasty"},{"pos":"n","word":"hastiness"}],"synonyms":["accelerate"],"examples":["After notifying the driver’s family of the accident, the officer hastened to add that their son had not been hurt.","You should not make important decisions hastily."],"lesson":22,"id":"22-5"},{"word":"hue","def_lines":[],"pos":"n","definition":"color","forms":[],"synonyms":["color"],"examples":["The hue of the sunset was beautiful.","The hue of the room gave it a warm feeling."],"lesson":22,"id":"22-6"},{"word":"inactive","def_lines":[],"pos":"adj","definition":"not moving; not involved","forms":[{"pos":"n","word":"inaction"},{"pos":"n","word":"inactivity"}],"synonyms":["idle"],"examples":["The virus remains inactive for a long period of time.","Her inaction has caused her to miss many opportunities to advance her career."],"lesson":22,"id":"22-7"},{"word":"intricate","def_lines":[],"pos":"adj","definition":"having many parts; finely detailed","forms":[{"pos":"adv","word":"intricately"},{"pos":"n","word":"intricacy"}],"synonyms":["complex"],"examples":["The intricate design of the vase made it a valuable piece for her collection.","I cannot begin to understand all of the intricacies of modern automobile motors."],"lesson":22,"id":"22-8"},{"word":"magnitude","def_lines":[],"pos":"n","definition":"of great size or importance *to increase","forms":[{"pos":"adv","word":"magnificently"},{"pos":"adj","word":"magnificent"},{"pos":"v","word":"magnify*"},{"pos":"n","word":"magnification*"}],"synonyms":["dimension"],"examples":["The magnitude of shock waves determines the damage that occurs during an earthquake.","The invention of the telephone was a magnificent achievement for mankind."],"lesson":22,"id":"22-9"},{"word":"oblige","def_lines":[],"pos":"v","definition":"to have to do something","forms":[{"pos":"adv","word":"obligingly"},{"pos":"adj","word":"obliging"},{"pos":"adj","word":"obligatory"},{"pos":"n","word":"obligation"}],"synonyms":["require"],"examples":["She obliged her friend to choose a new lab partner.","Payment of the student activity fee was obligatory."],"lesson":22,"id":"22-10"},{"word":"overlook","def_lines":[],"pos":"v","definition":"to ignore or neglect","forms":[{"pos":"adj","word":"overlooked"}],"synonyms":["disregard"],"examples":["Scientists must not overlook any aspect of experimental procedure.","The overlooked error raised his score on the test."],"lesson":22,"id":"22-11"},{"word":"poll","def_lines":[],"pos":"n","definition":"questionnaire; a vote of public opinion","forms":[{"pos":"n","word":"polling"},{"pos":"n","word":"pollster"}],"synonyms":["survey"],"examples":["The poll indicated that conservation of the environment was the number one issue with college students.","The pollster asked the questions in a nonpartisan manner."],"lesson":22,"id":"22-12"},{"word":"practical","def_lines":[],"pos":"adj","definition":"convenient or effective","forms":[{"pos":"adv","word":"practically"},{"pos":"adj","word":"practicable"},{"pos":"n","word":"practicality"}],"synonyms":["functional"],"examples":["Her ambitious plan was not very practical.","Space travel to distant planets is not practicable at this time."],"lesson":22,"id":"22-13"},{"word":"predominant","def_lines":[],"pos":"adj","definition":"the most noticeable or powerful element","forms":[{"pos":"adv","word":"predominantly"},{"pos":"n","word":"predominate"},{"pos":"n","word":"predominance"}],"synonyms":["principal"],"examples":["The predominant export of the Middle East is petroleum.","Many cities in the Southwest are predominantly Hispanic."],"lesson":22,"id":"22-14"},{"word":"prompt","def_lines":[],"pos":"v","definition":"to cause something to happen; do quickly; be on time","forms":[{"pos":"adv","word":"promptly"},{"pos":"n","word":"promptness"}],"synonyms":["induce"],"examples":["His emotional plea prompted the director to give him a second chance.","Promptness is an important factor in many societies."],"lesson":22,"id":"22-15"},{"word":"provoke","def_lines":[],"pos":"v","definition":"to cause or produce negative behavior or result","forms":[{"pos":"n","word":"provocation"},{"pos":"adj","word":"provocative"}],"synonyms":["trigger"],"examples":["The installation of speed cameras provoked an angry response from the public.","The manager did not deliberately provoke the argument among his workers."],"lesson":22,"id":"22-16"}],"matching":[{"n":1,"word":"intricate","options":["functional","complex","predominant","inordinate"],"answer":1},{"n":2,"word":"disregard","options":["overcome","disperse","decline","overlook"],"answer":3},{"n":3,"word":"idle","options":["initiated","inundated","inactive","intrinsic"],"answer":2},{"n":4,"word":"archaic","options":["plentiful","ancient","placid","absurd"],"answer":1},{"n":5,"word":"bring about","options":["generate","heighten","hasten","ignite"],"answer":0},{"n":6,"word":"provoke","options":["oblige","heighten","disregard","trigger"],"answer":3},{"n":7,"word":"size","options":["allocation","magnitude","expand","advent"],"answer":1},{"n":8,"word":"color","options":["hue","paint","facet","scenery"],"answer":0},{"n":9,"word":"require","options":["survey","induce","oblige","relinquish"],"answer":2},{"n":10,"word":"account","options":["currency","poll","bank","story"],"answer":3}],"tests":[{"n":1,"passage":"Southeast Asian culture has many themes. The most predominant of these have been in religion and national history. In religion the main interest was not in actual doctrine but in the life and personalities of the Buddha and the Hindu gods. In national history the interest was in the celebrated heroes of the past. This theme appeared only after the great empires had vanished and the memories of their glory and power endured.","prompt":"The word predominant in the passage is closest in meaning to","options":["principal","inactive","archaic","overlooked"],"answer":0,"target":"predominant"},{"n":2,"passage":"The experience of the American frontier fostered raucous politics and rude manners. Conventions were disregarded and contempt for intellectual and cultural pursuits flourished. Brazen waste and the exploitation of natural resources abounded. The predominant spirit was to take while the taking was good. Frontier history includes many accounts of men who created empires and acquired great wealth within a short time.","prompt":"The word disregarded in the passage is closest in meaning to","options":["hastened","defied","overlooked","induced"],"answer":2,"target":"disregarded"},{"n":3,"passage":"For religious reasons, the Egyptians considered Canis Major the most important constellation in the sky. Many Egyptian temples were aligned so that at the rising or setting of Sirius, the starlight reached the interior altar. In the Egyptian calendar, the first practical calendar created, the advent of Sirius in the morning sky before sunrise marked the beginning of the annual flooding of the Nile.","prompt":"The word practical in the passage is closest in meaning to","options":["functional","accurate","standard","celestial"],"answer":0,"target":"practical"},{"n":4,"passage":"Airplanes have extensive agricultural value. They are used to distribute fertilizer, to reseed forest land, and to control forest fires. Many rice growers use planes to seed, fertilize, spray pesticides, and even to hasten crop ripening by spraying hormones from the air.","prompt":"The word hasten in the passage is closest in meaning to","options":["heighten","enable","curtail","accelerate"],"answer":3,"target":"hasten"},{"n":5,"passage":"The CD is an improvement over the conventional record and tape recording because of its complete absence of background noise and wider dynamic range. The CD is also more durable since nothing mechanical touches the surface of the disc when it is played. In addition to its audio recording applications, recent computer trade magazine polls confirm that the compact disc is the preferred medium of recording data.","prompt":"The word polls in the passage is closest in meaning to","options":["surveys","accounts","articles","advertisements"],"answer":0,"target":"polls"},{"n":6,"passage":"Scientists are still seeking to account for the sudden appearance of precisely patterned circles in grain fields in the north of England. Known as crop circles, they range in size from two to eighty meters in diameter. Their circular geometric pattern is not explained by the way the grain was planted; nor is their flattened appearance easily explained by weather conditions. The farmers who work the land are as mystified as everyone else by these strange phenomena.","prompt":"In stating that scientists are seeking to account for crop circles, the author means that they are trying to","options":["measure them in meters.","describe their geometry.","explain what causes them.","grow them in grain fields."],"answer":2,"target":""},{"n":7,"passage":"Tree buds may be vegetative or reproductive. Vegetative buds produce height growth until the growth process induces the formation of flowers. Exactly what is responsible for the formation of a reproductive bud varies, but changes in the number of daylight hours is a common signal in many plants.","prompt":"The word induces in the passage is closest in meaning to","options":["obliges","prompts","evolves","creates"],"answer":1,"target":"induces"},{"n":8,"passage":"Some leaders of the Han period in China exerted enormous pressure for the simplification and standardization of writing. The result was a new category of script called clerical script. The archaic seal script was often retained for formal titles. It was also adapted to the small seals that have been used as signatures from the Han period to the present. These small red stamps, often present on documents, letters, books, and paintings, signify either authorship or ownership.","prompt":"The word archaic in the passage is closest in meaning to","options":["antiquated","durable","ancient","persistent"],"answer":2,"target":"archaic"},{"n":9,"passage":"There are six general classes of map symbols: size, lightness and darkness, direction, texture, shape, and color. The mixture of these “visual variables” creates the variety that is found on maps. For example, hue is used on urban planning maps to show differences in land use. Different shades may be used to indicate information such as changes in elevation or population density.","prompt":"The word hue in the passage is closest in meaning to","options":["color","dim","facet","element"],"answer":0,"target":"hue"},{"n":10,"passage":"Sleep is an intricate form of the resting state. It is observed in animals that have highly developed nervous systems. When they sleep, their nervous systems shift into inactive modes that are different, but no less active than those that they demonstrate while awake.","prompt":"The word inactive in the passage is closest in meaning to","options":["astute","deep","dormant","idle"],"answer":3,"target":"inactive"}]},{"lesson":23,"words":[{"word":"analogous","def_lines":[],"pos":"adj","definition":"alike in some way","forms":[{"pos":"n","word":"analogy"}],"synonyms":["similar to"],"examples":["The action of light waves is analogous to the action of sound waves.","The analogy between the behavior of the bacteria in the lab and in the human body is not clear."],"lesson":23,"id":"23-1"},{"word":"approximately","def_lines":[],"pos":"adv","definition":"almost correct; not exact","forms":[{"pos":"adj","word":"approximate"},{"pos":"v","word":"approximate"},{"pos":"n","word":"approximation"}],"synonyms":["around"],"examples":["There are approximately 500 billion galaxies in the universe.","The results of this study approximate those of a previous study."],"lesson":23,"id":"23-2"},{"word":"compel","def_lines":[],"pos":"v","definition":"to make something happen by necessity or force","forms":[{"pos":"adv","word":"compellingly"},{"pos":"adj","word":"compelling"}],"synonyms":["obliged"],"examples":["The representatives were compelled to vote in favor of the legislation despite their personal opposition to it.","The lawyer’s plea was made in a compelling manner."],"lesson":23,"id":"23-3"},{"word":"compile","def_lines":[],"pos":"v","definition":"to collect","forms":[{"pos":"n","word":"compilation"}],"synonyms":["assemble"],"examples":["The film club asked each of its members to compile a list of his or her favorite movies.","The book is a compilation of Shakespeare’s plays."],"lesson":23,"id":"23-4"},{"word":"formidable","def_lines":[],"pos":"adj","definition":"difficult; causing worry or fear","forms":[{"pos":"adv","word":"formidably"}],"synonyms":["overwhelming"],"examples":["Their formidable opponents gave no sign of weakness.","The man’s voice echoed formidably throughout the hallway."],"lesson":23,"id":"23-5"},{"word":"intrusive","def_lines":[],"pos":"adj","definition":"the state of being inside when not desired to be there by others","forms":[{"pos":"adv","word":"intrusively"},{"pos":"v","word":"intrude"},{"pos":"n","word":"intrusion"},{"pos":"n","word":"intruder"}],"synonyms":["annoying"],"examples":["The intrusive bacteria caused his condition to worsen.","The intrusion of the hazardous gas made it difficult to live in the house."],"lesson":23,"id":"23-6"},{"word":"periodic","def_lines":[],"pos":"adj","definition":"occurring at specific, determined periods of time","forms":[{"pos":"adj","word":"periodical"},{"pos":"adv","word":"periodically"}],"synonyms":["regularly"],"examples":["Periodic payments must be made on home loans.","Some people need periodic doses of medicine."],"lesson":23,"id":"23-7"},{"word":"prone","def_lines":[],"pos":"adj","definition":"likely to do something","forms":[],"synonyms":["inclined to"],"examples":["Most liquids are prone to contract when frozen.","She is prone to study hard the night before her tests."],"lesson":23,"id":"23-8"},{"word":"prophetic","def_lines":[],"pos":"adj","definition":"correctly telling about future events","forms":[{"pos":"adv","word":"prophetically"},{"pos":"v","word":"prophesy"},{"pos":"n","word":"prophecy"},{"pos":"n","word":"prophet"}],"synonyms":["predictive"],"examples":["His prophetic powers were investigated by a team of psychologists.","The brilliant student fulfilled his teacher’s prophecy that he would be a successful doctor."],"lesson":23,"id":"23-9"},{"word":"proportions","def_lines":[],"pos":"n","definition":"the relationship of size or importance when compared to another object or person","forms":[{"pos":"adv","word":"proportionally"},{"pos":"adj","word":"proportional"},{"pos":"adj","word":"proportionate"},{"pos":"adv","word":"proportionately"}],"synonyms":["dimensions"],"examples":["The goal of establishing a space station will take a team effort of major proportions.","The pilot’s salary is proportional to that of pilots of other airlines."],"lesson":23,"id":"23-10"},{"word":"readily","def_lines":[],"pos":"adv","definition":"willingly; easily","forms":[{"pos":"adj","word":"ready"},{"pos":"v","word":"ready"},{"pos":"n","word":"readiness"}],"synonyms":["freely"],"examples":["The workers readily complained about the food in the cafeteria.","Her readiness to cooperate was an important factor in the investigation."],"lesson":23,"id":"23-11"},{"word":"reliably","def_lines":[],"pos":"adv","definition":"in a trusted way","forms":[{"pos":"adj","word":"reliable"},{"pos":"adj","word":"reliant"},{"pos":"v","word":"rely"},{"pos":"n","word":"reliability"},{"pos":"n","word":"reliance"}],"synonyms":["dependably"],"examples":["An appliance must perform its task reliably to be popular with consumers.","Satellite photos show the smallest details with great reliability."],"lesson":23,"id":"23-12"},{"word":"reluctantly","def_lines":[],"pos":"adj","definition":"unwillingly","forms":[{"pos":"adj","word":"reluctant"},{"pos":"n","word":"reluctance"}],"synonyms":["hesitatingly"],"examples":["Although not completely satisfied with the contract, the officials reluctantly agreed to sign it.","The electrician was reluctant to estimate the cost of the repair work."],"lesson":23,"id":"23-13"},{"word":"renown","def_lines":[],"pos":"n","definition":"fame","forms":[{"pos":"adj","word":"renowned"}],"synonyms":["prominence"],"examples":["This school is of great renown.","The renowned conductor made a guest appearance at the concert."],"lesson":23,"id":"23-14"},{"word":"revive","def_lines":[],"pos":"v","definition":"to restore to life or bring back into memory","forms":[{"pos":"n","word":"revival"},{"pos":"adj","word":"revived"}],"synonyms":["renew"],"examples":["The students revived the old tradition of having a homecoming dance.","Old plays are sometimes revived by applying modern interpretations to their content."],"lesson":23,"id":"23-15"},{"word":"triumph","def_lines":[],"pos":"n","definition":"a victory; a success","forms":[{"pos":"adv","word":"triumphantly"},{"pos":"adj","word":"triumphant"},{"pos":"adj","word":"triumphal"},{"pos":"v","word":"triumph"}],"synonyms":["achievement"],"examples":["His career was characterized by one triumph after another.","He triumphed over all of his difficulties."],"lesson":23,"id":"23-16"}],"matching":[{"n":1,"word":"intrusive","options":["inactive","intricate","predictive","annoying"],"answer":3},{"n":2,"word":"obliged","options":["distorted","dependable","compelled","settled"],"answer":2},{"n":3,"word":"assemble","options":["compel","accelerate","compile","renew"],"answer":2},{"n":4,"word":"formidable","options":["predictive","overwhelming","functional","practical"],"answer":1},{"n":5,"word":"similar to","options":["unlike","analogous","archaic","prone"],"answer":1},{"n":6,"word":"around","options":["obviously","likely","entirely","approximately"],"answer":3},{"n":7,"word":"hesitatingly","options":["reluctantly","readily","compellingly","practically"],"answer":0},{"n":8,"word":"achievements","options":["triumphs","phenomena","dimensions","approximation"],"answer":0},{"n":9,"word":"regularly","options":["routinely","actually","periodic","gradually"],"answer":2},{"n":10,"word":"renown","options":["domination","prophecy","prominence","position"],"answer":2}],"tests":[{"n":1,"passage":"New annual growth of trees produces growth rings. In most instances, the age of a tree can be reliably determined by counting the rings of a trunk’s cross section. Most of the growth ring wood cells are dead. Only young xylem cells, those that grow during the current growing season, are alive. As a result, the ratio of dead to living wood cells increases as the girth of the tree increases.","prompt":"The word reliably in the passage is closest in meaning to","options":["periodically","dependably","approximately","ordinarily"],"answer":1,"target":"reliably"},{"n":2,"passage":"Lightships and buoys have an important function in coastal waters. They mark channels and thereby safely guide passing ships around hazards or shallow waters. Their great advantage is mobility, making them readily redeployable to meet changing conditions. For example, submerged hazards such as sandbars can change location rapidly under the influence of the sea. The use of buoys makes it possible to efficiently mark safe channels at all times.","prompt":"The word readily in the passage is closest in meaning to","options":["freely","reluctantly","repeatedly","occasionally"],"answer":0,"target":"readily"},{"n":3,"passage":"The construction of the Saint Lawrence Seaway was an undertaking of great proportions. Constructing a link between the Great Lakes and the Atlantic seaboard had been proposed since 1535. Locks built in the 1800s by Canada became operational in 1901 on the upper Saint Lawrence River. But this original seaway was not deep or wide enough for modern ships. Canada and the United States constructed the new seaway, which became operational in 1959.","prompt":"The word proportions in the passage is closest in meaning to","options":["triumphs","renown","dimensions","strength"],"answer":2,"target":"proportions"},{"n":4,"passage":"In European folklore, mermaids are mythical beings who, like sprites, have magical and prophetic powers. They love music and song. Though very long-lived, they are mortal and have no souls. Although sometimes kindly, mermaids are generally dangerous to man. Their gifts have typically brought misfortune, and, if offended, they have caused floods or other disasters. To see one on a voyage is an omen of shipwreck.","prompt":"The word prophetic in the passage is closest in meaning to","options":["formidable","intrusive","predictive","renowned"],"answer":2,"target":"prophetic"},{"n":5,"passage":"In Western cultures, the absence of a formal definition of responsibilities has produced an ambiguous and often conflicting set of expectations for young people. At the same time, young people are prone to experience problems of peer pressure. They are told to behave maturely, while being denied access to the rights and privileges of adults.","prompt":"The word prone in the passage is closest in meaning to","options":["obliged","positioned","cautioned","inclined"],"answer":3,"target":"prone"},{"n":6,"passage":"Among the great orchestras of the world, the Philadelphia Orchestra stands out for several reasons. One is the overall quality of its musicians, although it is especially renowned for its violin players. Another is the orchestra’s famous recordings of nineteenth-century music, including the nine symphonies of Ludwig von Beethoven. A third is the orchestra’s many international concert tours. For example, it was the first U.S. orchestra to visit China.","prompt":"In saying that this orchestra is especially renowned for its violinists, the author means that it","options":["has an unusual violin section.","is famous for the violin players.","has made a lot of recordings.","pays the violinists more money."],"answer":1,"target":""},{"n":7,"passage":"The body of scales or bracts of a cone contains the reproductive organs of certain flowerless plants. The cone, a distinguishing feature of pines and other evergreens, is crudely analogous to the flowers of other plants.","prompt":"The word analogous in the passage is closest in meaning to","options":["apparent","constant","speculative","similar"],"answer":3,"target":"analogous"},{"n":8,"passage":"Most physicians participate in continuing education to keep up with the massive amount of information being discovered each year in their fields. Many states require that physicians periodically prove that they have actively participated in continuing medical education in order to maintain their certification to practice medicine.","prompt":"The word periodically in the passage is closest in meaning to","options":["nominally","partially","persistently","regularly"],"answer":3,"target":"periodically"},{"n":9,"passage":"Peace pipes are the large, ornately decorated tobacco pipes of the Indians of eastern North America. They functioned as symbols of truce and were ceremonially smoked for purposes of binding or renewing alliances. Peace pipes attained so much symbolic importance that it was thought that smoking the pipe with others compelled everyone present to be united in friendship.","prompt":"The word compelled in the passage is closest in meaning to","options":["obliged","sheltered","shifted","dependable"],"answer":0,"target":"compelled"},{"n":10,"passage":"The Spanish conquerors attempted to replace Aztec medicine with their own. When Aztec medical personnel resisted they were killed and Spanish medicine intruded into Aztec culture. However, some elements of Spanish medicine were compatible with the folk medical practices and became part of a new folk system. Mexican folk medicine thrived, yet there were many regional differences.","prompt":"The word intruded in the passage is closest in meaning to","options":["enacted","imported","emphasized","imposed"],"answer":3,"target":"intruded"}]},{"lesson":24,"words":[{"word":"affordable","def_lines":[],"pos":"adj","definition":"able to be done, usually referring to something you can do without damage or loss","forms":[{"pos":"adv","word":"affordably"},{"pos":"v","word":"afford"}],"synonyms":["economical"],"examples":["The new dictionary is quite affordable.","He could afford the house because of current low interest rates."],"lesson":24,"id":"24-1"},{"word":"contaminated","def_lines":[],"pos":"adj","definition":"to make something impure by adding something dirty or a poisonous substance","forms":[{"pos":"v","word":"contaminate"},{"pos":"n","word":"contamination"}],"synonyms":["pollute"],"examples":["This contaminated water supply must be closed off to the public.","Bacteria and insects are frequently agents of food contamination."],"lesson":24,"id":"24-2"},{"word":"discernible","def_lines":[],"pos":"adj","definition":"noticeable; easily seen","forms":[{"pos":"adv","word":"discernibly"},{"pos":"v","word":"discern"},{"pos":"n","word":"discernment"}],"synonyms":["detectable"],"examples":["A feeling of anxiety was discernible among the members of the team.","The new student was unable to discern the humor of the teacher’s joke."],"lesson":24,"id":"24-3"},{"word":"flourishing","def_lines":[],"pos":"adj","definition":"active and growing; healthy","forms":[{"pos":"v","word":"flourish"}],"synonyms":["thriving"],"examples":["Small flourishing companies would be harmed by an increase in the minimum wage.","A young mind will flourish with the proper guidance."],"lesson":24,"id":"24-4"},{"word":"maintain","def_lines":[],"pos":"v","definition":"to support; to keep in good condition","forms":[{"pos":"n","word":"maintenance"}],"synonyms":["preserve"],"examples":["The building had to be renovated because it was not well maintained.","Proper maintenance of a car’s engine will preserve its performance and value."],"lesson":24,"id":"24-5"},{"word":"mediocre","def_lines":[],"pos":"adj","definition":"of average quality; not good or bad","forms":[{"pos":"n","word":"mediocrity"}],"synonyms":["average"],"examples":["This is a mediocre research report.","The mediocrity of his work was disappointing."],"lesson":24,"id":"24-6"},{"word":"negligible","def_lines":[],"pos":"v","definition":"to ignore; to give little attention","forms":[{"pos":"adv","word":"negligibly"},{"pos":"adj","word":"neglected"},{"pos":"adj","word":"neglectful"},{"pos":"adj","word":"negligent"},{"pos":"n","word":"neglect"},{"pos":"n","word":"negligence"},{"pos":"v","word":"neglect"},{"pos":"adj","word":"hardly noticeable; scarcely detectable"}],"synonyms":["insignificant"],"examples":["The amount of bacteria in the culture was negligible.","His negligence caused him to lose all of the work he had done on the computer."],"lesson":24,"id":"24-7"},{"word":"parallel","def_lines":[],"pos":"adj","definition":"being almost of the same type or time; comparable","forms":[{"pos":"v","word":"parallel"}],"synonyms":["similar"],"examples":["There were many parallels between his life and mine.","Her background parallels mine."],"lesson":24,"id":"24-8"},{"word":"peculiar","def_lines":[],"pos":"adj","definition":"unusual; uncommon","forms":[{"pos":"adv","word":"peculiarly"},{"pos":"n","word":"peculiarity"}],"synonyms":["strange"],"examples":["This plastic has a peculiar texture.","The puffin has many peculiarities not shared by other birds."],"lesson":24,"id":"24-9"},{"word":"potent","def_lines":[],"pos":"adj","definition":"very strong","forms":[],"synonyms":["powerful"],"examples":["He gave a potent speech at the convention.","The venom of the coral snake is extremely potent."],"lesson":24,"id":"24-10"},{"word":"remarkable","def_lines":[],"pos":"adj","definition":"worthy of mention; uncommon","forms":[{"pos":"adv","word":"remarkably"}],"synonyms":["exceptional"],"examples":["The invention of the radio was a remarkable achievement.","The actor was remarkably calm before his performance."],"lesson":24,"id":"24-11"},{"word":"scattered","def_lines":[],"pos":"adj","definition":"spread out or separated widely","forms":[{"pos":"v","word":"scatter"}],"synonyms":["dispersed"],"examples":["Hurricane Andrew left debris scattered throughout Miami.","The crowd scattered when it began to rain heavily."],"lesson":24,"id":"24-12"},{"word":"solid","def_lines":[],"pos":"adj","definition":"having good quality; being well made, firm; not a gas or liquid","forms":[{"pos":"adv","word":"solidly"},{"pos":"v","word":"solidify"},{"pos":"n","word":"solidification"}],"synonyms":["steady"],"examples":["The lawyer for the defense portrayed his client as a man of solid integrity.","The union attempted to solidify its position in the workplace."],"lesson":24,"id":"24-13"},{"word":"somewhat","def_lines":[],"pos":"adj","definition":"a little","forms":[],"synonyms":["slight"],"examples":["They feel somewhat tired after the mile run.","Buying food at a convenience store can be somewhat expensive."],"lesson":24,"id":"24-14"},{"word":"stem from","def_lines":[],"pos":"ph. v","definition":"to emerge or develop from something","forms":[],"synonyms":["originate"],"examples":["The author’s talent in writing stems from his love of reading books.","Many opportunities have stemmed from his decision to attend the university."],"lesson":24,"id":"24-15"},{"word":"tedious","def_lines":[],"pos":"adj","definition":"long and tiring","forms":[{"pos":"adv","word":"tediously"},{"pos":"n","word":"tedium"}],"synonyms":["monotonous"],"examples":["The tedious lecture bored most of the audience.","Some people become frustrated by the tedium of daily living."],"lesson":24,"id":"24-16"}],"matching":[{"n":1,"word":"discernible","options":["exceptional","detectable","solid","negligent"],"answer":1},{"n":2,"word":"average","options":["ample","approximate","slight","mediocre"],"answer":3},{"n":3,"word":"originate","options":["stem from","preserve","maintain","disperse"],"answer":0},{"n":4,"word":"potent","options":["powerful","reliable","firm","durable"],"answer":0},{"n":5,"word":"affordable","options":["remarkable","formidable","economical","proportional"],"answer":2},{"n":6,"word":"similar","options":["prophetic","substantial","parallel","varied"],"answer":2},{"n":7,"word":"strange","options":["peculiar","vanishing","somewhat","renowned"],"answer":0},{"n":8,"word":"negligible","options":["exceptional","intricate","insignificant","scattered"],"answer":2},{"n":9,"word":"thriving","options":["flourishing","vanishing","polluting","astounding"],"answer":0},{"n":10,"word":"monotonous","options":["ambiguous","hazardous","prosperous","tedious"],"answer":3}],"tests":[{"n":1,"passage":"The Ceratosaurus, a genus of large carnivorous dinosaurs found as fossils in Late Jurassic rocks of North America, was similar to, and possibly closely related to, the Allosaurus. Ceratosaurus weighed up to 2 tons. This dinosaur was somewhat smaller than Allosaurus. It had a distinctive horn on its snout, a row of bony plates down the middle of its back, and four clawed fingers rather than three.","prompt":"The word somewhat in the passage is closest in meaning to","options":["potently","uniquely","slightly","peculiarly"],"answer":2,"target":"somewhat"},{"n":2,"passage":"The countries of Scandinavia were influenced by the spirit of improvement prevalent throughout Europe during the eighteenth century, but showed less advanced agriculture than others. Danish farmers were somewhat slowed in using new methods because of political restrictions. It was not until the end of the nineteenth century that solid advances in farming techniques occurred.","prompt":"The word solid in the passage is closest in meaning to","options":["sluggish","negligible","mediocre","substantial"],"answer":3,"target":"solid"},{"n":3,"passage":"Tourists throng to Baltimore’s Inner Harbor year-round. The Inner Harbor was built in an area that was once a contaminated industrial port. This area underwent rapid development in the 1980s. It is now a waterside array of high-fashion stores, new hotels, outdoor performances, moving boats, docked ships, and locales for eating and drinking.","prompt":"The word contaminated in the passage is closest in meaning to","options":["deserted","polluted","dangerous","flourishing"],"answer":1,"target":"contaminated"},{"n":4,"passage":"The Northwest Territories are Canada’s most sparsely settled area. Most settlements consist of only a few hundred people. About two- thirds of Canada’s Inuit Eskimos live there, scattered throughout the Arctic sector. Most Europeans who live in this territory live in the Mackenzie Valley.","prompt":"The word scattered in the passage is closest in meaning to","options":["maintained","sheltered","organized","distributed"],"answer":3,"target":"scattered"},{"n":5,"passage":"Plastics are a vast group of synthetic materials whose structures are based on the chemistry of carbon. They are also called polymers because they are made of extremely long chains of carbon atoms. An important characteristic of plastics is that they can be readily molded into finished products by the application of heat. As a finished product, one of its well-known properties includes remarkable resistance to heat.","prompt":"The word remarkable in the passage is closest in meaning to","options":["periodic","proportional","exceptional","practical"],"answer":2,"target":"remarkable"},{"n":6,"passage":"Extensive water storage is peculiar to a class of animals called ruminants. The class includes sheep and cattle, but the class member best known for storing water is the camel. There are two types of camel, the single-humped dromedary and the double-humped Bactrian camel found in the dry steppes of central Asia. The ability of these animals to store water makes them the ideal beasts of burden on long treks across the desert.","prompt":"In saying that extensive water storage is peculiar to ruminants, the author means that","options":["only these animals have this capacity.","camels have an unusual appearance.","desert life is difficult for most animals.","camels store water in their humps."],"answer":0,"target":""},{"n":7,"passage":"As computer systems improve, databases will play an increasingly important role as sources of information for the general public. As databases become more refined, the need for awareness of a particular database will become more important. Users will need to be able to discern how reliable information coming from a database is.","prompt":"The word discern in the passage is closest in meaning to","options":["maintain","account","determine","classify"],"answer":2,"target":"discern"},{"n":8,"passage":"The late 1970s and 1980s were years of delirious skyscraper construction. This was found in the cities that experienced economic progress, such as Dallas, Houston, and Atlanta in the southern United States, and also Hong Kong, Bangkok, and Singapore. Although New Yorkers, in particular, had reason to complain that the building of mediocre skyscrapers was choking Manhattan, few distinguished profiles were added to the skylines of modern cities.","prompt":"The word mediocre in the passage is closest in meaning to","options":["average","renowned","functional","contemporary"],"answer":0,"target":"mediocre"},{"n":9,"passage":"The deserts of the world are distributed in a pair of parallel belts lying approximately 25 degrees north and south of the equator. Of these, the world’s largest desert is found in the Northern Hemisphere. The Sahara and smaller deserts, forming much of the arid portion of the Middle East, are located in high-pressure regions directly influenced by global circulation of the atmosphere.","prompt":"The word parallel in the passage is closest in meaning to","options":["proportional","noticeable","broad","similar"],"answer":3,"target":"parallel"},{"n":10,"passage":"The life of the Atlantic salmon is typical of all salmon. The young fish leave the streams of their origin and disperse into the feeding water of the cold seas. When they are sexually mature they return to their home streams. In early summer, vast numbers of fish can be observed in their run upstream. It is not known how the right river system and the specific nesting sites are identified, but research indicates that the fish sense a chemical code peculiar to their home stream.","prompt":"The word peculiar in the passage is closest in meaning to","options":["arbitrary","distinctive","mysterious","intricate"],"answer":1,"target":"peculiar"}]},{"lesson":25,"words":[{"word":"briefly","def_lines":[],"pos":"adv","definition":"short, usually in time","forms":[{"pos":"adj","word":"brief"},{"pos":"n","word":"brevity"}],"synonyms":["concisely"],"examples":["The visiting professor spoke briefly at the faculty meeting.","Solar eclipses are brief moments when the Earth and Moon cross the Sun’s fixed position in the solar system."],"lesson":25,"id":"25-1"},{"word":"circulate","def_lines":[],"pos":"v","definition":"to cause to move along a fixed path; move freely","forms":[{"pos":"adj","word":"circulatory"},{"pos":"n","word":"circulation"}],"synonyms":["distribute"],"examples":["The news of the president’s visit circulated quickly throughout the city.","A dollar bill remains in circulation for approximately one and a half years."],"lesson":25,"id":"25-2"},{"word":"consistently","def_lines":[],"pos":"adv","definition":"without changing; keeping the same principles, ideas, or quality","forms":[{"pos":"adj","word":"consistent"},{"pos":"v","word":"consist"},{"pos":"n","word":"consistency"}],"synonyms":["dependably"],"examples":["The temperature must be maintained consistently at 75° centigrade.","The policy of the government concerning unemployment has been consistent."],"lesson":25,"id":"25-3"},{"word":"exhibit","def_lines":[],"pos":"v","definition":"to show or demonstrate","forms":[{"pos":"n","word":"exhibit"},{"pos":"n","word":"exhibition"},{"pos":"n","word":"exhibitor"}],"synonyms":["display"],"examples":["The compound exhibits the qualities of an acid.","It was the best exhibition of talent that I have ever seen."],"lesson":25,"id":"25-4"},{"word":"found","def_lines":[],"pos":"v","definition":"to establish; start up; *a philanthropic organization","forms":[{"pos":"n","word":"foundation*"},{"pos":"n","word":"founder"}],"synonyms":["establish"],"examples":["The wealthy woman founded a hospital in her hometown.","The foundation maintained a number of philanthropic activities."],"lesson":25,"id":"25-5"},{"word":"improperly","def_lines":[],"pos":"adv","definition":"not following established rules; not desirable","forms":[{"pos":"adj","word":"improper"},{"pos":"n","word":"impropriety"}],"synonyms":["inappropriately"],"examples":["The disappointing outcome was a result of an improperly prepared petri dish.","There was an impropriety with the way the funds were spent."],"lesson":25,"id":"25-6"},{"word":"impulsively","def_lines":[],"pos":"adv","definition":"acting without thinking","forms":[{"pos":"adj","word":"impulsive"},{"pos":"n","word":"impulse"},{"pos":"n","word":"impulsiveness"}],"synonyms":["capriciously"],"examples":["She reacted impulsively to the loud noise.","Many shoppers buy items on impulse."],"lesson":25,"id":"25-7"},{"word":"infrequently","def_lines":[],"pos":"adj","definition":"almost never","forms":[{"pos":"adj","word":"infrequent"},{"pos":"n","word":"infrequency"}],"synonyms":["rarely"],"examples":["Tornadoes occur infrequently in the eastern part of the United States.","Deserts are characterized by their infrequent rainfall."],"lesson":25,"id":"25-8"},{"word":"isolated","def_lines":[],"pos":"adj","definition":"to keep separated from others","forms":[{"pos":"v","word":"isolate"},{"pos":"n","word":"isolation"}],"synonyms":["secluded"],"examples":["The failure of the communications system left the towns isolated.","The doctors were unable to isolate the cause of the epidemic."],"lesson":25,"id":"25-9"},{"word":"overtly","def_lines":[],"pos":"adv","definition":"in a way clearly seen; not done secretly","forms":[{"pos":"adj","word":"overt"}],"synonyms":["openly"],"examples":["He overtly disregarded the regulations.","Her overt attempt to take control of the discussion failed."],"lesson":25,"id":"25-10"},{"word":"profoundly","def_lines":[],"pos":"adv","definition":"in a deep way; showing deep knowledge of a subject","forms":[{"pos":"adj","word":"profound"},{"pos":"n","word":"profundity"}],"synonyms":["significantly"],"examples":["Everyone was profoundly impressed by the news reports.","The Nobel Prize is a profound recognition of outstanding achievement."],"lesson":25,"id":"25-11"},{"word":"sharply","def_lines":[],"pos":"adv","definition":"showing sensitivity or quick thinking; showing a quick change in direction","forms":[{"pos":"adj","word":"sharp"},{"pos":"v","word":"sharpen"},{"pos":"n","word":"sharpness"}],"synonyms":["quickly"],"examples":["Car prices rose sharply over the past year.","There was a sharp change in the humidity after the storm."],"lesson":25,"id":"25-12"},{"word":"situated","def_lines":[],"pos":"adj","definition":"being found in a certain place *a current condition","forms":[{"pos":"n","word":"situation*"},{"pos":"v","word":"situate"}],"synonyms":["located"],"examples":["The resort town of Cancun is situated in the northern part of the Yucatan peninsula.","They found themselves in a very difficult situation."],"lesson":25,"id":"25-13"},{"word":"subsequently","def_lines":[],"pos":"adv","definition":"following; coming after something","forms":[{"pos":"adj","word":"subsequent"}],"synonyms":["afterward"],"examples":["The public applauded the president’s actions and subsequently his ratings in the polls improved.","This report, and all subsequent reports, must be written in the appropriate style."],"lesson":25,"id":"25-14"},{"word":"unmistakable","def_lines":[],"pos":"adj","definition":"clearly able to be determined","forms":[{"pos":"adj","word":"unmistakably"}],"synonyms":["indisputable"],"examples":["The markings of the insect provided for an unmistakable identification of the species.","It is unmistakably clear that the report must be finished by noon."],"lesson":25,"id":"25-15"},{"word":"upstanding","def_lines":[],"pos":"adj","definition":"marked by integrity; good, honest","forms":[{"pos":"n","word":"upstandingness"}],"synonyms":["moral"],"examples":["The school only accepts upstanding young adults.","The neighborhood has been kept clean and beautiful thanks to its upstanding residents."],"lesson":25,"id":"25-16"}],"matching":[{"n":1,"word":"consistently","options":["dependably","significantly","readily","diligently"],"answer":0},{"n":2,"word":"capriciously","options":["impulsively","profoundly","reluctantly","scarcely"],"answer":0},{"n":3,"word":"moral","options":["diligent","outstanding","generic","upstanding"],"answer":3},{"n":4,"word":"circulated","options":["sharpened","distributed","maintained","encircled"],"answer":1},{"n":5,"word":"briefly","options":["rarely","reliably","concisely","severely"],"answer":2},{"n":6,"word":"exhibited","options":["displayed","founded","located","highlighted"],"answer":0},{"n":7,"word":"overtly","options":["entirely","openly","evenly","actually"],"answer":1},{"n":8,"word":"inappropriately","options":["disapprovingly","approximately","improperly","unintentionally"],"answer":2},{"n":9,"word":"secluded","options":["situated","isolated","established","shifted"],"answer":1},{"n":10,"word":"indisputably","options":["severely","infrequently","significantly","unmistakably"],"answer":3}],"tests":[{"n":1,"passage":"The colossal Statue of Liberty is situated in New York harbor on a small island park near Ellis Island. Standing 302 feet high including its base, it shows a woman holding a torch in her raised right hand. In her left, there is a tablet proclaiming liberty, bearing the date July 4, 1776. An elevator rises to the balcony level, and a spiral staircase leads to a observation platform in the statue’s crown.","prompt":"The word situated in the passage is closest in meaning to","options":["visited","exhibited","isolated","located"],"answer":3,"target":"situated"},{"n":2,"passage":"In its earliest forms, astrology consisted of simple omens that astrologers interpreted from the celestial bodies in the sky. In its developed form, astrology analyzes the presumed effects of the Sun, Moon, planets, and stars on the Earth for a specific time and place. Astrologists also contend that the position of constellations at the moment of your birth profoundly influences your future.","prompt":"The word profoundly in the passage is closest in meaning to","options":["subsequently","significantly","unmistakably","consistently"],"answer":1,"target":"profoundly"},{"n":3,"passage":"When a language is devised as a means of communication between persons having no language in common, it is called a lingua franca. This lingua franca is native to none of those using it. A lingua franca with a sharply reduced grammar and vocabulary is called a pidgin. When a whole speech community gives up its former language or languages and takes a pidgin as its native tongue, the pidgin becomes a creole.","prompt":"The word sharply in the passage is closest in meaning to","options":["severely","overtly","impulsively","improperly"],"answer":0,"target":"sharply"},{"n":4,"passage":"Cedarwood is a light, soft, resinous, and durable wood, even when it makes contact with soil or moisture. It is an important timber used in construction in regions where it is found, but is infrequently used elsewhere. Many varieties of the Atlas cedar are popular ornamental trees in North America, especially along the Pacific and Gulf coasts.","prompt":"The word infrequently in the passage is closest in meaning to","options":["rarely","briefly","selectively","continually"],"answer":0,"target":"infrequently"},{"n":5,"passage":"In 1876 the Johns Hopkins University was founded in Baltimore as the first U.S. institution to incorporate the German ideal of university education. Since that time, graduate education has become an important aspect of many institutions. Older universities, such as Harvard and Yale, and newer ones, such as Stanford and Chicago, have embraced the aims of advanced learning conducted in a spirit of freedom and autonomy.","prompt":"The word founded in the passage is closest in meaning to","options":["erected","distinguished","criticized","established"],"answer":3,"target":"founded"},{"n":6,"passage":"Recent studies in psychology have explored the reasons why some purchases are made on impulse while others are given a significant amount of forethought. One finding is that shoppers are more likely to impulsively buy clothes than garden tools. It suggests that buying on impulse is strongly related to shoppers’ attitudes about themselves and to their “self-images.” Useful objects such as garden tools engage shoppers less personally than items that enhance their appearance.","prompt":"In discussing purchases made on impulse, the author is referring to purchases that shoppers make","options":["after weighing all the pluses and minuses.","on a moment’s notice and without thinking.","in boutiques rather than department stores.","to alter the feelings of people around them."],"answer":1,"target":""},{"n":7,"passage":"The Adventures of Huckleberry Finn by Mark Twain can be interpreted on several levels. On the surface, it is a picturesque novel in which young Huck Finn relates his adventures as he travels down the Mississippi River with a runaway slave named Jim. On another level, it is a societal satire on the constraints of civilization. Huckleberry Finn becomes a study of nature’s indifference; the river, like society, is sometimes benevolent, sometimes malicious, and always impulsive.","prompt":"The word impulsive in the passage is closest in meaning to","options":["abundant","baffling","capricious","philanthropic"],"answer":2,"target":"impulsive"},{"n":8,"passage":"Because of New Zealand’s location, there was no higher animal life in the country when the Maori arrived. There were two species of lizard: the gecko, and the tuatara, a reptile that was extinct everywhere else for 100,000,000 years. There were also a few primitive species of frogs and two species of bats. These are all living today, but are confined to outlying islands and isolated parts of the country.","prompt":"The word isolated in the passage is closest in meaning to","options":["secluded","negligible","protected","unlikely"],"answer":0,"target":"isolated"},{"n":9,"passage":"The American painter Frank Duveneck was an important influence on other American artists of his generation. In 1870, he went to Munich to study at the Royal Academy, where he had a brief acquaintance with William Merritt Chase. Duveneck was an admirer of the realism of Gustave Courbet, but his Munich work also shows how well he had assimilated the masterful brushwork and the skill in capturing expressions of the Dutch portraitist Frans Hals.","prompt":"The word brief in the passage is closest in meaning to","options":["thriving","fleeting","superficial","fertile"],"answer":1,"target":"brief"},{"n":10,"passage":"A dramatic monologue is a speech of long duration made by a character to a second person. In fiction, an interior monologue is a type of monologue that exhibits the thoughts, feelings, and associations passing through a character’s mind.","prompt":"The word exhibits in the passage is closest in meaning to","options":["clarifies","examines","displays","answers"],"answer":2,"target":"exhibits"}]},{"lesson":26,"words":[{"word":"chaotic","def_lines":[],"pos":"adj","definition":"being in complete disorder and confusion","forms":[{"pos":"n","word":"chaos"}],"synonyms":["disorganized"],"examples":["The traffic in Seoul is often chaotic.","There was complete chaos when the world champions arrived at the airport."],"lesson":26,"id":"26-1"},{"word":"controversial","def_lines":[],"pos":"adj","definition":"causing disagreement or argument","forms":[{"pos":"adv","word":"controversially"},{"pos":"n","word":"controversy"}],"synonyms":["divisive"],"examples":["The governor made a controversial decision to raise taxes.","The controversy was caused by the proposal to build an airport in the area."],"lesson":26,"id":"26-2"},{"word":"exemplify","def_lines":[],"pos":"v","definition":"to give an example","forms":[{"pos":"adj","word":"exemplary"}],"synonyms":["symbolize"],"examples":["The recent downturn in the housing industry exemplifies the poor economic conditions.","Her exemplary academic achievement is representative of most students at this institution."],"lesson":26,"id":"26-3"},{"word":"factor in","def_lines":[],"pos":"ph. v","definition":"to account for something while making a decision or analysis","forms":[],"synonyms":["consider"],"examples":["The family had to factor in the price of gasoline as they planned their road trip.","The architect did not factor in the required distance from the sidewalk in his design."],"lesson":26,"id":"26-4"},{"word":"gratifying","def_lines":[],"pos":"adj","definition":"giving pleasure or a feeling of accomplishment; showing thanks","forms":[{"pos":"adv","word":"gratefully"},{"pos":"adj","word":"grateful"},{"pos":"v","word":"gratify"},{"pos":"n","word":"gratification"},{"pos":"n","word":"gratefulness"}],"synonyms":["satisfying"],"examples":["Studying abroad can be a very gratifying experience.","She was grateful for all the work he had done for her."],"lesson":26,"id":"26-5"},{"word":"interpret","def_lines":[],"pos":"v","definition":"to understand the meaning of something","forms":[{"pos":"n","word":"interpreter"},{"pos":"n","word":"interpretation"},{"pos":"n","word":"interpreting"}],"synonyms":["clarify"],"examples":["The ambiguous speech was very difficult to interpret.","Their interpretation of the story generated some interesting discussion."],"lesson":26,"id":"26-6"},{"word":"launch","def_lines":[],"pos":"v","definition":"to cause something to begin","forms":[{"pos":"n","word":"launch"},{"pos":"n","word":"launching"}],"synonyms":["initiate"],"examples":["The company launched a new program to attract more clients.","The launching of the first Soviet Sputnik created concern among the American public."],"lesson":26,"id":"26-7"},{"word":"legitimate","def_lines":[],"pos":"adj","definition":"reasonable; lawful","forms":[{"pos":"adv","word":"legitimately"},{"pos":"n","word":"legitimacy"}],"synonyms":["authentic"],"examples":["The engineer had a legitimate reason for changing the design of the building.","The legitimacy of the theory has yet to be determined."],"lesson":26,"id":"26-8"},{"word":"lethargy","def_lines":[],"pos":"n","definition":"a lack of energy or commitment; lazy; indifferent","forms":[{"pos":"adj","word":"lethargic"},{"pos":"adv","word":"lethargically"}],"synonyms":["sluggishness"],"examples":["The hippopotamus basking in the sun displayed almost total lethargy.","When it is time to do homework assignments, many students become lethargic."],"lesson":26,"id":"26-9"},{"word":"particular","def_lines":[],"pos":"adj","definition":"a certain way or thing; unusual; hard to please; *especially","forms":[{"pos":"adv","word":"particularly*"}],"synonyms":["specific"],"examples":["The speaker has a particular way of persuading his audience.","That group of workers is particularly difficult to satisfy."],"lesson":26,"id":"26-10"},{"word":"radiant","def_lines":[],"pos":"adj","definition":"sending out in all directions, especially heat or light","forms":[{"pos":"adv","word":"radiantly"},{"pos":"n","word":"radiance"},{"pos":"n","word":"radiation"},{"pos":"n","word":"radiator"}],"synonyms":["bright"],"examples":["The actor’s radiant smile captivated the audience.","The radiance of the fire prevented the firefighters from entering the house."],"lesson":26,"id":"26-11"},{"word":"ridge","def_lines":[],"pos":"n","definition":"the top of a mountain range; a raised part of any surface","forms":[],"synonyms":["crest"],"examples":["A bald eagle stood on the ridge of the tall office building.","The mountain ridge was heavily forested."],"lesson":26,"id":"26-12"},{"word":"span","def_lines":[],"pos":"v","definition":"the length of time or distance from one limit to the other; to cross","forms":[{"pos":"n","word":"span"}],"synonyms":["cover"],"examples":["The old man’s life spanned two centuries.","The span of the bridge is three miles."],"lesson":26,"id":"26-13"},{"word":"spontaneous","def_lines":[],"pos":"adj","definition":"unplanned; uncontrolled","forms":[{"pos":"adv","word":"spontaneously"},{"pos":"n","word":"spontaneity"}],"synonyms":["instinctive"],"examples":["The spontaneous combustion inside the cylinder creates the power of the motor.","The crowd reacted spontaneously to the danger."],"lesson":26,"id":"26-14"},{"word":"stream","def_lines":[],"pos":"n","definition":"a natural flow of something; a pouring out","forms":[{"pos":"v","word":"stream"}],"synonyms":["river"],"examples":["There was a constant stream of information coming from the White House.","Water streamed from the dam as workers attempted to make the repairs."],"lesson":26,"id":"26-15"},{"word":"striking","def_lines":[],"pos":"adj","definition":"drawing special attention to","forms":[{"pos":"adv","word":"strikingly"}],"synonyms":["remarkable"],"examples":["His striking proposal saved the company from bankruptcy.","That was a strikingly convincing argument that the speaker delivered."],"lesson":26,"id":"26-16"}],"matching":[{"n":1,"word":"gratifying","options":["spontaneous","thriving","satisfying","analogous"],"answer":2},{"n":2,"word":"disorganized","options":["disrupted","chaotic","instinctive","discernible"],"answer":1},{"n":3,"word":"factor in","options":["compile","tolerate","consist","consider"],"answer":3},{"n":4,"word":"launch","options":["initiate","isolate","compel","stream"],"answer":0},{"n":5,"word":"lethargic","options":["spontaneous","analogous","sluggish","conscientious"],"answer":2},{"n":6,"word":"symbolize","options":["radiate","exemplify","span","synthesize"],"answer":1},{"n":7,"word":"legitimate","options":["peculiar","authentic","sharp","subsequent"],"answer":1},{"n":8,"word":"ridge","options":["crest","current","stream","radiance"],"answer":0},{"n":9,"word":"interpret","options":["specify","investigate","clarify","initiate"],"answer":2},{"n":10,"word":"radiant","options":["covered","bright","potent","tedious"],"answer":1}],"tests":[{"n":1,"passage":"In the communications and computer fields, research in optical switching is motivated by the need to transmit data streams at constantly higher speeds more efficiently. At the same time, customers demand transmission and switching rates far higher than can be provided by a purely electronic system. Due to developments in semiconductor lasers and in fiber optics, transmission at higher speeds is now possible.","prompt":"The word streams in the passage is closest in meaning to","options":["flows","pieces","files","particles"],"answer":0,"target":"streams"},{"n":2,"passage":"A striking example of a successful multiethnic country is Switzerland, where French, German, and Italian speakers from diverse religious groups live and work in harmony and prosperity. Ethnic diversity in Switzerland appears to have stimulated rather than divided the Swiss population. Studies of conditions in Switzerland demonstrate that harmony can coexist with diversity when certain characteristics are shared.","prompt":"The word striking in the passage is closest in meaning to","options":["spontaneous","characteristic","legitimate","remarkable"],"answer":3,"target":"striking"},{"n":3,"passage":"In one of the most influential books on education ever written, Émile Rousseau argued that society should protect children from the corrupt nature of civilization and cautiously nurture their natural, spontaneous impulses, which, in Rousseau’s mind, were always healthy. He further maintained that it was important to avoid premature intellectualization of emotion so that the child’s intellect could develop without distortion.","prompt":"The word spontaneous in the passage is closest in meaning to","options":["chaotic","gratifying","instinctive","uninterrupted"],"answer":2,"target":"spontaneous"},{"n":4,"passage":"The water available to fulfill a particular need is known as the water supply. When the need is domestic, industrial, or agricultural, the water must fulfill both quality and quantity requirements. Water supplies can be acquired by several types of water resources projects, such as dams, reservoirs, or wells.","prompt":"The word particular in the passage is closest in meaning to","options":["critical","common","gratifying","specific"],"answer":3,"target":"particular"},{"n":5,"passage":"Joseph Haydn was undoubtedly the most prolific of all symphony writers; his works spanned what has been called the Classical Era. He is most celebrated for taking the established forms of the symphony and shaping them into the forceful media for musical expression through invention and experimentation. These were recognized as innovations by composers who followed.","prompt":"The word spanned in the passage is closest in meaning to","options":["exemplified","covered","launched","interpreted"],"answer":1,"target":"spanned"},{"n":6,"passage":"Writing more than 2,500 years ago, the Greek historian Herodotus claimed that it took 100,000 people 20 years to build Khufu, one of the largest pyramids in Egypt. However, Herodotus visited Egypt almost 2,700 years after Khufu was built, and historical facts are always open to interpretation anyway. Modern Egyptologists estimate that it took as few as 5,000 men to quarry the stone, haul it to the site, and assemble the pyramid.","prompt":"In stating that historical facts are always open to interpretation, the author means that they","options":["are changed with the passage of time.","can be analyzed in a variety of ways.","are facts and therefore indisputable.","accumulate slowly throughout history."],"answer":1,"target":""},{"n":7,"passage":"An intaglio is an engraved gem that, when pressed into softened wax, produces an image in relief. This wax seal was once used as a means to identify legitimate letters and documents. The first engraving of hard stones existed as early as about 4000 B.C. in Mesopotamia, but the style of typical intaglios, which were usually mounted on rings, was developed by the ancient Greeks.","prompt":"The word legitimate in the passage is closest in meaning to","options":["normalize","authentic","robust","secure"],"answer":1,"target":"legitimate"},{"n":8,"passage":"In the late 1920s and early 1930s, the trucking industry was quite chaotic. It was dominated by large numbers of itinerant owner- operators. The industry was considered to be unstable and in need of regulation. The National Industrial Recovery Act of 1933 brought together two organized groups of trucking officials to develop standards of fair competition. This action led to the formation of the American Trucking Associations.","prompt":"The word chaotic in the passage is closest in meaning to","options":["disorganized","inordinate","formidable","imposing"],"answer":0,"target":"chaotic"},{"n":9,"passage":"Singapore is the only nation outside of mainland China and Taiwan where the majority of the population is ethnic Chinese. Its culture exemplifies this Chinese heritage, coupled with various diverse cultural influences. Its British colonial architecture and Chinese, Hindu, and Muslim shrines reflect the cultural diversity found in this international setting.","prompt":"The word exemplifies in the passage is closest in meaning to","options":["symbolizes","radiates","shelters","cultivates"],"answer":0,"target":"exemplifies"},{"n":10,"passage":"The field of opera once belonged exclusively to the Europeans. Successful American opera seemed to be confined to Gershwin’s Porgy and Bess and other obscure operatic works. More recently the opera world has witnessed growth in successful operatic works by Americans. In addition, new opera companies and small opera groups have been established. These developments are particularly gratifying to those who favor bringing a more American flavor to the opera stage.","prompt":"The word gratifying in the passage is closest in meaning to","options":["prophetic","remarkable","bizarre","satisfying"],"answer":3,"target":"gratifying"}]},{"lesson":27,"words":[{"word":"aptly","def_lines":[],"pos":"adv","definition":"having a tendency to do something; likely","forms":[{"pos":"adj","word":"apt"},{"pos":"n","word":"aptness"}],"synonyms":["appropriately"],"examples":["It was an aptly timed remark.","Emotional problems are apt to damage personal relationships."],"lesson":27,"id":"27-1"},{"word":"demonstration","def_lines":[],"pos":"n","definition":"a show or exhibit *overtly showing emotion","forms":[{"pos":"adv","word":"demonstrably"},{"pos":"v","word":"demonstrate"},{"pos":"adj","word":"demonstrative*"},{"pos":"adj","word":"demonstrable"}],"synonyms":["display"],"examples":["The demonstration clarified the procedure for everyone.","I have never seen the politicians so demonstrative of their feelings."],"lesson":27,"id":"27-2"},{"word":"ingredients","def_lines":[],"pos":"n","definition":"things combined to make something; the contents of something","forms":[],"synonyms":["elements"],"examples":["The ingredients of the product are kept secret.","Good style, punctuation, and grammar are the important ingredients of a good essay."],"lesson":27,"id":"27-3"},{"word":"involuntarily","def_lines":[],"pos":"adv","definition":"in an unthinking manner; not chosen","forms":[{"pos":"adj","word":"involuntary"}],"synonyms":["automatically"],"examples":["He involuntarily worked overtime.","Reflexes are involuntary reactions to external stimuli."],"lesson":27,"id":"27-4"},{"word":"marvel","def_lines":[],"pos":"n","definition":"something that surprises or impresses","forms":[{"pos":"adv","word":"marvelously"},{"pos":"adj","word":"marvelous"}],"synonyms":["wonder"],"examples":["The Great Wall of China is one of the world’s marvels.","The weather was marvelous for an afternoon get-together in the park."],"lesson":27,"id":"27-5"},{"word":"moderate","def_lines":[],"pos":"adj","definition":"not too much, not too little; *to reduce","forms":[{"pos":"adv","word":"moderately"},{"pos":"v","word":"moderate*"},{"pos":"n","word":"moderation"}],"synonyms":["medium"],"examples":["She made the best of her moderate dancing ability.","The Broadway play was moderately successful."],"lesson":27,"id":"27-6"},{"word":"motivate","def_lines":[],"pos":"v","definition":"to provide a reason or purpose for doing something","forms":[{"pos":"n","word":"motivation"},{"pos":"adj","word":"motivated"}],"synonyms":["encourage"],"examples":["Grades motivate most students to do well in their studies.","The speaker gave a motivational speech that inspired everyone in the audience."],"lesson":27,"id":"27-7"},{"word":"odd","def_lines":[],"pos":"adj","definition":"unusual","forms":[{"pos":"adv","word":"oddly"},{"pos":"n","word":"oddity"}],"synonyms":["strange"],"examples":["It is odd to find a person who speaks many languages.","The moon rock is an oddity available at the museum for all to view."],"lesson":27,"id":"27-8"},{"word":"profuse","def_lines":[],"pos":"adj","definition":"to be very generous, often in excess","forms":[{"pos":"n","word":"profuseness"},{"pos":"adv","word":"profusely"}],"synonyms":["abundant"],"examples":["The company apologized profusely for the defects in its product.","She deserved the profuse praise from her teacher."],"lesson":27,"id":"27-9"},{"word":"reflection","def_lines":[],"pos":"n","definition":"a picture or element thrown back","forms":[{"pos":"adj","word":"reflected"},{"pos":"v","word":"reflect"}],"synonyms":["image"],"examples":["His bright smile was a reflection of his satisfaction.","In order for us to perceive something visually, light must be reflected from the object’s surface."],"lesson":27,"id":"27-10"},{"word":"succinct","def_lines":[],"pos":"adj","definition":"short and to the point","forms":[{"pos":"adv","word":"succinctly"}],"synonyms":["concise"],"examples":["Since she had little time to speak, the biologist made her presentation succinct.","The class assignment is to summarize the book’s plot as succinctly as possible."],"lesson":27,"id":"27-11"},{"word":"supposedly","def_lines":[],"pos":"adv","definition":"according to reports or hearsay; widely believed or accepted","forms":[{"pos":"adj","word":"supposed"},{"pos":"v","word":"suppose"},{"pos":"n","word":"supposition"}],"synonyms":["presumably"],"examples":["The new trains are supposedly able to reach speeds of 150 miles per hour.","The stockbroker’s supposition is that the economy will improve."],"lesson":27,"id":"27-12"},{"word":"sustained","def_lines":[],"pos":"adj","definition":"continuing in a constant way; remaining strong","forms":[{"pos":"v","word":"sustain"},{"pos":"adj","word":"sustenance"}],"synonyms":["consistent"],"examples":["Sustained rainfall is the only hope they have for relief from the drought.","Luckily, the trees did not sustain any damage from the attack of the locusts."],"lesson":27,"id":"27-13"},{"word":"symbols","def_lines":[],"pos":"n","definition":"signs or objects that represent something or somebody","forms":[{"pos":"adv","word":"symbolically"},{"pos":"adj","word":"symbolic"},{"pos":"v","word":"symbolize"}],"synonyms":["marks"],"examples":["The strange symbols found in Egyptian tombs have intrigued historians for centuries.","This painting symbolizes the universal themes of humanity."],"lesson":27,"id":"27-14"},{"word":"synthesis","def_lines":[],"pos":"n","definition":"the mixing of separate things to form a whole; *not made by nature","forms":[{"pos":"adv","word":"synthetically*"},{"pos":"adj","word":"synthetic*"},{"pos":"v","word":"synthesize"}],"synonyms":["combination"],"examples":["The language of Papiamento is a synthesis of Dutch and native Indian languages of Curaçao.","Vitamins are synthetically produced."],"lesson":27,"id":"27-15"},{"word":"tangible","def_lines":[],"pos":"adj","definition":"real; that which can be felt","forms":[{"pos":"adv","word":"tangibly"},{"pos":"n","word":"tangibility"}],"synonyms":["concrete"],"examples":["The work of a teacher seldom produces tangible results until years after a student has graduated.","The solution to this problem can be tangibly demonstrated."],"lesson":27,"id":"27-16"}],"matching":[{"n":1,"word":"marvel","options":["ridge","chaos","wonder","combination"],"answer":2},{"n":2,"word":"display","options":["disperse","decline","disguise","demonstration"],"answer":3},{"n":3,"word":"succinct","options":["odd","moderate","strange","concise"],"answer":3},{"n":4,"word":"appropriately","options":["supposedly","aptly","tangibly","durably"],"answer":1},{"n":5,"word":"moderate","options":["sustained","medium","sharp","periodic"],"answer":1},{"n":6,"word":"involuntary","options":["infrequent","substantial","automatic","immeasurable"],"answer":2},{"n":7,"word":"elements","options":["ingredients","measurements","marks","spans"],"answer":0},{"n":8,"word":"motivate","options":["travel","isolate","sustain","encourage"],"answer":3},{"n":9,"word":"reflection","options":["image","synthesis","solid","tightness"],"answer":0},{"n":10,"word":"tangible","options":["firm","consistent","concrete","tedious"],"answer":2}],"tests":[{"n":1,"passage":"The mechanical traps of various carnivorous plants can be observed in many varieties. However, the snap trap, such as that found on the Venus Flytrap, is found only in the sundew family of plants. When an animal touches its sensory hairs, the prey is trapped by a rapid automatic closure of a set of lobes that surround the animal. After that, the digestion process starts. Any insect that lands on the Venus Flytrap will become a meal for the plant.","prompt":"The word automatic in the passage is closest in meaning to","options":["temporary","incessant","involuntary","impartial"],"answer":2,"target":"automatic"},{"n":2,"passage":"In the Western world, contemplation on art began with the philosophers of ancient Greece. Plato discussed proportion as the source of beauty, and imitation as the primary mode of art. Aristotle identified different kinds of imitation, and Xenocrates wrote technical dissertations on painting and sculpture that examined the ideal synthesis of proportion and imitation in terms of the lives of classical Greek artists.","prompt":"The word synthesis in the passage is closest in meaning to","options":["image","symbolism","display","combination"],"answer":3,"target":"synthesis"},{"n":3,"passage":"Anthropologists who study human communication tend to focus on its central role in the survival of a society. Communication serves to preserve and transmit the undefined aspects of a culture. Society communicates culture through significant symbols. These are embodied in language and represent the concepts of honor, bravery, love, cooperation, and honesty.","prompt":"The word symbols in the passage is closest in meaning to","options":["marvels","signs","patterns","exaggerations"],"answer":1,"target":"symbols"},{"n":4,"passage":"Based on the inscriptions called codices, linguists believe that the Maya spoke a language closely related to modern Native American groups. During the classical period, the Maya also had sustained contact with warriors and traders from Teotihuacan in central Mexico, the largest and most powerful state of the era. There is no proof of a conquest, but the Maya embraced some foreign deities, symbols, and styles of clothing of other groups.","prompt":"The word sustained in the passage is closest in meaning to","options":["tangible","consistent","moderate","measurable"],"answer":1,"target":"sustained"},{"n":5,"passage":"The Oregon Trail followed the Sweetwater River westward from the vicinity of Casper to South Pass. Independence Rock, a granite monolith on the north bank of the river near a reservoir, was a significant trail landmark. The river was supposedly named by General William Ashley in 1823 because its water tasted sweet to his trappers.","prompt":"The word supposedly in the passage is closest in meaning to","options":["presumably","oddly","aptly","predictably"],"answer":0,"target":"supposedly"},{"n":6,"passage":"At 46,000 gross tons, the Titanic was the largest floating object ever built. It was 853 feet long, 93 feet wide, and 61 feet high. As many people said, it was aptly named the Titanic—in ancient Greek mythology, the Titans ruled the universe until Zeus defeated and replaced them. The mighty Titanic was also overthrown: while carrying over 2,200 passengers, it crashed into an iceberg off Newfoundland and sank on April 14, 1912.","prompt":"In stating that the Titanic was aptly named, the author means that","options":["the ship’s captain was criminally negligent.","there were too many passengers on board.","the ship’s name, Titanic, was appropriate.","the word Titanic comes from Greek history."],"answer":2,"target":""},{"n":7,"passage":"The date of the earliest UFO sighting in history is unknown and the evidence for such sightings is scanty and purely speculative. The beginning of the UFO phenomenon began with the sighting of dirigiblelike “mystery ships” over the United States in 1896–1897. In 1946, people in Scandinavia reported large-scale sightings of “ghost rockets,” odd-looking “rockets” that made no noise. None of these phenomena has been satisfactorily explained.","prompt":"The word odd in the passage is closest in meaning to","options":["strange","ample","intriguing","elusive"],"answer":0,"target":"odd"},{"n":8,"passage":"A living cell is a marvel of detailed and complex structure. When examined with a microscope, it gives the appearance of almost chaotic activity. On a deeper level, it is known that molecules are being synthesized at a tremendous rate. Almost any enzyme causes the synthesis of more than 100 other molecules per second. In 10 minutes, a large percentage of the total mass of a metabolizing bacterial cell has been synthesized.","prompt":"The word marvel in the passage is closest in meaning to","options":["invention","wonder","magnification","swiftness"],"answer":1,"target":"marvel"},{"n":9,"passage":"In the 1790s, a variety of agricultural machinery was developed. At that time, an efficient seed drill had been designed but still required demonstrations in the 1830s to convince farmers of its value. A few threshing machines were in use before 1800, and gradually increased in popularity. However, in the 1830s, farm laborers in England rebelled because the machines deprived them of winter employment.","prompt":"The word demonstrations in the passage is closest in meaning to","options":["illustrations","circulations","displays","preconceptions"],"answer":2,"target":"demonstrations"},{"n":10,"passage":"The oxygen supply in the Earth’s atmosphere is a result of photosynthesis by green plants. Plants require all the essential ingredients of photosynthesis to build the vital compounds and structures. Water is required, because cell enlargement is a result of internal water pressure extending the walls. This explains why in periods of drought, plants tend to have smaller leaves.","prompt":"The word ingredients in the passage is closest in meaning to","options":["characteristics","parts","basics","elements"],"answer":3,"target":"ingredients"}]},{"lesson":28,"words":[{"word":"aggravating","def_lines":[],"pos":"adj","definition":"making worse; annoying","forms":[{"pos":"n","word":"aggravation"},{"pos":"v","word":"aggravate"}],"synonyms":["irritating"],"examples":["The aggravating delay was caused by road repairs.","The shortage of work aggravated the crisis in the small town."],"lesson":28,"id":"28-1"},{"word":"amusement","def_lines":[],"pos":"n","definition":"something that holds interest and is enjoyable","forms":[{"pos":"adv","word":"amusingly"},{"pos":"adj","word":"amusing"},{"pos":"v","word":"amuse"}],"synonyms":["diversion"],"examples":["We listened in amusement as he tried to convince his friend to lend him $50.","His amusing comment made everyone laugh."],"lesson":28,"id":"28-2"},{"word":"conceivably","def_lines":[],"pos":"adv","definition":"feasibly; believably","forms":[{"pos":"adj","word":"conceivable"},{"pos":"v","word":"conceive"}],"synonyms":["possibly"],"examples":["They could conceivably earn first place with their science project.","It is conceivable that humans will travel to distant planets one day."],"lesson":28,"id":"28-3"},{"word":"convert","def_lines":[],"pos":"v","definition":"to change from one form or state to another","forms":[{"pos":"adj","word":"convertible"},{"pos":"n","word":"conversion"}],"synonyms":["alter"],"examples":["When boiled, liquids convert into gases.","The conversion from Fahrenheit to centigrade can be easily made."],"lesson":28,"id":"28-4"},{"word":"curative","def_lines":[],"pos":"adj","definition":"being able to restore to good condition","forms":[{"pos":"n","word":"cure"}],"synonyms":["healing"],"examples":["The curative properties of certain plants have been well documented.","There is no simple cure for the ills of society."],"lesson":28,"id":"28-5"},{"word":"debilitating","def_lines":[],"pos":"adj","definition":"weakening","forms":[{"pos":"n","word":"debility"},{"pos":"v","word":"debilitate"}],"synonyms":["weakening"],"examples":["The lack of investment savings has a debilitating effect on the economy.","The patient’s debility limited his mobility."],"lesson":28,"id":"28-6"},{"word":"deplete","def_lines":[],"pos":"v","definition":"to use up; reduce greatly","forms":[{"pos":"adj","word":"depleted"},{"pos":"n","word":"depletion"}],"synonyms":["consume"],"examples":["She depleted all of her savings to buy the word processor.","The depletion of the Earth’s oil reserves poses a threat to our current way of life."],"lesson":28,"id":"28-7"},{"word":"finite","def_lines":[],"pos":"adj","definition":"of a certain amount; having an end; not infinite","forms":[],"synonyms":["limited"],"examples":["There are a finite number of explanations for the unusual results.","Is there a finite number of stars in the universe?"],"lesson":28,"id":"28-8"},{"word":"perceive","def_lines":[],"pos":"v","definition":"to sense; become aware of","forms":[{"pos":"adv","word":"perceptibly"},{"pos":"adj","word":"perceivable"},{"pos":"adj","word":"perceptive"},{"pos":"adv","word":"perceptively"},{"pos":"n","word":"perception"}],"synonyms":["observe"],"examples":["We perceive major differences between the two political parties.","Porpoises are very perceptive mammals."],"lesson":28,"id":"28-9"},{"word":"security","def_lines":[],"pos":"n","definition":"the feeling of freedom from danger, doubt, or worry","forms":[{"pos":"adv","word":"securely"},{"pos":"adj","word":"secure"},{"pos":"v","word":"secure"}],"synonyms":["safety"],"examples":["Her sense of security increased as her grades improved.","We secured all of the doors of the lab before leaving."],"lesson":28,"id":"28-10"},{"word":"take on","def_lines":[],"pos":"ph. v","definition":"to accept a task; to deal with something","forms":[],"synonyms":["undertake"],"examples":["Certain programs take on the task of protecting a computer from harmful Internet viruses.","The athlete enjoys taking on new fitness challenges."],"lesson":28,"id":"28-11"},{"word":"toxic","def_lines":[],"pos":"adj","definition":"harmful; capable of being fatal","forms":[{"pos":"n","word":"toxicity"}],"synonyms":["poisonous"],"examples":["Disposal of toxic wastes is an ongoing environmental issue.","This product has the highest toxicity of any known to science."],"lesson":28,"id":"28-12"},{"word":"tranquility","def_lines":[],"pos":"n","definition":"calm; quietness","forms":[{"pos":"adv","word":"tranquilly"},{"pos":"adj","word":"tranquil"},{"pos":"v","word":"tranquilize"}],"synonyms":["peacefulness"],"examples":["The tranquility of the lake at sunrise inspired a profound sense of well- being.","His tranquil manner of expression made us all feel more secure."],"lesson":28,"id":"28-13"},{"word":"trap","def_lines":[],"pos":"v","definition":"to catch and hold onto, usually by trickery; deceived","forms":[{"pos":"adj","word":"trapped"},{"pos":"n","word":"trap"}],"synonyms":["retain"],"examples":["I was trapped into paying for the meal.","The trapped animals were released after being tagged by the wildlife conservationists."],"lesson":28,"id":"28-14"},{"word":"undeniably","def_lines":[],"pos":"adv","definition":"clearly true","forms":[{"pos":"adj","word":"undeniable"}],"synonyms":["absolutely"],"examples":["Of all the planets in our solar system, the Earth is undeniably the most conducive to supporting life.","It is undeniable that he has skill, but he needs to show more initiative."],"lesson":28,"id":"28-15"},{"word":"underestimated","def_lines":[],"pos":"adj","definition":"guessed lower than the actual quantity","forms":[{"pos":"v","word":"underestimate"}],"synonyms":["miscalculated"],"examples":["The underestimated demand for tickets made the theater manager plan better for the next performance.","The treasurer underestimated the cost of the new furniture."],"lesson":28,"id":"28-16"}],"matching":[{"n":1,"word":"curative","options":["healing","gratifying","toxic","conceivable"],"answer":0},{"n":2,"word":"limited","options":["sustained","ample","finite","approximate"],"answer":2},{"n":3,"word":"amusement","options":["peacefulness","demonstration","diversion","marvel"],"answer":2},{"n":4,"word":"security","options":["power","safety","trap","cure"],"answer":1},{"n":5,"word":"debilitating","options":["convincing","formidable","accelerating","weakening"],"answer":3},{"n":6,"word":"undertake","options":["take on","bring about","stem from","factor in"],"answer":0},{"n":7,"word":"conceivably","options":["absolutely","aptly","possibly","tranquilly"],"answer":2},{"n":8,"word":"alter","options":["sustain","launch","foster","convert"],"answer":3},{"n":9,"word":"depleted","options":["retained","consumed","polluted","inundated"],"answer":1},{"n":10,"word":"perceive","options":["deny","miscalculate","observe","estimate"],"answer":2}],"tests":[{"n":1,"passage":"Less than one percent of all freight cargo is carried by air, most being carried by surface methods. Nevertheless, this curious fact significantly underestimates the importance of air freight. In terms of value of cargo carried, air transport is greater than all other modes. By the early 1990s Tokyo’s Narita Airport and New York’s John F. Kennedy Airport were handling in excess of one million tons of cargo per year.","prompt":"The word underestimates in the passage is closest in meaning to","options":["understands","assesses","highlights","miscalculates"],"answer":3,"target":"underestimates"},{"n":2,"passage":"Margaret Mead, a well-known cultural anthropologist, was associated with the American Museum of Natural History in New York City from 1926 until her death. In the 1980s, her work, in particular her famous study of Samoa, became a subject of controversy. Her critics alleged that her belief in the predominate influence of culture in shaping personality led her to misread evidence and overgeneralize. Her defenders endorsed her undeniably keen observations.","prompt":"The word undeniably in the passage is closest in meaning to","options":["absolutely","inconsistently","presumably","unexpectedly"],"answer":0,"target":"undeniably"},{"n":3,"passage":"Ice, a nearly pure solid, contains few foreign ions in its structure. It contains particles of matter and gases, which are trapped in bubbles in the ice. A change in makeup of these materials over time is recorded in the successive layers of ice. This has been used to interpret the history of the environment of Earth’s surface and the influence of human activities on this environment.","prompt":"The word trapped in the passage is closest in meaning to","options":["found","reflected","retained","converted"],"answer":2,"target":"trapped"},{"n":4,"passage":"Wang Wei was a Chinese poet, painter, and scholar of the Tang dynasty. He left behind both a significant body of lyrical poetry and delicately depicted landscape paintings. These paintings reflected a love of nature and an inner tranquility derived from Buddhism and meditation. He is traditionally credited with founding the Southern school of Chinese landscape painting.","prompt":"The word tranquility in the passage is closest in meaning to","options":["peacefulness","amusement","fulfillment","security"],"answer":0,"target":"tranquility"},{"n":5,"passage":"The problem of ocean pollution has been acknowledged at national and international levels. The U.S. Congress passed an act in 1988 that phased in a complete prohibition of ocean dumping by 1991. Also in 1988, 65 nations agreed to stop burning toxic waste at sea by 1994. The legality of the latter measure remains debatable and may be proven unenforceable, mirroring the experience of a 1977 law that attempted the same prohibition.","prompt":"The word toxic in the passage is closest in meaning to","options":["inordinate","debilitating","poisonous","dispersed"],"answer":2,"target":"toxic"},{"n":6,"passage":"Before Alexander Fleming made his great discovery, he had been studying losozyme, an enzyme found in tears that prevents infection. However, he wanted to find a substance with curative powers, something that would keep bacteria from growing and multiplying altogether. By accident, he noticed a mold growing in one of his laboratory dishes that had this effect. It turned out to be penicillin, one of the most widely used antibiotics today.","prompt":"In stating that Fleming wanted to find a substance with curative powers, the author means that he was looking for a medicine that would","options":["regulate a patient’s exposure to germs.","combat disease-causing bacteria.","control a patient’s body temperature.","increase a patient’s level of infection."],"answer":1,"target":""},{"n":7,"passage":"So-called prophetic dreams in ancient Middle Eastern cultures were often used to help the sick. In classical Greece, ailing people came to dream in special temples where priests and priestesses advised them about their dreams’ curative benefits. A similar practice known as dream incubation is known to have existed in the ancient cultures of Babylon and Egypt.","prompt":"The word curative in the passage is closest in meaning to","options":["corrective","fertile","healing","ample"],"answer":2,"target":"curative"},{"n":8,"passage":"Chronic fatigue syndrome is a disorder characterized by at least six months of debilitating fatigue that begins abruptly and is usually accompanied by mild fever, sore throat, tender muscles, joint pain, headache, sleep disorders, confusion, memory loss, and vision problems. Once considered an imagined rather than a specific physical condition, chronic fatigue syndrome remains controversial.","prompt":"The word debilitating in the passage is closest in meaning to","options":["weakening","disruptive","tangible","persistent"],"answer":0,"target":"debilitating"},{"n":9,"passage":"Fireworms are marine worms that inhabit warm tropical waters. They produce an aggravating stinging sensation if touched. One particular species, H. carunculata, found in the coral reefs of the Caribbean Sea, has a body covered with fine, white, brittle bristles that embed themselves in human skin if touched.","prompt":"The word aggravating in the passage is closest in meaning to","options":["disruptive","annoying","irritating","formidable"],"answer":2,"target":"aggravating"},{"n":10,"passage":"Scientists have tried to find a way to make hurricanes less dangerous by analyzing their component parts and neutralizing them. A hurricane contains huge quantities of supercooled water and silver iodide. Seeding the hurricane could conceivably produce some changes in storm behavior. Aircraft seeding experiments have obtained some minor, short-lived changes resulting in decreased wind speeds for a few hours.","prompt":"The word conceivably in the passage is closest in meaning to","options":["presumably","consistently","possibly","noticeably"],"answer":2,"target":"conceivably"}]},{"lesson":29,"words":[{"word":"acknowledge","def_lines":[],"pos":"v","definition":"to know, remember, and accept the existence of something","forms":[{"pos":"n","word":"acknowledgment"},{"pos":"adj","word":"acknowledged"}],"synonyms":["recognize"],"examples":["The foreman acknowledged the fact that there had been a mistake in the design of the house.","The promotion he received was an acknowledgment of his excellent work."],"lesson":29,"id":"29-1"},{"word":"acquire","def_lines":[],"pos":"v","definition":"to gain or come to possess","forms":[{"pos":"adj","word":"acquisitive"},{"pos":"n","word":"acquisition"}],"synonyms":["obtain"],"examples":["He acquired two beautiful paintings during his visit to Taipei.","The office’s most recent acquisition was a new photocopier."],"lesson":29,"id":"29-2"},{"word":"assimilate","def_lines":[],"pos":"v","definition":"to become a part of","forms":[{"pos":"n","word":"assimilation"}],"synonyms":["incorporate"],"examples":["The United States of America has assimilated people from all parts of the world.","Assimilation of a new cultural environment can be difficult."],"lesson":29,"id":"29-3"},{"word":"assortment","def_lines":[],"pos":"n","definition":"a variety","forms":[{"pos":"adj","word":"assorted"}],"synonyms":["selection"],"examples":["You have an assortment of elective courses from which to choose.","He bought a box of assorted books at the book fair."],"lesson":29,"id":"29-4"},{"word":"caliber","def_lines":[],"pos":"n","definition":"the standard of; the degree of goodness","forms":[],"synonyms":["quality"],"examples":["The high caliber of her work earned her a raise in pay.","Only parts of the highest caliber can be used to make repairs on the spacecraft."],"lesson":29,"id":"29-5"},{"word":"condensed","def_lines":[],"pos":"adj","definition":"made smaller; shortened; merge","forms":[{"pos":"v","word":"condense"}],"synonyms":["summarize"],"examples":["This is a condensed version of the original research report.","Try to condense the two chapters into one."],"lesson":29,"id":"29-6"},{"word":"contradictory","def_lines":[],"pos":"adj","definition":"not agreeing with the facts or previous statements made on the subject; declared wrong","forms":[{"pos":"v","word":"contradict"},{"pos":"n","word":"contradiction"}],"synonyms":["inconsistent"],"examples":["It is contradictory to say that you know French after studying it for only three months.","The expert contradicted himself during his presentation."],"lesson":29,"id":"29-7"},{"word":"disregard","def_lines":[],"pos":"v","definition":"to pay no attention","forms":[{"pos":"n","word":"disregard"}],"synonyms":["ignore"],"examples":["They disregarded the no parking signs and were ticketed by the police.","His disregard of the lab instructions caused him to make many errors."],"lesson":29,"id":"29-8"},{"word":"precious","def_lines":[],"pos":"adj","definition":"having much monetary or sentimental value; beautiful","forms":[],"synonyms":["cherished"],"examples":["This golden ring is my most precious possession.","The precious stone was one of a kind."],"lesson":29,"id":"29-9"},{"word":"prominent","def_lines":[],"pos":"adj","definition":"famous; having a high position","forms":[{"pos":"adv","word":"prominently"},{"pos":"n","word":"prominence"}],"synonyms":["renowned"],"examples":["Their talent for locating oil deposits made them prominent geologists in the corporation.","He gained prominence through his television appearances."],"lesson":29,"id":"29-10"},{"word":"requisite","def_lines":[],"pos":"adj","definition":"needed for a specific purpose; *a formal request","forms":[{"pos":"v","word":"require"},{"pos":"n","word":"requirement"},{"pos":"v","word":"requisition*"},{"pos":"n","word":"requisition*"}],"synonyms":["demanded"],"examples":["Here is the list of requisite courses for the master’s degree in biology.","The project team made a requisition for a new set of reference books."],"lesson":29,"id":"29-11"},{"word":"stable","def_lines":[],"pos":"adj","definition":"experiencing few or no changes; not moving","forms":[{"pos":"adv","word":"stably"},{"pos":"n","word":"stability"}],"synonyms":["steady"],"examples":["Be sure the ladder is stable before climbing it.","Most people believe that maintaining economic stability is an important goal of every government."],"lesson":29,"id":"29-12"},{"word":"unravel","def_lines":[],"pos":"v","definition":"to organize; make clear","forms":[{"pos":"n","word":"unraveling"}],"synonyms":["separate"],"examples":["The detective was not able to unravel the mystery of the missing money.","The unraveling of the Soviet Union took place in the span of a few months."],"lesson":29,"id":"29-13"},{"word":"vague","def_lines":[],"pos":"adj","definition":"not clear; ambiguous","forms":[{"pos":"adv","word":"vaguely"},{"pos":"n","word":"vagueness"}],"synonyms":["unclear"],"examples":["She has only vague memories of her childhood.","The vagueness of his directions caused us to get lost."],"lesson":29,"id":"29-14"},{"word":"vast","def_lines":[],"pos":"adj","definition":"very much; very large","forms":[{"pos":"adv","word":"vastly"}],"synonyms":["huge"],"examples":["I have noticed a vast improvement in your English vocabulary.","Unfortunately, the water quality has deteriorated vastly since my last visit here."],"lesson":29,"id":"29-15"},{"word":"volume","def_lines":[],"pos":"n","definition":"the amount of something contained in a space; *holding a lot","forms":[{"pos":"adv","word":"voluminously*"},{"pos":"adj","word":"voluminous*"}],"synonyms":["quantity"],"examples":["The volume of information that a flash drive can hold is astounding.","This voluminous report will erase your doubt about the financial condition of the company."],"lesson":29,"id":"29-16"}],"matching":[{"n":1,"word":"caliber","options":["volume","marvel","quality","acclaim"],"answer":2},{"n":2,"word":"ignore","options":["disregard","separate","deplete","withstand"],"answer":0},{"n":3,"word":"acknowledged","options":["exaggerated","recognized","exemplified","accentuated"],"answer":1},{"n":4,"word":"assortment","options":["assertion","selection","pattern","ingredient"],"answer":1},{"n":5,"word":"obtain","options":["acquire","unravel","relinquish","perceive"],"answer":0},{"n":6,"word":"steady","options":["stable","precious","staple","tangible"],"answer":0},{"n":7,"word":"condensed","options":["summarized","emphasized","legitimized","conformed"],"answer":0},{"n":8,"word":"assimilate","options":["illustrate","incorporate","investigate","isolate"],"answer":1},{"n":9,"word":"renown","options":["reaction","vast","prominent","requisite"],"answer":2},{"n":10,"word":"contradictory","options":["ambiguous","requisite","inconsistent","disregarded"],"answer":2}],"tests":[{"n":1,"passage":"By the end of 1998, the Internet’s World Wide Web had become so commonplace in the public consciousness that even nontechnical adults were likely to acknowledge having heard of the “Net” and the “Web.” Companies large and small began including a web-site address in their advertising. Furthermore, large telecommunications firms began offering their customers Internet access services.","prompt":"The word acknowledge in the passage is closest in meaning to","options":["deny","remember","concede","cherish"],"answer":2,"target":"acknowledge"},{"n":2,"passage":"Traditionally, the South Pacific Melanesians completed the requisite destruction of their art objects once their ceremonial purposes were achieved. Part of the artistic tradition included the need to destroy and then recreate art objects as ritualistic or social needs arose. As a result of this behavior, the Melanesian artistic tradition existed solely as an artistic concept in the mind of the artist who often worked without models of previous works.","prompt":"The word requisite in the passage is closest in meaning to","options":["required","renowned","reluctant","reliable"],"answer":0,"target":"requisite"},{"n":3,"passage":"Nuclear families of the preindustrial era were bound to a set of social obligations that made the nuclear family subordinate to the wishes of the larger family. This extended family system began to unravel with the advent of the Industrial Revolution. Aspirations for greater personal freedom and changing economic conditions produced a slow movement toward more independent nuclear families.","prompt":"The word unravel in the passage is closest in meaning to","options":["form","condense","assimilate","separate"],"answer":3,"target":"unravel"},{"n":4,"passage":"In 1941 President Franklin D. Roosevelt drafted The Four Freedoms. It was a list of basic human rights: freedom of speech and expression, freedom of worship, freedom from want, and freedom from fear. Later in the same year, these were incorporated into the Atlantic Charter, a British and American statement of goals for a peaceful world. Some leaders criticized The Four Freedoms for being too vague to serve as a guide for prudent statesmanship.","prompt":"The word vague in the passage is closest in meaning to","options":["contradictory","prominent","specific","unclear"],"answer":3,"target":"vague"},{"n":5,"passage":"The earliest-known handcrafted carpet, about 2,500 years old, was discovered in ice in a tomb at Pazyryk, Siberia. Rugs were also made in Persia approximately 200 years later during the reign of Cyrus, whose tomb was covered with precious carpets. By the sixteenth century, rug making was a highly developed craft in Persia and Turkey.","prompt":"The word precious in the passage is closest in meaning to","options":["fine","marvelous","intricate","astounding"],"answer":0,"target":"precious"},{"n":6,"passage":"A bar code is a tiny cluster of vertical lines and horizontal numbers against a white field found on many products today. This electronic code is not prominently displayed; rather, it is usually tucked away somewhere on the backside of the packaging. The digits in the code indicate the name and price of the product; more importantly, they help merchants maintain their stock by subtracting each purchase from the store’s inventory.","prompt":"In saying that bar codes are not prominently displayed, the author means that they","options":["cover most of the packaging.","can be scanned by a computer.","are invisible to the naked eye.","may be somewhat difficult to find."],"answer":3,"target":""},{"n":7,"passage":"Scientists believe that the volume of water in the oceans has not changed drastically during the last few hundred million years. This conclusion is drawn from evidence indicating that the interiors of the continents have never been covered by the oceans.","prompt":"The word volume in the passage is closest in meaning to","options":["quantity","proportions","magnitude","depth"],"answer":0,"target":"volume"},{"n":8,"passage":"The dynamic growth of communications networks after 1995, especially in the scholarly world, has accelerated the establishment of the “virtual library.” At the core of this development is public-domain information. Residing in databases distributed worldwide, a growing portion of this vast resource is now accessible almost immediately through the Internet.","prompt":"The word vast in the passage is closest in meaning to","options":["dense","huge","extensive","core"],"answer":1,"target":"vast"},{"n":9,"passage":"Discount stores sell products at prices lower than those found in conventional retail outlets. Some, such as department stores, offer wide assortments of goods. Other discount chains specialize, offering special types of merchandise such as jewelry, electronic equipment, or electrical appliances. Discount stores have become international phenomena. They have spread to Western Europe, Latin America, Australia, and Japan.","prompt":"The word assortments in the passage is closest in meaning to","options":["amusements","patterns","proportions","selections"],"answer":3,"target":"assortments"},{"n":10,"passage":"The major reasons for establishing a wildlife refuge are to acquire protection for a group of animals that have become significantly reduced in number and to suitably improve the habitat so that animals will breed and flourish. Often, restrictions or prohibitions are placed on development, hunting, trapping, trespassing, or fishing.","prompt":"The word acquire in the passage is closest in meaning to","options":["obtain","endorse","receive","access"],"answer":0,"target":"acquire"}]},{"lesson":30,"words":[{"word":"charisma","def_lines":[],"pos":"n","definition":"a special quality that endears other people to the person who has this quality","forms":[{"pos":"adj","word":"charismatic"}],"synonyms":["appeal"],"examples":["She has charisma that no other candidate possesses.","John F. Kennedy was known for his charismatic personality."],"lesson":30,"id":"30-1"},{"word":"clever","def_lines":[],"pos":"adj","definition":"intelligent; resourceful","forms":[{"pos":"adv","word":"cleverly"},{"pos":"n","word":"cleverness"}],"synonyms":["astute"],"examples":["Everyone appreciated their clever idea.","His cleverness enabled him to rise quickly in the organization."],"lesson":30,"id":"30-2"},{"word":"convince","def_lines":[],"pos":"v","definition":"to make someone see things your way","forms":[{"pos":"adv","word":"convincingly"},{"pos":"adj","word":"convincing"}],"synonyms":["persuade"],"examples":["They could not convince the girls to go to the dance with them.","The video made a convincing argument for the recycling of paper and plastic materials."],"lesson":30,"id":"30-3"},{"word":"endure","def_lines":[],"pos":"v","definition":"to last; suffer pain","forms":[{"pos":"adj","word":"endurable"},{"pos":"adj","word":"enduring"},{"pos":"n","word":"endurance"}],"synonyms":["persevere"],"examples":["How he is able to endure living next to the airport is beyond my comprehension.","The endurance displayed by the athlete gave evidence of his rigorous training."],"lesson":30,"id":"30-4"},{"word":"forfeit","def_lines":[],"pos":"v","definition":"to give up; have something taken away, usually by rule or regulation","forms":[{"pos":"n","word":"forfeit"}],"synonyms":["relinquish"],"examples":["Usually you must forfeit your native country’s citizenship to become a citizen of another country.","The forfeit occurred because not enough players showed up."],"lesson":30,"id":"30-5"},{"word":"precarious","def_lines":[],"pos":"adj","definition":"not safe, firm, or steady","forms":[{"pos":"adv","word":"precariously"}],"synonyms":["hazardous"],"examples":["The diver put himself in a precarious situation among the sharks.","The cup was positioned precariously on the edge of the table."],"lesson":30,"id":"30-6"},{"word":"severe","def_lines":[],"pos":"n","definition":"severity","forms":[{"pos":"adj","word":"extreme; harmful"},{"pos":"adv","word":"severely"}],"synonyms":["intense"],"examples":["The weather service issued a severe storm warning for most of Michigan.","The severity of his condition will not be known until the test results are studied."],"lesson":30,"id":"30-7"},{"word":"sporadic","def_lines":[],"pos":"adj","definition":"not consistent; irregular","forms":[{"pos":"adv","word":"sporadically"}],"synonyms":["erratic"],"examples":["The radio communications were subject to sporadic sunspot interference.","Violent storms occur sporadically in the Southwest."],"lesson":30,"id":"30-8"},{"word":"superior","def_lines":[],"pos":"adj","definition":"excellent quality; above all the rest","forms":[{"pos":"n","word":"superiority"}],"synonyms":["exceptional"],"examples":["This is a superior fossil of a trilobite.","The restaurant’s superiority was established shortly after it opened."],"lesson":30,"id":"30-9"},{"word":"truncate","def_lines":[],"pos":"v","definition":"to shorten; to end something suddenly","forms":[{"pos":"adj","word":"truncated"}],"synonyms":["cut"],"examples":["The television program was truncated because the soccer match went into extra time.","The publishers of the newspaper asked the writer to truncate her report."],"lesson":30,"id":"30-10"},{"word":"wanton","def_lines":[],"pos":"adj","definition":"done without thought or consideration; grossly negligent","forms":[{"pos":"adv","word":"wantonly"}],"synonyms":["senseless"],"examples":["Her wanton disregard of the rules was unexplainable.","The jealous man was wantonly impolite to the winner."],"lesson":30,"id":"30-11"},{"word":"weak","def_lines":[],"pos":"adj","definition":"not strong; incapable","forms":[{"pos":"adv","word":"weakly"},{"pos":"v","word":"weaken"},{"pos":"n","word":"weakness"}],"synonyms":["ineffective"],"examples":["The weak light was inadequate for reading.","Most people have at least one area of weakness."],"lesson":30,"id":"30-12"},{"word":"widespread","def_lines":[],"pos":"adj","definition":"found everywhere","forms":[],"synonyms":["extensive"],"examples":["There is a widespread rumor that there will be no class next Thursday.","The political influence of the developed countries of the world is widespread."],"lesson":30,"id":"30-13"},{"word":"wisdom","def_lines":[],"pos":"n","definition":"knowledge and understanding","forms":[{"pos":"adv","word":"wisely"},{"pos":"adj","word":"wise"}],"synonyms":["insight"],"examples":["It is often said that wisdom is the product of experience.","It was a wise decision for you to buy a car."],"lesson":30,"id":"30-14"},{"word":"witticism","def_lines":[],"pos":"n","definition":"a joke; a funny story","forms":[{"pos":"adv","word":"wittily"},{"pos":"adj","word":"witty"},{"pos":"n","word":"wit"},{"pos":"n","word":"wittiness"}],"synonyms":["humor"],"examples":["His witticisms captivated the audience.","Mark Twain was famous for his sharp wit."],"lesson":30,"id":"30-15"},{"word":"woo","def_lines":[],"pos":"v","definition":"to make efforts to attain or gain something","forms":[],"synonyms":["attract"],"examples":["The directors tried to woo the support of the union.","The opponents of the proposed highway wooed nearby residents to defend their position."],"lesson":30,"id":"30-16"}],"matching":[{"n":1,"word":"astute","options":["acknowledge","extensive","clever","weak"],"answer":2},{"n":2,"word":"sporadic","options":["prophetic","intrinsic","erratic","archaic"],"answer":2},{"n":3,"word":"relinquish","options":["recover","disperse","forfeit","deplete"],"answer":2},{"n":4,"word":"persevering","options":["enduring","ineffective","secure","sincere"],"answer":0},{"n":5,"word":"superior","options":["prosperous","sustained","superficial","exceptional"],"answer":3},{"n":6,"word":"truncate","options":["impress","cut","uphold","postpone"],"answer":1},{"n":7,"word":"precarious","options":["peculiar","dangerous","widespread","aggravating"],"answer":1},{"n":8,"word":"persuade","options":["convince","conform","confirm","conceal"],"answer":0},{"n":9,"word":"wisdom","options":["acceleration","insight","caution","marvel"],"answer":1},{"n":10,"word":"intense","options":["instant","hazardous","severe","robust"],"answer":2}],"tests":[{"n":1,"passage":"The circulation war of the tabloids that took place in New York City in the 1920s was copied in Britain in the 1930s. This brought numerous circulation-boosting schemes. Prizes for readers were introduced in the 1890s and had become popular measures to woo new subscribers by the 1900s. Although the practice was condemned by the Newspaper Proprietors’ Association, gift schemes grew along with the number of newspapers for many years. They continue today.","prompt":"The word woo in the passage is closest in meaning to","options":["forfeit","attract","convince","deceive"],"answer":1,"target":"woo"},{"n":2,"passage":"Intensity, intimacy, and omnipresence have been identified as the distinctive characteristics of the motion-picture image. Its intensity stems from its power to capture the complete attention of the theatergoer. Outside the theater, a person’s attention is usually divided among the elements of the limitless reality around him or her, except for sporadic moments of concentration on what is selected for closer examination.","prompt":"The word sporadic in the passage is closest in meaning to","options":["occasional","charismatic","recurrent","splendid"],"answer":0,"target":"sporadic"},{"n":3,"passage":"Established in 1942, the Voice of America is the international radio network of the U.S. Information Agency. Its charge is the widespread decree of a favorable understanding of the United States abroad. It achieves this task with a wide range of programs, including news, editorials, features, and music. The VOA has established a long-term modernization plan to increase its number of broadcasting languages from 42 to 60.","prompt":"The word widespread in the passage is closest in meaning to","options":["unlimited","discernible","extensive","alluring"],"answer":2,"target":"widespread"},{"n":4,"passage":"Jellyfish feed on organisms such as plankton, fish, and other jellyfish. They capture their prey by using nematocysts, small stinging organs found on their tentacles. Their movement is produced through rhythmic contractions of the bell’s perimeter surface, which discharges water. This causes water to move the animal forward by jet propulsion. Some varieties of jellyfish are able to swim well, but most are weak swimmers that drift with sea currents.","prompt":"The word weak in the passage is closest in meaning to","options":["ineffective","chaotic","harmful","agile"],"answer":0,"target":"weak"},{"n":5,"passage":"During his administration, Thomas Jefferson pursued a policy of expansion. He seized an opportunity when Napoleon Bonaparte decided to forfeit French ambitions in North America by offering the Louisiana Territory for sale. This remarkable acquisition, purchased for a few cents per acre, more than doubled the area of the United States. Jefferson had no constitutional right to complete the transaction. Nevertheless, he made up the rules as he went along, broadly interpreting the Constitution.","prompt":"The word forfeit in the passage is closest in meaning to","options":["accelerate","restrain","relinquish","disrupt"],"answer":2,"target":"forfeit"},{"n":6,"passage":"In some countries, high-speed driving is severely punished, while in others speed is ignored, tolerated, or encouraged. For example, French police fine drivers as much as 380 euros on the spot for driving more than 110 kilometers per hour, while the famous German expressway known as the “Autobahn” has no speed limit, although sections of it may have recommended limits. The lack of a speed limit and lighter police surveillance turn many drivers into skillful competitors.","prompt":"In stating that high-speed driving is severely punished, the author means that","options":["offenders are sure to be arrested at once.","exceeding the limit carries the death penalty.","authorities impose a large fine.","speeding is officially encouraged."],"answer":2,"target":""},{"n":7,"passage":"As a U.S. congressman, Davy Crockett won a reputation as a witty, shrewd, and outspoken backwoodsman. It was in Washington that the legend of this man as a coonskin-hatted bear hunter and tall-tale teller was created. There, his political allies promoted this image so he could compete with President Jackson’s image as a democrat.","prompt":"The word witty in the passage is closest in meaning to","options":["robust","scattered","humorous","instinctive"],"answer":2,"target":"witty"},{"n":8,"passage":"The volcanic areas of southern Guatemala contain some of the nation’s most richest soils. However, the northern parts of this region are particularly subject to erosion encouraged by steep slopes and deforestation. Within the Sierra region, heavier rainfall combined with thinner soils on the steep slopes and the wanton destruction of forests have led to widespread erosion.","prompt":"The word wanton in the passage is closest in meaning to","options":["senseless","sustained","proportional","outlandish"],"answer":0,"target":"wanton"},{"n":9,"passage":"In all the Apache groups, the family structure was matrilocal. The women cared for the children, gathered plant food, and collected firewood and water. The men of the family hunted, fought, raided, and made weapons and shields. The most persuasive, tenacious, and successful family heads became Apache leaders. Those in authority were chosen because they had personal charisma and success in warfare.","prompt":"The word charisma in the passage is closest in meaning to","options":["obligations","fallacies","appeal","capriciousness"],"answer":2,"target":"charisma"},{"n":10,"passage":"Bishop Wright profoundly influenced the lives of his children. Wilbur and Orville, like their father, were independent thinkers. They had deep confidence in their own talents, and an unwavering faith in the soundness of their judgment. They were taught to endure difficulties and continue in the face of disappointment. Those qualities, when combined with their unique talents, help to explain the accomplishments of the Wright brothers as inventors.","prompt":"The word endure in the passage is closest in meaning to","options":["disguise","endorse","reject","persevere"],"answer":3,"target":"endure"}]}]};
